const ASSISTANT_MCP_MAX_CONTEXT_BYTES_ABSOLUTE = Math.max(1024, Number(process.env.CMDP_ASSISTANT_MCP_MAX_CONTEXT_BYTES_ABSOLUTE || 1048576) || 1048576);
