function normalizeLogLevel(value) {
  const text = String(value || '').trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(logLevelWeights, text) ? text : 'info';
}

function normalizeLogFormat(value) {
  const text = String(value || '').trim().toLowerCase();
  return text === 'text' ? 'text' : 'json';
}

function normalizeLogTargets(value) {
  const targets = String(value || 'stdout')
    .split(',')
    .map((item) => item.trim().toLowerCase())
    .filter(Boolean)
    .filter((item) => item === 'stdout' || item === 'syslog');
  const unique = targets.length ? Array.from(new Set(targets)) : ['stdout'];
  return unique.includes('stdout') ? unique : ['stdout', ...unique];
}

function parseNameSet(value) {
  return new Set(String(value || '')
    .split(',')
    .map((item) => item.trim().toLowerCase())
    .filter(Boolean));
}

function normalizeSyslogProtocol(value) {
  const text = String(value || '').trim().toLowerCase();
  return text === 'tcp' ? 'tcp' : 'udp';
}

function normalizeSyslogFacility(value) {
  const text = String(value || '').trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(syslogFacilityCodes, text) ? text : 'local0';
}

function normalizeSyslogPort(value) {
  const port = Number(value);
  return Number.isInteger(port) && port >= 1 && port <= 65535 ? port : 0;
}

function syslogHostIsConfigured(value) {
  const host = String(value || '').trim();
  if (!host || /[\s/]/.test(host)) return false;
  return !/^(replace-me|changeme|change-me|placeholder|example|syslog\.example\.local)$/i.test(host);
}

function normalizeDiagnosticMode(value) {
  const text = String(value || '').trim().toLowerCase();
  if (text === 'basic') return 'Basic';
  if (text === 'verbose') return 'Verbose';
  return 'off';
}

function normalizeLiteLLMBaseUrl(value) {
  const text = String(value || '').trim();
  if (!text) return '';
  try {
    const parsed = new URL(text);
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return '';
    parsed.hash = '';
    parsed.search = '';
    return parsed.toString().replace(/\/+$/, '');
  } catch {
    return '';
  }
}

function normalizeLiteLLMAllowedBaseUrls(value) {
  return Array.from(new Set(String(value || '')
    .split(',')
    .map(normalizeLiteLLMBaseUrl)
    .filter(Boolean)));
}

function liteLLMBaseUrlStatus(value) {
  const fallback = normalizeLiteLLMBaseUrl(LITELLM_BASE_URL);
  const requested = normalizeLiteLLMBaseUrl(value);
  if (!requested || requested === fallback) {
    return {
      baseUrl: fallback,
      requestedBaseUrl: requested,
      allowed: true,
      source: 'env'
    };
  }
  if (LITELLM_ALLOWED_BASE_URLS.includes(requested)) {
    return {
      baseUrl: requested,
      requestedBaseUrl: requested,
      allowed: true,
      source: 'runtimeConfig'
    };
  }
  return {
    baseUrl: fallback,
    requestedBaseUrl: requested,
    allowed: false,
    source: 'blocked'
  };
}

function diagnosticModeAllows(level, mode = DIAGNOSTIC_MODE) {
  const normalizedMode = normalizeDiagnosticMode(mode);
  const normalizedLevel = normalizeDiagnosticMode(level);
  if (normalizedLevel === 'off') return normalizedMode !== 'off';
  if (normalizedMode === 'Verbose') return normalizedLevel === 'Basic' || normalizedLevel === 'Verbose';
  return normalizedMode === 'Basic' && normalizedLevel === 'Basic';
}

function logLevelEnabled(level) {
  return (logLevelWeights[level] || logLevelWeights.info) >= (logLevelWeights[LOG_LEVEL] || logLevelWeights.info);
}

function redactByName(name, value, redactSet) {
  return redactSet.has(String(name || '').toLowerCase()) ? '[REDACTED]' : value;
}

function sanitizeUrlForLog(value, maxLength = 500) {
  const text = String(value || '');
  if (!text) return '';
  try {
    const parsed = text.startsWith('/') ? new URL(text, 'http://local') : new URL(text);
    const sanitizedPath = sanitizeRequestPath(parsed);
    return truncateText(parsed.origin === 'http://local' ? sanitizedPath : `${parsed.origin}${sanitizedPath}`, maxLength);
  } catch {
    return truncateText(text, maxLength);
  }
}

function sanitizeHeaderValue(name, value) {
  const normalized = String(name || '').toLowerCase();
  if (normalized === 'referer' || normalized === 'referrer') {
    return sanitizeUrlForLog(value, 500);
  }
  return truncateText(value, 300);
}

function sanitizeHeaders(headers) {
  const result = {};
  Object.entries(headers || {}).forEach(([name, value]) => {
    const normalized = String(name || '').toLowerCase();
    if (LOG_REDACT_HEADERS.has(normalized)) {
      result[name] = '[REDACTED]';
      return;
    }
    if (Array.isArray(value)) {
      result[name] = value.map((item) => sanitizeHeaderValue(name, item));
      return;
    }
    result[name] = sanitizeHeaderValue(name, value);
  });
  return result;
}

function sanitizeRequestPath(requestUrl) {
  const params = new URLSearchParams();
  requestUrl.searchParams.forEach((value, name) => {
    params.append(name, truncateText(redactByName(name, value, LOG_REDACT_QUERY), 200));
  });
  const query = params.toString();
  return truncateText(`${requestUrl.pathname}${query ? `?${query}` : ''}`, 1000);
}

function sanitizeReqUrl(req) {
  try {
    return sanitizeRequestPath(new URL(req.url || '/', `http://${req.headers.host || `${LISTEN_HOST}:${LISTEN_PORT}`}`));
  } catch {
    return truncateText(req.url || '', 1000);
  }
}

function sanitizeDiagnosticHref(value) {
  return sanitizeUrlForLog(value, 500);
}

function sessionHashFromCookie(cookieHeader) {
  const token = getCookieValue(cookieHeader, 'CMDBuild-Authorization');
  return token ? sha256Hex(token).slice(0, 16) : '';
}

function routeKind(pathname) {
  if (isHealthPath(pathname)) return 'health';
  if (isMetricsPath(pathname)) return 'metrics';
  if (pathname.startsWith(`${BACKEND_PREFIX}/`)) return 'backend';
  if (pathname === DYNAMIC_UI_PREFIX || pathname.startsWith(`${DYNAMIC_UI_PREFIX}/`)) return 'dynamic-ui';
  return 'cmdbuild-proxy';
}

function currentRequestId() {
  const store = requestContext.getStore();
  return store && store.requestId ? String(store.requestId) : '';
}

function httpTransportForTarget(target) {
  return target.protocol === 'https:' ? https : http;
}

function cmdbuildAgentForTarget(target) {
  return target.protocol === 'https:' ? cmdbuildHttpsAgent : cmdbuildHttpAgent;
}

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function cmdbuildRequestCanRetry(method, retryOption) {
  if (!CMDBUILD_RETRY_ENABLED || retryOption === false) return false;
  if (retryOption === true) return true;
  return ['GET', 'HEAD', 'OPTIONS'].includes(String(method || 'GET').toUpperCase());
}

function executionDeadlineTimeoutError(timeoutMs = DRAFT_PREVIEW_TIMEOUT_MS) {
  const error = new Error(`Draft preview timed out after ${timeoutMs}ms.`);
  error.code = 'draft_preview_timeout';
  error.statusCode = 504;
  return error;
}

function executionDeadlineRemainingMs(deadlineAt) {
  const deadline = Number(deadlineAt || 0);
  return Number.isFinite(deadline) && deadline > 0 ? deadline - Date.now() : Infinity;
}

function assertExecutionDeadline(deadlineAt, timeoutMs) {
  if (executionDeadlineRemainingMs(deadlineAt) <= 0) throw executionDeadlineTimeoutError(timeoutMs);
}

function shouldRetryCmdbuildResult(result) {
  const statusCode = Number(result && result.statusCode || 0);
  return statusCode === 408 ||
    statusCode === 429 ||
    statusCode === 500 ||
    statusCode === 502 ||
    statusCode === 503 ||
    statusCode === 504;
}

function cmdbuildRetryDelayMs(attempt, baseDelayMs = CMDBUILD_RETRY_BASE_DELAY_MS, maxDelayMs = CMDBUILD_RETRY_MAX_DELAY_MS, jitterRatio = 0.2) {
  const exponential = Math.min(maxDelayMs, baseDelayMs * (2 ** Math.max(0, Number(attempt || 1) - 1)));
  const jitter = jitterRatio > 0 ? Math.floor(exponential * jitterRatio * Math.random()) : 0;
  return Math.min(maxDelayMs, exponential + jitter);
}

function shouldStructuredLogRequest(pathname) {
  return isHealthPath(pathname) ||
    isMetricsPath(pathname) ||
    pathname.startsWith(`${BACKEND_PREFIX}/`) ||
    pathname === DYNAMIC_UI_PREFIX ||
    pathname.startsWith(`${DYNAMIC_UI_PREFIX}/`) ||
    shouldLogProxyRequest(pathname);
}

function syslogSeverity(level) {
  if (level === 'error') return 3;
  if (level === 'warn') return 4;
  if (level === 'debug') return 7;
  return 6;
}

function sendSyslog(payload) {
  const pri = (syslogFacilityCodes[SYSLOG_FACILITY] * 8) + syslogSeverity(payload.level);
  const message = `<${pri}>1 ${payload.time} ${os.hostname()} cmdbdynamicpages ${process.pid} ${payload.event || '-'} - ${JSON.stringify(payload)}`;
  if (SYSLOG_PROTOCOL === 'tcp') {
    const socket = net.createConnection({ host: SYSLOG_HOST, port: SYSLOG_PORT }, () => {
      socket.end(`${message}\n`);
    });
    socket.setTimeout(1000, () => socket.destroy());
    socket.on('error', (error) => {
      process.stderr.write(JSON.stringify({
        time: new Date().toISOString(),
        level: 'warn',
        event: 'logging.syslog_failed',
        error: error.message || String(error)
      }) + '\n');
    });
    return;
  }
  const socket = dgram.createSocket('udp4');
  socket.send(Buffer.from(message), SYSLOG_PORT, SYSLOG_HOST, (error) => {
    socket.close();
    if (error) {
      process.stderr.write(JSON.stringify({
        time: new Date().toISOString(),
        level: 'warn',
        event: 'logging.syslog_failed',
        error: error.message || String(error)
      }) + '\n');
    }
  });
}

function writeStructuredLog(level, event, fields = {}, options = {}) {
  const normalizedLevel = normalizeLogLevel(level);
  if (!options.force && !logLevelEnabled(normalizedLevel)) return;
  const payload = {
    time: new Date().toISOString(),
    level: normalizedLevel,
    service: 'cmdbdynamicpages',
    event,
    ...fields
  };
  if (LOG_TARGETS.includes('stdout')) {
    const line = LOG_FORMAT === 'text'
      ? `${payload.time} ${payload.level.toUpperCase()} ${payload.event} ${JSON.stringify(fields)}`
      : JSON.stringify(payload);
    const stream = normalizedLevel === 'error' ? process.stderr : process.stdout;
    stream.write(`${line}\n`);
  }
  if (LOG_TARGETS.includes('syslog')) sendSyslog(payload);
}

function logDiagnosticBasic(event, fields = {}) {
  if (!diagnosticModeAllows('Basic')) return;
  writeStructuredLog('info', `diagnostic.${event}`, {
    diagnosticMode: DIAGNOSTIC_MODE,
    ...fields
  }, { force: true });
}

function logDiagnosticVerbose(event, fields = {}) {
  if (!diagnosticModeAllows('Verbose')) return;
  writeStructuredLog('info', `diagnostic.${event}`, {
    diagnosticMode: DIAGNOSTIC_MODE,
    ...fields
  }, { force: true });
}

function logDebug(event, fields) {
  writeStructuredLog('debug', event, fields);
}

function logInfo(event, fields) {
  writeStructuredLog('info', event, fields);
}

function logWarn(event, fields) {
  writeStructuredLog('warn', event, fields);
}

function logError(event, fields) {
  writeStructuredLog('error', event, fields);
}

function parsePublicOriginConfiguration(value) {
  const rawValue = String(value || '').trim();
  if (!rawValue) {
    return {
      configured: false,
      valid: true,
      origin: '',
      reason: ''
    };
  }

  try {
    const parsed = new URL(rawValue);
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      return {
        configured: true,
        valid: false,
        origin: '',
        reason: 'protocol_must_be_http_or_https'
      };
    }
    if (parsed.username || parsed.password || parsed.pathname !== '/' || parsed.search || parsed.hash) {
      return {
        configured: true,
        valid: false,
        origin: '',
        reason: 'must_be_an_origin_without_credentials_path_query_or_fragment'
      };
    }
    return {
      configured: true,
      valid: true,
      origin: parsed.origin,
      reason: ''
    };
  } catch {
    return {
      configured: true,
      valid: false,
      origin: '',
      reason: 'must_be_a_valid_url'
    };
  }
}

function publicOriginStatus() {
  return {
    configured: PUBLIC_ORIGIN_CONFIGURATION.configured,
    origin: PUBLIC_ORIGIN || null,
    mode: PUBLIC_ORIGIN ? 'configured' : 'development_request_host_fallback'
  };
}

function loggingStatus() {
  return {
    level: LOG_LEVEL,
    format: LOG_FORMAT,
    targets: LOG_TARGETS,
    diagnostic: {
      mode: DIAGNOSTIC_MODE,
      enabled: DIAGNOSTIC_MODE !== 'off',
      levels: ['Basic', 'Verbose'],
      policy: {
        basic: 'safe structured diagnostic events without sensitive payloads',
        verbose: 'sanitized request and upstream diagnostics without request/response bodies'
      }
    },
    redactHeaders: Array.from(LOG_REDACT_HEADERS).sort(),
    redactQuery: Array.from(LOG_REDACT_QUERY).sort(),
    syslog: LOG_TARGETS.includes('syslog') ? {
      host: SYSLOG_HOST,
      port: SYSLOG_PORT,
      protocol: SYSLOG_PROTOCOL,
      facility: SYSLOG_FACILITY
    } : null,
    elk: {
      directOutput: false,
      recommendedPipeline: 'stdout/syslog -> collector -> Elasticsearch'
    },
    publicOrigin: publicOriginStatus(),
    assistant: assistantStatus(),
    d2: d2RendererConfigSummary()
  };
}

function validateRuntimeConfig(input = {}) {
  const nodeEnv = String(input.nodeEnv === undefined ? process.env.NODE_ENV || '' : input.nodeEnv || '').trim();
  const csrfSecret = String(input.csrfSecret === undefined ? process.env.CMDBDYNAMICPAGES_CSRF_SECRET || '' : input.csrfSecret || '').trim();
  const redisUrl = String(input.redisUrl === undefined ? REDIS_URL : input.redisUrl || '').trim();
  const redisEnabled = input.redisEnabled === undefined ? REDIS_ENABLED : input.redisEnabled !== false;
  const logTargets = input.logTargets || LOG_TARGETS;
  const syslogHost = String(input.syslogHost === undefined ? SYSLOG_HOST : input.syslogHost || '').trim();
  const syslogPort = normalizeSyslogPort(input.syslogPort === undefined ? SYSLOG_PORT : input.syslogPort);
  const syslogProtocol = normalizeSyslogProtocol(input.syslogProtocol === undefined ? SYSLOG_PROTOCOL : input.syslogProtocol);
  const diagnosticMode = normalizeDiagnosticMode(input.diagnosticMode === undefined ? DIAGNOSTIC_MODE : input.diagnosticMode);
  const publicOriginConfiguration = parsePublicOriginConfiguration(input.publicOrigin === undefined ? process.env.CMDP_PUBLIC_ORIGIN || '' : input.publicOrigin);
  const errors = [];
  const warnings = [];

  if (nodeEnv.toLowerCase() === 'production' && !csrfSecret) {
    errors.push({
      code: 'csrf_secret_required',
      env: 'CMDBDYNAMICPAGES_CSRF_SECRET',
      message: 'Production startup requires a stable external CSRF secret.'
    });
  }
  if (nodeEnv.toLowerCase() === 'production' && /^(replace-me|changeme|change-me|secret|password)$/i.test(csrfSecret)) {
    errors.push({
      code: 'csrf_secret_placeholder',
      env: 'CMDBDYNAMICPAGES_CSRF_SECRET',
      message: 'Production startup requires a non-placeholder CSRF secret.'
    });
  }

  if (!publicOriginConfiguration.valid) {
    errors.push({
      code: 'public_origin_invalid',
      env: 'CMDP_PUBLIC_ORIGIN',
      message: 'CMDP_PUBLIC_ORIGIN must be an http(s) origin without credentials, path, query, or fragment.',
      reason: publicOriginConfiguration.reason
    });
  } else if (nodeEnv.toLowerCase() === 'production' && !publicOriginConfiguration.configured) {
    errors.push({
      code: 'public_origin_required',
      env: 'CMDP_PUBLIC_ORIGIN',
      message: 'Production startup requires CMDP_PUBLIC_ORIGIN for same-origin browser requests.'
    });
  }

  let redisTransport = { transport: 'invalid', caConfigured: false };
  if (redisEnabled) {
    try {
      const redisConfig = parseRedisUrl(redisUrl);
      redisTransport = {
        transport: redisConfig.tls ? 'tls' : 'plaintext',
        caConfigured: Boolean(redisConfig.tlsCaFile)
      };
      if (redisConfig.tls && redisConfig.tlsCaFile && !fs.statSync(redisConfig.tlsCaFile).isFile()) {
        throw new Error('Redis TLS CA path is not a regular file.');
      }
    } catch (error) {
      errors.push({
        code: 'redis_url_invalid',
        env: 'CMDBDYNAMIC_REDIS_URL',
        message: error && error.message ? error.message : 'Redis URL is invalid.'
      });
    }
    if (nodeEnv.toLowerCase() === 'production' && redisTransport.transport === 'plaintext') {
      warnings.push({
        code: 'redis_plaintext_transport',
        env: 'CMDBDYNAMIC_REDIS_URL',
        message: 'Redis is configured without TLS. Prefer rediss:// for production deployments.'
      });
    }
  }

  if (!Array.isArray(logTargets) || !logTargets.includes('stdout')) {
    errors.push({
      code: 'stdout_log_target_required',
      env: 'CMDP_LOG_TARGET',
      message: 'Structured logs must always include stdout/stderr.'
    });
  }
  if (nodeEnv.toLowerCase() === 'production' && Array.isArray(logTargets) && !logTargets.includes('syslog')) {
    errors.push({
      code: 'syslog_log_target_required',
      env: 'CMDP_LOG_TARGET',
      message: 'Production startup requires CMDP_LOG_TARGET=stdout,syslog so structured logs are delivered to a configured syslog sink.'
    });
  }
  if (nodeEnv.toLowerCase() === 'production' && Array.isArray(logTargets) && logTargets.includes('syslog') && (!syslogHostIsConfigured(syslogHost) || !syslogPort)) {
    errors.push({
      code: 'syslog_configuration_required',
      env: 'CMDP_SYSLOG_HOST,CMDP_SYSLOG_PORT',
      message: 'Production syslog logging requires a non-placeholder CMDP_SYSLOG_HOST and a valid CMDP_SYSLOG_PORT.'
    });
  }

  if (diagnosticMode === 'Verbose' && nodeEnv.toLowerCase() === 'production') {
    warnings.push({
      code: 'verbose_diagnostic_in_production',
      env: 'CMDP_DIAGNOSTIC_MODE',
      message: 'Verbose diagnostics should be enabled only temporarily during an incident.'
    });
  }

  return {
    ok: errors.length === 0,
    nodeEnv,
    diagnosticMode,
    logTargets,
    syslog: {
      host: syslogHost,
      port: syslogPort,
      protocol: syslogProtocol
    },
    publicOrigin: publicOriginConfiguration.origin,
    publicOriginConfigured: publicOriginConfiguration.configured,
    redis: redisTransport,
    assistant: assistantStatus(),
    d2: d2RendererConfigSummary(),
    errors,
    warnings
  };
}

function runtimeConfigLogSummary(validation = validateRuntimeConfig()) {
  return {
    nodeEnv: validation.nodeEnv || 'development',
    diagnosticMode: validation.diagnosticMode,
    logTargets: validation.logTargets,
    syslog: validation.syslog || null,
    publicOrigin: validation.publicOrigin || '',
    publicOriginConfigured: Boolean(validation.publicOriginConfigured),
    redis: validation.redis || redisTransportSecurity(),
    d2: validation.d2 || d2RendererConfigSummary(),
    errors: validation.errors.map((item) => item.code),
    warnings: validation.warnings.map((item) => item.code)
  };
}

const metricDefinitions = {
  cmdp_http_requests_total: { type: 'counter', help: 'HTTP requests by route, method, and status class.' },
  cmdp_http_requests_aborted_total: { type: 'counter', help: 'HTTP requests aborted by the client before a response was completed.' },
  cmdp_http_request_duration_seconds_count: { type: 'counter', help: 'HTTP request duration observation count.' },
  cmdp_http_request_duration_seconds_sum: { type: 'counter', help: 'HTTP request duration sum in seconds.' },
  cmdp_cmdbuild_rest_requests_total: { type: 'counter', help: 'CMDBuild REST requests by method and status class.' },
  cmdp_cmdbuild_rest_errors_total: { type: 'counter', help: 'CMDBuild REST errors by method and status class.' },
  cmdp_cmdbuild_rest_retries_total: { type: 'counter', help: 'CMDBuild REST retry attempts.' },
  cmdp_redis_errors_total: { type: 'counter', help: 'Redis command errors by reason.' },
  cmdp_runtime_cache_hits_total: { type: 'counter', help: 'Runtime cache hits by backend.' },
  cmdp_runtime_cache_misses_total: { type: 'counter', help: 'Runtime cache misses by backend.' },
  cmdp_runtime_cache_build_seconds_count: { type: 'counter', help: 'Runtime cache build duration observation count.' },
  cmdp_runtime_cache_build_seconds_sum: { type: 'counter', help: 'Runtime cache build duration sum in seconds.' },
  cmdp_runtime_cache_invalidations_total: { type: 'counter', help: 'Runtime cache invalidations by backend and status.' },
  cmdp_d2_render_errors_total: { type: 'counter', help: 'D2 render failures by reason.' },
  cmdp_d2_render_seconds_count: { type: 'counter', help: 'D2 render duration observation count.' },
  cmdp_d2_render_seconds_sum: { type: 'counter', help: 'D2 render duration sum in seconds.' },
  cmdp_d2_import_total: { type: 'counter', help: 'D2 import requests by status.' },
  cmdp_d2_import_seconds_count: { type: 'counter', help: 'D2 import duration observation count.' },
  cmdp_d2_import_seconds_sum: { type: 'counter', help: 'D2 import duration sum in seconds.' },
  cmdp_template_run_errors_total: { type: 'counter', help: 'Template execution failures by action and reason.' },
  cmdp_execution_throttled_total: { type: 'counter', help: 'Template execution requests rejected by throttling.' },
  cmdp_health_ready: { type: 'gauge', help: 'Readiness status: 1 ready, 0 not ready.' }
};

function metricLabelsKey(labels = {}) {
  return Object.keys(labels)
    .sort()
    .map((name) => [name, String(labels[name])]);
}

function metricKey(name, labels = {}) {
  return `${name}|${JSON.stringify(metricLabelsKey(labels))}`;
}

function incMetric(name, labels = {}, amount = 1) {
  const key = metricKey(name, labels);
  const current = metricsState.counters.get(key) || { name, labels: Object.fromEntries(metricLabelsKey(labels)), value: 0 };
  current.value += Number(amount) || 0;
  metricsState.counters.set(key, current);
  return current.value;
}

function setMetricGauge(name, labels = {}, value = 0) {
  const key = metricKey(name, labels);
  metricsState.gauges.set(key, {
    name,
    labels: Object.fromEntries(metricLabelsKey(labels)),
    value: Number(value) || 0
  });
}

setMetricGauge('cmdp_health_ready', {}, 0);

function observeMetricSeconds(name, labels = {}, seconds = 0) {
  incMetric(`${name}_count`, labels, 1);
  incMetric(`${name}_sum`, labels, Math.max(0, Number(seconds) || 0));
}

function statusClass(statusCode) {
  const status = Number(statusCode) || 0;
  if (status <= 0) return 'network';
  return `${Math.floor(status / 100)}xx`;
}

function prometheusEscape(value) {
  return String(value === undefined || value === null ? '' : value)
    .replace(/\\/g, '\\\\')
    .replace(/\n/g, '\\n')
    .replace(/"/g, '\\"');
}

function prometheusSample(sample) {
  const labels = Object.entries(sample.labels || {});
  const suffix = labels.length
    ? `{${labels.map(([name, value]) => `${name}="${prometheusEscape(value)}"`).join(',')}}`
    : '';
  return `${sample.name}${suffix} ${sample.value}`;
}

function renderPrometheusMetrics() {
  const samples = [...metricsState.counters.values(), ...metricsState.gauges.values()]
    .sort((left, right) => left.name.localeCompare(right.name) || JSON.stringify(left.labels).localeCompare(JSON.stringify(right.labels)));
  const names = Array.from(new Set(samples.map((sample) => sample.name))).sort();
  const lines = [];
  for (const name of names) {
    const definition = metricDefinitions[name] || { type: 'untyped', help: name };
    lines.push(`# HELP ${name} ${definition.help}`);
    lines.push(`# TYPE ${name} ${definition.type}`);
    samples.filter((sample) => sample.name === name).forEach((sample) => lines.push(prometheusSample(sample)));
  }
  return `${lines.join('\n')}\n`;
}

async function metricsPayload() {
  return renderPrometheusMetrics();
}

function attachHttpRequestLogging(req, res, requestUrl) {
  if (!shouldStructuredLogRequest(requestUrl.pathname)) return;
  const requestId = truncateText(req.headers['x-request-id'] || crypto.randomUUID(), 120);
  req.cmdpRequestId = requestId;
  const startedAt = Date.now();
  let responseFinished = false;
  if (!res.headersSent) res.setHeader('x-request-id', requestId);
  const common = {
    requestId,
    method: req.method || '',
    path: sanitizeRequestPath(requestUrl),
    route: routeKind(requestUrl.pathname),
    hasCmdbuildCookie: Boolean(getCookieValue(req.headers.cookie, 'CMDBuild-Authorization')),
    sessionHash: sessionHashFromCookie(req.headers.cookie),
    userAgent: truncateText(req.headers['user-agent'] || '', 200),
    referer: sanitizeUrlForLog(req.headers.referer || '', 500)
  };
  logDebug('http.request.start', common);
  logDiagnosticVerbose('http.request.start', {
    requestId,
    method: common.method,
    path: common.path,
    route: common.route,
    headers: sanitizeHeaders(req.headers)
  });
  res.on('finish', () => {
    responseFinished = true;
    const statusCode = res.statusCode || 0;
    const fields = {
      ...common,
      statusCode,
      durationMs: Date.now() - startedAt
    };
    incMetric('cmdp_http_requests_total', {
      route: common.route,
      method: common.method,
      status: statusClass(statusCode)
    });
    observeMetricSeconds('cmdp_http_request_duration_seconds', {
      route: common.route,
      method: common.method
    }, fields.durationMs / 1000);
    logDiagnosticBasic('http.request.finish', {
      requestId,
      method: common.method,
      path: common.path,
      route: common.route,
      statusCode,
      durationMs: fields.durationMs
    });
    logDiagnosticVerbose('http.request.finish_detail', {
      requestId,
      method: common.method,
      path: common.path,
      route: common.route,
      statusCode,
      durationMs: fields.durationMs,
      hasCmdbuildCookie: common.hasCmdbuildCookie,
      responseContentType: truncateText(res.getHeader('content-type') || '', 200)
    });
    if (statusCode >= 500) logError('http.request.finish', fields);
    else if (statusCode >= 400) logWarn('http.request.finish', fields);
    else logInfo('http.request.finish', fields);
  });
  res.on('close', () => {
    if (responseFinished) return;
    const fields = {
      ...common,
      durationMs: Date.now() - startedAt
    };
    incMetric('cmdp_http_requests_aborted_total', {
      route: common.route,
      method: common.method
    });
    logWarn('http.request.aborted', fields);
  });
}

function appendBoundedLog(target, item, maxItems = 100) {
  target.push(item);
  while (target.length > maxItems) target.shift();
}

function stableJsonStringify(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(stableJsonStringify).join(',')}]`;
  return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableJsonStringify(value[key])}`).join(',')}}`;
}

function sha256Hex(value) {
  return crypto.createHash('sha256').update(String(value || '')).digest('hex');
}

function hashJson(value) {
  return sha256Hex(stableJsonStringify(value));
}

function legacyAssistantDraftAuthoring(value) {
  const draft = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
  const d2Draft = draft.d2Authoring && typeof draft.d2Authoring === 'object' && !Array.isArray(draft.d2Authoring)
    ? draft.d2Authoring
    : {};
  return {
    version: 1,
    assistant: {
      objectFlowIntent: cloneJsonValueServer(draft.objectFlowIntent, { context: '', blocks: [] }),
      diagramInterpretPrompt: String(draft.diagramInterpretPrompt || ''),
      diagramMappingPrompt: String(draft.diagramMappingPrompt || '')
    },
    d2: { source: String(d2Draft.source || '') }
  };
}

function normalizeD2AnalysisCheckpoint(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const source = value.source && typeof value.source === 'object' && !Array.isArray(value.source) ? value.source : {};
  const roles = Array.isArray(value.roles) ? value.roles : [];
  const relationRules = Array.isArray(value.relationRules) ? value.relationRules : [];
  const structureTree = value.structureTree && typeof value.structureTree === 'object' && !Array.isArray(value.structureTree)
    ? value.structureTree
    : {};
  const checkpoint = {
    version: D2_IMPORT_ANALYSIS_CHECKPOINT_VERSION,
    proposalId: truncateText(String(value.proposalId || ''), 128),
    deterministicSpecHash: truncateText(String(value.deterministicSpecHash || ''), 128),
    source: {
      hash: truncateText(String(source.hash || ''), 128),
      structureHash: truncateText(String(source.structureHash || ''), 128),
      mappingContractHash: truncateText(String(source.mappingContractHash || ''), 128)
    },
    roles: roles.slice(0, D2_IMPORT_MAX_ELEMENTS).map((role) => ({
      id: truncateText(String(role && role.id || ''), 256),
      visualKind: normalizeDiagramImportVisualKind(role && role.visualKind, ''),
      labelTemplate: truncateText(String(role && role.labelTemplate || ''), 12_000)
    })).filter((role) => role.id),
    relationRules: cloneJsonValueServer(relationRules.slice(0, D2_IMPORT_MAX_ELEMENTS), []),
    structureTree: cloneJsonValueServer(structureTree, { version: D2_IMPORT_STRUCTURE_TREE_VERSION, items: [] })
  };
  if (Number(checkpoint.structureTree.version || 0) !== D2_IMPORT_STRUCTURE_TREE_VERSION || !Array.isArray(checkpoint.structureTree.items)) {
    return null;
  }
  if (!checkpoint.proposalId || !isSpecHash(checkpoint.deterministicSpecHash) ||
    !isSpecHash(checkpoint.source.hash) || !isSpecHash(checkpoint.source.structureHash) || !isSpecHash(checkpoint.source.mappingContractHash)) {
    return null;
  }
  const bytes = Buffer.byteLength(JSON.stringify(checkpoint), 'utf8');
  if (bytes > D2_IMPORT_ASSISTANT_CHECKPOINT_MAX_BYTES) {
    throw new Error(`authoring.d2.analysisCheckpoint exceeded configured maxBytes=${D2_IMPORT_ASSISTANT_CHECKPOINT_MAX_BYTES}.`);
  }
  return checkpoint;
}

function normalizeD2AssistantCheckpoint(value) {
  const analysis = normalizeD2AnalysisCheckpoint(value);
  if (!analysis) return null;
  const source = value.source && typeof value.source === 'object' && !Array.isArray(value.source) ? value.source : {};
  const roles = Array.isArray(value.roles) ? value.roles : [];
  const relationRules = Array.isArray(value.relationRules) ? value.relationRules : [];
  const structureTree = value.structureTree && typeof value.structureTree === 'object' && !Array.isArray(value.structureTree)
    ? value.structureTree
    : {};
  const interpretation = value.interpretation && typeof value.interpretation === 'object' && !Array.isArray(value.interpretation)
    ? value.interpretation
    : {};
  const mapping = value.mapping && typeof value.mapping === 'object' && !Array.isArray(value.mapping)
    ? value.mapping
    : {};
  const checkpoint = {
    version: D2_IMPORT_ASSISTANT_CHECKPOINT_VERSION,
    proposalId: analysis.proposalId,
    deterministicSpecHash: analysis.deterministicSpecHash,
    source: analysis.source,
    roles: roles.slice(0, D2_IMPORT_MAX_ELEMENTS).map((role) => ({
      id: truncateText(String(role && role.id || ''), 256),
      visualKind: normalizeDiagramImportVisualKind(role && role.visualKind, ''),
      labelTemplate: truncateText(String(role && role.labelTemplate || ''), 12_000)
    })).filter((role) => role.id),
    relationRules: cloneJsonValueServer(relationRules.slice(0, D2_IMPORT_MAX_ELEMENTS), []),
    structureTree: cloneJsonValueServer(structureTree, { version: D2_IMPORT_STRUCTURE_TREE_VERSION, items: [] }),
    interpretation: {
      explanation: truncateText(String(interpretation.explanation || ''), 12_000),
      warnings: uniqueStrings(Array.isArray(interpretation.warnings) ? interpretation.warnings.map(String) : []).slice(0, 200),
      decisions: (Array.isArray(interpretation.decisions) ? interpretation.decisions : []).slice(0, D2_IMPORT_MAX_ELEMENTS).map((decision) => ({
        roleId: truncateText(String(decision && decision.roleId || ''), 256),
        visualKind: normalizeDiagramImportVisualKind(decision && decision.visualKind, ''),
        labelTemplate: truncateText(String(decision && decision.labelTemplate || ''), 12_000),
        reason: truncateText(String(decision && decision.reason || ''), 12_000)
      })).filter((decision) => decision.roleId)
    },
    mapping: {
      explanation: truncateText(String(mapping.explanation || ''), 12_000),
      warnings: uniqueStrings(Array.isArray(mapping.warnings) ? mapping.warnings.map(String) : []).slice(0, 200),
      result: cloneJsonValueServer(mapping.result && typeof mapping.result === 'object' && !Array.isArray(mapping.result) ? mapping.result : {}, {})
    }
  };
  const bytes = Buffer.byteLength(JSON.stringify(checkpoint), 'utf8');
  if (bytes > D2_IMPORT_ASSISTANT_CHECKPOINT_MAX_BYTES) {
    throw new Error(`authoring.d2.assistantCheckpoint exceeded configured maxBytes=${D2_IMPORT_ASSISTANT_CHECKPOINT_MAX_BYTES}.`);
  }
  return checkpoint;
}

function normalizeTemplateAuthoring(value, legacyDraft = null) {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value
    : legacyDraft && typeof legacyDraft === 'object' && !Array.isArray(legacyDraft)
      ? legacyAssistantDraftAuthoring(legacyDraft)
      : null;
  if (!source) return null;
  const assistant = source.assistant && typeof source.assistant === 'object' && !Array.isArray(source.assistant)
    ? source.assistant
    : {};
  const d2 = source.d2 && typeof source.d2 === 'object' && !Array.isArray(source.d2)
    ? source.d2
    : {};
  const d2Source = String(d2.source || '');
  if (Buffer.byteLength(d2Source, 'utf8') > D2_IMPORT_MAX_INPUT_BYTES) {
    throw new Error(`authoring.d2.source exceeded configured maxInputBytes=${D2_IMPORT_MAX_INPUT_BYTES}.`);
  }
  const analysisCheckpoint = normalizeD2AnalysisCheckpoint(d2.analysisCheckpoint);
  const assistantCheckpoint = normalizeD2AssistantCheckpoint(d2.assistantCheckpoint);
  return {
    version: 1,
    assistant: {
      objectFlowIntent: cloneJsonValueServer(assistant.objectFlowIntent, { context: '', blocks: [] }),
      diagramInterpretPrompt: truncateText(String(assistant.diagramInterpretPrompt || ''), 6000),
      diagramMappingPrompt: truncateText(String(assistant.diagramMappingPrompt || ''), 6000)
    },
    d2: {
      source: d2Source,
      sourceHash: d2Source ? sha256Hex(d2Source) : '',
      ...(analysisCheckpoint ? { analysisCheckpoint } : {}),
      ...(assistantCheckpoint ? { assistantCheckpoint } : {})
    }
  };
}

function templateAuthoring(spec, options = {}) {
  const source = spec && typeof spec === 'object' && !Array.isArray(spec) ? spec : {};
  const authoring = normalizeTemplateAuthoring(source.authoring);
  if (authoring || options.allowLegacy !== true) return authoring;
  // Retired assistantDraft is accepted only by the ordinary template-save
  // migration path. Runtime and authoring actions never treat it as state.
  return normalizeTemplateAuthoring(null, source.assistantDraft);
}

function templateAuthoringD2(spec, options = {}) {
  const authoring = templateAuthoring(spec, options);
  return authoring && authoring.d2 && typeof authoring.d2 === 'object' && !Array.isArray(authoring.d2)
    ? authoring.d2
    : {};
}

function executionTemplateSpec(spec) {
  const next = cloneJsonValueServer(spec && typeof spec === 'object' && !Array.isArray(spec) ? spec : {}, {});
  // Authoring prompts and raw D2 source do not change deterministic execution.
  // D2 mapping state remains in result.diagrams and is therefore part of this hash.
  // Validation signatures and input fingerprints only govern authoring review;
  // they must not invalidate a published/static result by themselves.
  delete next.authoring;
  delete next.assistantDraft;
  for (const diagram of next.result && Array.isArray(next.result.diagrams) ? next.result.diagrams : []) {
    const imported = diagram && diagram.authoring && diagram.authoring.d2Import;
    if (!imported || typeof imported !== 'object' || Array.isArray(imported)) continue;
    delete imported.mappingValidation;
    delete imported.mappingInputRevision;
  }
  return next;
}

function executionSpecHash(spec) {
  return hashJson(executionTemplateSpec(spec));
}

function diagramImportDeterministicSpec(spec) {
  return executionTemplateSpec(spec);
}

function diagramImportDeterministicSpecHash(spec) {
  return hashJson(diagramImportDeterministicSpec(spec));
}

const d2SourceStructureCache = new Map();
const D2_SOURCE_STRUCTURE_CACHE_MAX = 100;

function d2MappingStructureHash(ir) {
  const elements = ir && ir.elements && typeof ir.elements === 'object' ? ir.elements : {};
  const normalizeElements = (value) => (Array.isArray(value) ? value : []).map((item) => ({
    key: String(item && item.key || ''),
    parentKey: String(item && item.parentKey || ''),
    childKey: String(item && item.childKey || ''),
    childrenKeys: Array.isArray(item && item.childrenKeys) ? item.childrenKeys.map(String).sort() : [],
    groupKeys: Array.isArray(item && item.groupKeys) ? item.groupKeys.map(String).sort() : [],
    sourceKey: String(item && item.sourceKey || ''),
    targetKey: String(item && item.targetKey || ''),
    pathSegments: Array.isArray(item && item.pathSegments) ? item.pathSegments.map(String) : [],
    sourcePathSegments: Array.isArray(item && item.sourcePathSegments) ? item.sourcePathSegments.map(String) : [],
    targetPathSegments: Array.isArray(item && item.targetPathSegments) ? item.targetPathSegments.map(String) : [],
    parentPathSegments: Array.isArray(item && item.parentPathSegments) ? item.parentPathSegments.map(String) : [],
    childPathSegments: Array.isArray(item && item.childPathSegments) ? item.childPathSegments.map(String) : [],
    direction: String(item && item.direction || ''),
    classKeys: Array.isArray(item && item.classKeys) ? item.classKeys.map(String).sort() : []
  })).sort((left, right) => left.key.localeCompare(right.key));
  return hashJson({
    version: 1,
    nodes: normalizeElements(elements.nodes),
    edges: normalizeElements(elements.edges),
    groups: normalizeElements(elements.groups),
    hierarchies: normalizeElements(elements.hierarchies),
    classes: (Array.isArray(ir && ir.classes) ? ir.classes : []).map((item) => String(item && item.key || '')).filter(Boolean).sort()
  });
}

function d2MappingContractHash(ir) {
  const classes = Array.isArray(ir && ir.classes) ? ir.classes : [];
  return hashJson({
    version: 1,
    classes: classes.map((item) => ({
      key: String(item && item.key || ''),
      notes: String(item && item.notes || ''),
      directionPolicy: normalizeDiagramDirectionPolicy(item && item.directionPolicy)
    })).filter((item) => item.key).sort((left, right) => left.key.localeCompare(right.key))
  });
}

async function d2SourceStructureIdentity(source) {
  const text = String(source || '');
  const sourceHash = sha256Hex(text);
  const cached = d2SourceStructureCache.get(sourceHash);
  if (cached) return cached;
  const parsed = await d2ImportIrForRender(text);
  const identity = parsed.ok
    ? {
        ok: true,
        sourceHash,
        structureHash: parsed.ir.source.structureHash || d2MappingStructureHash(parsed.ir),
        mappingContractHash: parsed.ir.source.mappingContractHash || d2MappingContractHash(parsed.ir),
        ir: parsed.ir
      }
    : { ok: false, sourceHash, reason: parsed.reason || 'invalid_source', error: parsed.error || 'D2 source is invalid.' };
  d2SourceStructureCache.set(sourceHash, identity);
  while (d2SourceStructureCache.size > D2_SOURCE_STRUCTURE_CACHE_MAX) {
    d2SourceStructureCache.delete(d2SourceStructureCache.keys().next().value);
  }
  return identity;
}

async function d2WorkflowStatusForSpec(spec) {
  const d2Authoring = templateAuthoringD2(spec, { allowLegacy: false });
  const diagrams = spec && spec.result && Array.isArray(spec.result.diagrams) ? spec.result.diagrams : [];
  const importedDiagram = diagrams.find((diagram) => {
    const item = diagram && diagram.authoring && diagram.authoring.d2Import;
    return item && item.version === 3 && String(item.sourceHash || '').trim();
  });
  const imported = importedDiagram && importedDiagram.authoring && importedDiagram.authoring.d2Import;
  const source = String(d2Authoring.source || '');
  if (!source.trim()) {
    if (imported) {
      return {
        state: 'pending',
        reason: 'authoring_source_missing',
        sourceHash: '',
        appliedSourceHash: String(imported.sourceHash || '')
      };
    }
    return { state: 'none', reason: 'source_missing' };
  }
  const sourceHash = sha256Hex(source);
  if (!imported) {
    return { state: 'pending', reason: 'mapping_missing', sourceHash, appliedSourceHash: '' };
  }
  if (diagramImportStoredMaterializationIssues(imported).length) {
    return {
      state: 'pending',
      reason: 'materialization_contract_required',
      sourceHash,
      appliedSourceHash: String(imported.sourceHash || '')
    };
  }
  if (!importedDiagram.templateGrammar || importedDiagram.templateGrammar.version !== 3) {
    return { state: 'pending', reason: 'template_grammar_missing', sourceHash, appliedSourceHash: String(imported.sourceHash || '') };
  }
  if (!imported.structureTree || imported.structureTree.version !== D2_IMPORT_STRUCTURE_TREE_VERSION || !Array.isArray(imported.structureTree.items)) {
    return { state: 'pending', reason: 'structure_tree_missing', sourceHash, appliedSourceHash: String(imported.sourceHash || '') };
  }
  if (Number(imported.semanticModelRevision || 0) !== D2_IMPORT_SEMANTIC_MODEL_REVISION) {
    return {
      state: 'pending',
      reason: 'semantic_model_revision_required',
      sourceHash,
      appliedSourceHash: String(imported.sourceHash || '')
    };
  }
  if (!String(imported.mappingContractHash || '').trim()) {
    return { state: 'pending', reason: 'mapping_contract_missing', sourceHash, appliedSourceHash: String(imported.sourceHash || '') };
  }
  if (String(imported.sourceHash || '') !== sourceHash) {
    return { state: 'pending', reason: 'source_changed', sourceHash, appliedSourceHash: String(imported.sourceHash || '') };
  }
  if (imported.mappingValidation && imported.mappingValidation.status === 'needsReview') {
    return {
      state: 'pending',
      reason: 'mapping_input_review_required',
      inputReasons: Array.isArray(imported.mappingValidation.reasons) ? imported.mappingValidation.reasons : [],
      sourceHash,
      appliedSourceHash: String(imported.sourceHash || '')
    };
  }
  if (!imported.mappingValidation || imported.mappingValidation.status !== 'valid' || !diagramImportMappingValidationIsCurrent(imported)) {
    return { state: 'pending', reason: 'mapping_validation_required', sourceHash, appliedSourceHash: String(imported.sourceHash || '') };
  }
  const inputRevision = diagramImportMappingInputRevisionStatus(spec, imported);
  if (!inputRevision.current) {
    return {
      state: 'pending',
      reason: inputRevision.reasons.includes('source') ? 'source_changed' : 'mapping_input_review_required',
      inputReasons: inputRevision.reasons,
      sourceHash,
      appliedSourceHash: String(imported.sourceHash || '')
    };
  }
  return {
    state: 'applied',
    sourceHash,
    diagramId: String(imported.diagramId || ''),
    roles: Array.isArray(imported.roles) ? imported.roles.length : 0
  };
}

function normalizeD2Layout(value) {
  const text = String(value || D2_LAYOUT || 'dagre').trim().toLowerCase();
  return D2_LAYOUT_ALLOWLIST.has(text) ? text : 'dagre';
}

function d2RendererConfig() {
  return {
    enabled: D2_RENDER_ENABLED,
    required: D2_RENDER_ENABLED,
    binary: D2_BINARY,
    timeoutMs: D2_TIMEOUT_MS,
    maxInputBytes: D2_MAX_INPUT_BYTES,
    maxOutputBytes: D2_MAX_OUTPUT_BYTES,
    maxDiagrams: D2_MAX_DIAGRAMS,
    concurrency: D2_CONCURRENCY,
    layout: normalizeD2Layout(D2_LAYOUT),
    layoutAllowlist: Array.from(D2_LAYOUT_ALLOWLIST).sort()
  };
}

function d2RendererConfigSummary() {
  const config = d2RendererConfig();
  return {
    enabled: config.enabled,
    required: config.required,
    binary: config.binary,
    timeoutMs: config.timeoutMs,
    maxInputBytes: config.maxInputBytes,
    maxOutputBytes: config.maxOutputBytes,
    maxDiagrams: config.maxDiagrams,
    concurrency: config.concurrency,
    layout: config.layout,
    layoutAllowlist: config.layoutAllowlist,
    importer: d2ImportConfigSummary()
  };
}

function d2CacheContext() {
  const config = d2RendererConfig();
  return {
    d2: {
      sourceBuilderVersion: 3,
      enabled: config.enabled,
      binary: config.binary,
      timeoutMs: config.timeoutMs,
      maxInputBytes: config.maxInputBytes,
      maxOutputBytes: config.maxOutputBytes,
      maxDiagrams: config.maxDiagrams,
      concurrency: config.concurrency,
      layout: config.layout,
      layoutAllowlist: config.layoutAllowlist,
      markdownFrameRevision: D2_MARKDOWN_FRAME_REVISION
    }
  };
}

function d2RenderError(reason, message, extra = {}) {
  return {
    rendered: false,
    content: '',
    reason,
    renderError: truncateText(String(message || D2_RENDERER_UNAVAILABLE_TEXT), 500),
    ...extra
  };
}

function safeD2SvgReferenceValue(value) {
  const text = String(value || '').trim();
  if (!text) return true;
  if (text.startsWith('#')) return true;
  return text.startsWith('/') && !text.startsWith('//');
}

function d2ProcessEnv() {
  return {
    PATH: process.env.PATH || '/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin',
    HOME: process.env.HOME || '/tmp',
    TMPDIR: process.env.TMPDIR || '/tmp'
  };
}

function runD2Process(args, input, options = {}) {
  const config = d2RendererConfig();
  const timeoutMs = Math.max(100, Number(options.timeoutMs || config.timeoutMs) || config.timeoutMs);
  const maxOutputBytes = Math.max(1024, Number(options.maxOutputBytes || config.maxOutputBytes) || config.maxOutputBytes);
  return new Promise((resolve) => {
    const startedAt = Date.now();
    let stdoutBytes = 0;
    let stderrBytes = 0;
    let stdout = '';
    let stderr = '';
    let settled = false;
    let killedForOutput = false;
    let child;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      resolve({
        elapsedMs: Date.now() - startedAt,
        stdout: truncateText(stdout, maxOutputBytes),
        stderr: truncateText(stderr, 4096),
        ...result
      });
    };
    const timer = setTimeout(() => {
      if (child && !child.killed) child.kill('SIGKILL');
      finish({
        ok: false,
        reason: 'timeout',
        error: `D2 renderer timed out after ${timeoutMs}ms.`
      });
    }, timeoutMs);
    if (typeof timer.unref === 'function') timer.unref();

    try {
      child = spawn(config.binary, args, {
        shell: false,
        windowsHide: true,
        env: d2ProcessEnv(),
        stdio: ['pipe', 'pipe', 'pipe']
      });
    } catch (error) {
      finish({
        ok: false,
        reason: 'spawn_error',
        error: error && error.message ? error.message : String(error)
      });
      return;
    }

    child.stdout.on('data', (chunk) => {
      stdoutBytes += chunk.length;
      if (stdoutBytes > maxOutputBytes) {
        killedForOutput = true;
        if (!child.killed) child.kill('SIGKILL');
        return;
      }
      stdout += chunk.toString('utf8');
    });
    child.stderr.on('data', (chunk) => {
      stderrBytes += chunk.length;
      if (stderrBytes <= 4096) stderr += chunk.toString('utf8');
    });
    child.on('error', (error) => {
      finish({
        ok: false,
        reason: error && error.code === 'ENOENT' ? 'binary_not_found' : 'process_error',
        error: error && error.message ? error.message : String(error)
      });
    });
    child.stdin.on('error', (error) => {
      if (child && !child.killed) child.kill('SIGKILL');
      finish({
        ok: false,
        reason: 'stdin_error',
        error: error && error.message ? error.message : String(error)
      });
    });
    child.on('close', (code, signal) => {
      if (killedForOutput) {
        finish({
          ok: false,
          reason: 'output_limit',
          error: `D2 renderer output exceeded ${maxOutputBytes} bytes.`
        });
        return;
      }
      if (code !== 0) {
        finish({
          ok: false,
          reason: 'exit_code',
          exitCode: code == null ? null : code,
          signal: signal || '',
          error: `D2 renderer exited with code ${code == null ? 'unknown' : code}${signal ? ` signal ${signal}` : ''}.`
        });
        return;
      }
      finish({
        ok: true,
        reason: 'ok'
      });
    });

    if (input) child.stdin.write(input);
    child.stdin.end();
  });
}

function d2ImportConfigSummary() {
  return {
    binary: D2_IMPORT_BINARY,
    timeoutMs: D2_IMPORT_TIMEOUT_MS,
    maxInputBytes: D2_IMPORT_MAX_INPUT_BYTES,
    maxOutputBytes: D2_IMPORT_MAX_OUTPUT_BYTES,
    maxElements: D2_IMPORT_MAX_ELEMENTS,
    proposalTtlMs: D2_IMPORT_PROPOSAL_TTL_MS,
    assistantMaxSpecBytes: D2_IMPORT_ASSISTANT_MAX_SPEC_BYTES,
    assistantCheckpointMaxBytes: D2_IMPORT_ASSISTANT_CHECKPOINT_MAX_BYTES,
    templateRequestMaxBytes: TEMPLATE_REQUEST_MAX_BYTES
  };
}

function runD2ImportProcess(source, options = {}) {
  const config = d2ImportConfigSummary();
  const timeoutMs = Math.max(100, Number(options.timeoutMs || config.timeoutMs) || config.timeoutMs);
  const maxOutputBytes = Math.max(1024, Number(options.maxOutputBytes || config.maxOutputBytes) || config.maxOutputBytes);
  return new Promise((resolve) => {
    const startedAt = Date.now();
    let stdout = '';
    let stderr = '';
    let stdoutBytes = 0;
    let stderrBytes = 0;
    let settled = false;
    let killedForOutput = false;
    let child;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve({ elapsedMs: Date.now() - startedAt, stdout, stderr: truncateText(stderr, 4096), ...result });
    };
    const timer = setTimeout(() => {
      if (child && !child.killed) child.kill('SIGKILL');
      finish({ ok: false, reason: 'timeout', error: `D2 import timed out after ${timeoutMs}ms.` });
    }, timeoutMs);
    if (typeof timer.unref === 'function') timer.unref();

    try {
      child = spawn(config.binary, [`--max-input-bytes=${config.maxInputBytes}`, `--max-elements=${config.maxElements}`], {
        shell: false,
        windowsHide: true,
        env: d2ProcessEnv(),
        stdio: ['pipe', 'pipe', 'pipe']
      });
    } catch (error) {
      finish({ ok: false, reason: 'spawn_error', error: error && error.message ? error.message : String(error) });
      return;
    }
    child.stdout.on('data', (chunk) => {
      stdoutBytes += chunk.length;
      if (stdoutBytes > maxOutputBytes) {
        killedForOutput = true;
        if (!child.killed) child.kill('SIGKILL');
        return;
      }
      stdout += chunk.toString('utf8');
    });
    child.stderr.on('data', (chunk) => {
      stderrBytes += chunk.length;
      if (stderrBytes <= 4096) stderr += chunk.toString('utf8');
    });
    child.on('error', (error) => {
      finish({
        ok: false,
        reason: error && error.code === 'ENOENT' ? 'binary_not_found' : 'process_error',
        error: error && error.message ? error.message : String(error)
      });
    });
    child.stdin.on('error', (error) => {
      if (child && !child.killed) child.kill('SIGKILL');
      finish({
        ok: false,
        reason: 'stdin_error',
        error: error && error.message ? error.message : String(error)
      });
    });
    child.on('close', (code, signal) => {
      if (killedForOutput) {
        finish({ ok: false, reason: 'output_limit', error: `D2 import output exceeded ${maxOutputBytes} bytes.` });
      } else if (code !== 0) {
        finish({
          ok: false,
          reason: 'exit_code',
          exitCode: code == null ? null : code,
          signal: signal || '',
          error: stderr.trim() || `D2 import exited with code ${code == null ? 'unknown' : code}.`
        });
      } else {
        finish({ ok: true, reason: 'ok' });
      }
    });
    child.stdin.end(source);
  });
}

function normalizeDiagramImportElement(value, fallbackKey = '') {
  const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
  const key = String(source.key || source.id || source.name || fallbackKey || '').trim();
  return {
    key,
    label: String(source.label || source.title || key).trim(),
    kind: String(source.kind || source.type || source.shape || '').trim(),
    parentKey: String(source.parentKey || source.parent || '').trim(),
    childKey: String(source.childKey || source.child || '').trim(),
    childrenKeys: uniqueStrings(Array.isArray(source.childrenKeys) ? source.childrenKeys : Array.isArray(source.children) ? source.children : []),
    groupKeys: uniqueStrings(Array.isArray(source.groupKeys) ? source.groupKeys : source.group ? [source.group] : []),
    sourceKey: String(source.sourceKey || source.source || source.from || '').trim(),
    targetKey: String(source.targetKey || source.target || source.to || '').trim(),
    pathSegments: Array.isArray(source.pathSegments) ? source.pathSegments.map(String) : [],
    sourcePathSegments: Array.isArray(source.sourcePathSegments) ? source.sourcePathSegments.map(String) : [],
    targetPathSegments: Array.isArray(source.targetPathSegments) ? source.targetPathSegments.map(String) : [],
    parentPathSegments: Array.isArray(source.parentPathSegments) ? source.parentPathSegments.map(String) : [],
    childPathSegments: Array.isArray(source.childPathSegments) ? source.childPathSegments.map(String) : [],
    direction: String(source.direction || '').trim(),
    classKeys: uniqueStrings(Array.isArray(source.classKeys) ? source.classKeys : Array.isArray(source.classes) ? source.classes : []),
    suggestedRole: normalizeDiagramImportSemantic(source.suggestedRole),
    selectedRole: normalizeDiagramImportSemantic(source.selectedRole),
    semanticReason: truncateText(String(source.semanticReason || ''), 300),
    bindingHint: source.bindingHint && typeof source.bindingHint === 'object' && !Array.isArray(source.bindingHint)
      ? cloneJsonValueServer(source.bindingHint, {})
      : source.binding && typeof source.binding === 'object' && !Array.isArray(source.binding)
        ? cloneJsonValueServer(source.binding, {})
        : {},
    styleHints: {
      ...(source.styleHints && typeof source.styleHints === 'object' && !Array.isArray(source.styleHints) ? cloneJsonValueServer(source.styleHints, {}) : {}),
      ...(source.shape ? { shape: String(source.shape) } : {}),
      ...(Array.isArray(source.classes) && source.classes.length ? { classes: source.classes.map((item) => String(item)).filter(Boolean) } : {}),
      ...(source.href ? { href: String(source.href) } : {}),
      ...(source.tooltip ? { tooltip: String(source.tooltip) } : {}),
      ...(source.board ? { board: String(source.board) } : {}),
      ...(source.style && typeof source.style === 'object' && !Array.isArray(source.style)
        ? { style: cloneJsonValueServer(source.style, {}) }
        : {})
    },
    provenance: Array.isArray(source.provenance) ? source.provenance.map((item) => truncateText(String(item || ''), 200)).filter(Boolean) : []
    ,range: source.range && typeof source.range === 'object' && !Array.isArray(source.range)
      ? cloneJsonValueServer(source.range, {})
      : null
  };
}

function normalizeDiagramImportSemantic(value) {
  const semantic = String(value || '').trim();
  if (semantic === 'decorative') return 'static';
  return ['object', 'composite', 'group', 'static', 'structural'].includes(semantic) ? semantic : '';
}

function normalizeDiagramImportVisualKind(value, fallback = '') {
  const kind = String(value || '').trim();
  return ['node', 'container'].includes(kind) ? kind : fallback;
}

function diagramImportRoleVisualKind(role) {
  const source = role && typeof role === 'object' && !Array.isArray(role) ? role : {};
  const explicit = normalizeDiagramImportVisualKind(source.visualKind);
  if (explicit) return explicit;
  if (String(source.kind || '') === 'untypedContainer' || (Array.isArray(source.containerKeys) && source.containerKeys.length)) {
    return 'container';
  }
  return 'node';
}

function diagramImportInternalSemantic(role) {
  const visualKind = diagramImportRoleVisualKind(role);
  if (visualKind === 'node') return 'object';
  return 'structural';
}

function diagramImportApplyRoleModel(role) {
  const source = role && typeof role === 'object' ? role : {};
  const visualKind = diagramImportRoleVisualKind(source);
  const { repeatMode, ownerRoleId, groupSourceRoleId, groupKeyPath, ...rest } = source;
  return {
    ...rest,
    visualKind
  };
}

function diagramImportRoleNeedsStage(role) {
  return diagramImportRoleVisualKind(role) === 'node';
}

function diagramImportSemanticIsStructural(semantic) {
  return ['structural', 'static'].includes(normalizeDiagramImportSemantic(semantic));
}

function normalizeDiagramImportClass(value, fallbackKey = '') {
  const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
  const key = String(source.key || source.name || source.id || fallbackKey || '').trim();
  const usageKeys = uniqueStrings(source.usageKeys || source.elementKeys || source.sampleElementKeys || source.usages || []);
  const definition = source.definition && typeof source.definition === 'object' && !Array.isArray(source.definition)
    ? source.definition
    : {};
  const definitionStyleHints = {
    ...(definition.shape ? { shape: String(definition.shape) } : {}),
    ...(definition.style && typeof definition.style === 'object' && !Array.isArray(definition.style)
      ? { style: cloneJsonValueServer(definition.style, {}) }
      : {})
  };
  const notes = truncateText(String(source.notes || source.Notes || definition.notes || definition.Notes || '').trim(), 8000);
  return {
    key,
    label: String(source.label || source.description || key).trim(),
    notes,
    directionPolicy: normalizeDiagramDirectionPolicy(source.directionPolicy || definition.directionPolicy),
    usageKeys,
    usageCount: Math.max(usageKeys.length, Number(source.usageCount || 0)),
    nodeCount: Number(source.nodeCount || source.usage && source.usage.nodes || 0),
    containerCount: Number(source.containerCount || source.groupCount || source.usage && source.usage.groups || 0),
    styleHints: source.styleHints && typeof source.styleHints === 'object' && !Array.isArray(source.styleHints)
      ? cloneJsonValueServer(source.styleHints, {})
      : source.style && typeof source.style === 'object' && !Array.isArray(source.style)
        ? { style: cloneJsonValueServer(source.style, {}) }
        : definitionStyleHints,
    range: source.range && typeof source.range === 'object' && !Array.isArray(source.range)
      ? cloneJsonValueServer(source.range, {})
      : null
  };
}

function normalizeDiagramImportIr(raw, source) {
  const input = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  const rawElements = input.elements && typeof input.elements === 'object' && !Array.isArray(input.elements) ? input.elements : input;
  const normalizeList = (value, prefix) => (Array.isArray(value) ? value : []).map((item, index) => normalizeDiagramImportElement(item, `${prefix}_${index + 1}`)).filter((item) => item.key);
  const elements = {
    nodes: normalizeList(rawElements.nodes, 'node'),
    edges: normalizeList(rawElements.edges, 'edge'),
    groups: normalizeList(rawElements.groups, 'group'),
    hierarchies: normalizeList(rawElements.hierarchies || rawElements.hierarchy, 'hierarchy')
  };
  const rawClasses = Array.isArray(input.classes)
    ? input.classes
    : Array.isArray(rawElements.classes)
      ? rawElements.classes
      : [];
  const classes = rawClasses.map((item, index) => normalizeDiagramImportClass(item, `class_${index + 1}`)).filter((item) => item.key);
  const count = elements.nodes.length + elements.edges.length + elements.groups.length + elements.hierarchies.length;
  if (count > D2_IMPORT_MAX_ELEMENTS) {
    const error = new Error(`D2 import contains ${count} elements, exceeding configured maxElements=${D2_IMPORT_MAX_ELEMENTS}.`);
    error.code = 'd2_import_element_limit';
    error.statusCode = 413;
    throw error;
  }
  const normalized = {
    version: Number(input.version) >= 4 ? 4 : Number(input.version) >= 3 ? 3 : Number(input.version) >= 2 ? 2 : 1,
    source: {
      format: 'd2',
      hash: sha256Hex(source),
      structureHash: '',
      mappingContractHash: '',
      parser: String(input.source && (input.source.parser || input.source.parserVersion) || input.parser || 'cmdp-d2-import').trim(),
      lossless: Boolean(input.source && input.source.lossless)
    },
    template: input.template && typeof input.template === 'object' && !Array.isArray(input.template)
      ? cloneJsonValueServer(input.template, {})
      : input.diagram && typeof input.diagram === 'object' && !Array.isArray(input.diagram)
        ? cloneJsonValueServer(input.diagram, {})
        : {},
    elements,
    classes,
    warnings: uniqueStrings(Array.isArray(input.warnings) ? input.warnings : [])
  };
  normalized.source.structureHash = d2MappingStructureHash(normalized);
  normalized.source.mappingContractHash = d2MappingContractHash(normalized);
  return normalized;
}

function diagramImportStableId(prefix, value) {
  return `${prefix}_${sha256Hex(String(value || prefix)).slice(0, 16)}`;
}

function diagramImportPrimaryIdAttribute(role, primary = {}) {
  // A node represents one CMDBuild card. Its identity must remain stable even
  // when a user-facing Code or Description changes.
  if (diagramImportRoleVisualKind(role) === 'node') return '_id';
  return String(primary && primary.idAttribute || '_id').trim() || '_id';
}

function diagramImportRelatedBindingSignatureServer(binding) {
  const item = binding && typeof binding === 'object' && !Array.isArray(binding) ? binding : {};
  const id = String(item.id || '').trim();
  const stageId = String(item.stageId || '').trim();
  return id && stageId ? `stage:${stageId}:binding:${id}` : '';
}

function diagramImportChildTemplateToken(token) {
  const source = String(token || '').trim();
  const primary = source.match(/^child:([^:]+):primary:([^:]+)$/);
  if (primary) return {
    itemId: primary[1],
    kind: 'primary',
    field: primary[2],
    pathSignature: ''
  };
  const related = source.match(/^child:([^:]+):related:([^:]+):([^:]+)$/);
  if (!related) return null;
  let pathSignature = '';
  try {
    pathSignature = decodeURIComponent(related[2]);
  } catch (error) {
    return null;
  }
  return pathSignature ? {
    itemId: related[1],
    kind: 'related',
    field: related[3],
    pathSignature
  } : null;
}

function diagramImportChildTemplateTokens(template) {
  return uniqueStrings(diagramTemplateFieldNames(template || ''))
    .map((token) => ({ token: String(token || '').trim(), descriptor: diagramImportChildTemplateToken(token) }))
    .filter((item) => item.token.startsWith('child:') || item.token.startsWith('child.'));
}

function diagramImportPrimaryTemplateFieldNames(template) {
  return uniqueStrings(diagramTemplateFieldNames(template || '')
    .filter((field) => !diagramImportChildTemplateToken(field) && !String(field || '').startsWith('child.') && !String(field || '').startsWith('child:'))
    .map((field) => String(field || '').replace(/^primary\./, '').trim())
    .filter((field) => field && !field.includes('.')));
}

function diagramImportPrimaryTemplateFields(template) {
  return diagramImportPrimaryTemplateFieldNames(template);
}

function diagramImportPrimaryStructuredFields(role, primary = {}) {
  const configured = Array.isArray(primary && primary.structuredFields)
    ? primary.structuredFields
    : ['Code', 'Description'];
  const labelTemplate = String(primary && primary.labelTemplate || role && role.labelTemplate || '${Description}');
  return uniqueStrings(diagramImportPrimaryTemplateFields(labelTemplate)
    .concat(configured)).filter((field) => field !== '_id');
}

const DIAGRAM_IMPORT_CONDITION_OPERATORS = new Set([
  'equals',
  'contains',
  'regexMatch',
  'ipv4InCidr',
  'ipv4InRange',
  'ipv4CidrOverlaps',
  'ipv4CidrContains'
]);

const DIAGRAM_IMPORT_MATERIALIZATION_KINDS = new Set(['structural', 'stage', 'parentCard']);
const DIAGRAM_IMPORT_RELATED_MODES = new Set(['stage']);

function diagramImportHasExplicitMaterialization(mapping) {
  const candidate = mapping && typeof mapping === 'object' && !Array.isArray(mapping) ? mapping : {};
  const materialization = candidate.materialization && typeof candidate.materialization === 'object' && !Array.isArray(candidate.materialization)
    ? candidate.materialization
    : null;
  return Boolean(materialization && DIAGRAM_IMPORT_MATERIALIZATION_KINDS.has(String(materialization.kind || '').trim()));
}

function diagramImportStoredMaterializationIssues(imported) {
  const tree = imported && imported.structureTree && typeof imported.structureTree === 'object' && !Array.isArray(imported.structureTree)
    ? imported.structureTree
    : {};
  const items = Array.isArray(tree.items) ? tree.items : [];
  const issues = [];
  for (const item of items) {
    const mapping = item && item.mapping && typeof item.mapping === 'object' && !Array.isArray(item.mapping) ? item.mapping : {};
    const itemId = String(item && item.id || '').trim();
    if (!diagramImportHasExplicitMaterialization(mapping)) issues.push(`materialization:${itemId || 'unknown'}`);
    if (Object.prototype.hasOwnProperty.call(mapping, 'source')) issues.push(`legacySource:${itemId || 'unknown'}`);
    for (const related of Array.isArray(mapping.related) ? mapping.related : []) {
      if (String(related && related.mode || '') === 'traversal' || (Array.isArray(related && related.path) && related.path.length)) {
        issues.push(`relatedTraversal:${itemId || 'unknown'}`);
      }
    }
  }
  for (const rule of Array.isArray(imported && imported.relationRules) ? imported.relationRules : []) {
    if (String(rule && rule.mode || 'direct') === 'direct' || (Array.isArray(rule && rule.path) && rule.path.length)) {
      issues.push(`connectionTraversal:${String(rule && rule.id || 'unknown')}`);
    }
  }
  return issues;
}

function normalizeDiagramImportMaterialization(role, value) {
  const candidate = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
  const requested = String(candidate.kind || '').trim();
  const kind = DIAGRAM_IMPORT_MATERIALIZATION_KINDS.has(requested)
    ? requested
    : '';
  return {
    kind,
    stageId: kind === 'stage' ? String(candidate.stageId || '').trim() : ''
  };
}

function diagramImportOwnMaterializedStageId(mapping) {
  const materialization = mapping && mapping.materialization || {};
  return String(materialization.kind || '') === 'stage'
    ? String(materialization.stageId || '').trim()
    : '';
}

function normalizeDiagramImportConditionOperandKind(value) {
  const kind = String(value || '').trim();
  return ['literal', 'param', 'stage'].includes(kind) ? kind : 'literal';
}

function normalizeDiagramImportRelatedMode(value) {
  const mode = String(value || '').trim();
  return DIAGRAM_IMPORT_RELATED_MODES.has(mode) ? mode : 'stage';
}

function normalizeDiagramImportRelatedLabelValueMode(value) {
  const mode = String(value || '').trim();
  return ['none', 'single', 'join'].includes(mode) ? mode : 'single';
}

function normalizeDiagramImportConditionOperator(value) {
  const operator = String(value || 'equals').trim();
  if (operator === 'notEquals') return 'equals';
  return DIAGRAM_IMPORT_CONDITION_OPERATORS.has(operator) ? operator : 'equals';
}

function normalizeDiagramImportConditionCardSource(value) {
  const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
  const className = String(source.className || '').trim();
  const classColumn = String(source.classColumn || '').trim();
  const idColumn = String(source.idColumn || '').trim();
  if (!className || !classColumn || !idColumn) return null;
  return {
    id: String(source.id || `${classColumn}:${idColumn}`).trim(),
    className,
    classColumn,
    idColumn,
    label: String(source.label || '').trim()
  };
}

function diagramImportPlacementFilters(value) {
  const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
  const rawRules = Array.isArray(source.rules) ? source.rules : [];
  return {
    ruleJoin: source.ruleJoin === 'all' ? 'all' : 'any',
    rules: rawRules.map((rule, index) => {
      const candidate = rule && typeof rule === 'object' && !Array.isArray(rule) ? rule : {};
      const left = candidate.left && typeof candidate.left === 'object' && !Array.isArray(candidate.left) ? candidate.left : {};
      const right = candidate.right && typeof candidate.right === 'object' && !Array.isArray(candidate.right) ? candidate.right : {};
      const leftSource = normalizeDiagramImportConditionCardSource(left.source || candidate.leftSource);
      const rightSource = normalizeDiagramImportConditionCardSource(right.source || candidate.rightSource);
      const rightKind = normalizeDiagramImportConditionOperandKind(right.kind || candidate.rightKind || (candidate.rightStageId ? 'stage' : candidate.rightParam ? 'param' : 'literal'));
      const rawOperator = candidate.operator || candidate.op || 'equals';
      return {
        id: String(candidate.id || diagramImportStableId('condition', `${index}:${left.column || candidate.leftColumn || ''}:${right.column || candidate.rightColumn || ''}`)).trim(),
        action: candidate.action === 'exclude' || candidate.scope === 'exclude' ? 'exclude' : 'include',
        negate: Boolean(candidate.negate || rawOperator === 'notEquals'),
        ...(candidate.origin === 'assistant' ? { origin: 'assistant' } : {}),
        operator: normalizeDiagramImportConditionOperator(rawOperator),
        caseSensitive: candidate.caseSensitive === true,
        left: {
          column: String(left.column || left.field || left.path || candidate.leftColumn || candidate.leftField || '').trim(),
          regex: String(left.regex !== undefined ? left.regex : candidate.leftRegex || '').trim(),
          ...(leftSource ? { source: leftSource } : {})
        },
        right: {
          kind: rightKind,
          value: right.value !== undefined ? right.value : (candidate.rightValue !== undefined ? candidate.rightValue : ''),
          name: String(right.name || right.param || candidate.rightParam || candidate.valueParam || '').trim(),
          stageId: String(right.stageId || candidate.rightStageId || '').trim(),
          column: String(right.column || right.field || right.path || candidate.rightColumn || candidate.rightField || '').trim(),
          regex: String(right.regex !== undefined ? right.regex : candidate.rightRegex || '').trim(),
          ...(rightSource ? { source: rightSource } : {})
        }
      };
    })
  };
}

function diagramImportRoleMappingData(role, source = {}, mappingIndex = 0) {
  const candidate = source && typeof source === 'object' && !Array.isArray(source) ? source : {};
  const primary = candidate.primary && typeof candidate.primary === 'object' && !Array.isArray(candidate.primary) ? candidate.primary : {};
  return {
    id: String(candidate.id || diagramImportStableId('role_mapping', `${role.id}:${mappingIndex}`)).trim(),
    label: truncateText(String(candidate.label || candidate.name || '').trim(), 160),
    materialization: normalizeDiagramImportMaterialization(role, candidate.materialization),
    // Preserve the current visual result until an author explicitly hides an
    // empty container. Nodes have no empty-container policy.
    ...(diagramImportRoleVisualKind(role) === 'container' ? { showEmpty: candidate.showEmpty !== false } : {}),
    primary: {
      className: String(primary.className || '').trim(),
      idAttribute: diagramImportPrimaryIdAttribute(role, primary),
      labelTemplate: String(primary.labelTemplate || '${Description}'),
      structuredFields: diagramImportPrimaryStructuredFields(role, primary),
      filters: []
    },
    conditions: diagramImportPlacementFilters(candidate.conditions),
    hierarchyConditions: diagramImportPlacementFilters(candidate.hierarchyConditions),
    related: (Array.isArray(candidate.related) ? candidate.related : []).map((item, relatedIndex) => ({
      id: String(item && item.id || diagramImportStableId('related', `${role.id}:${mappingIndex}:${relatedIndex}`)),
      stageId: String(item && item.stageId || '').trim(),
      legacyTraversal: Boolean(String(item && item.mode || '') === 'traversal' || (Array.isArray(item && item.path) && item.path.length)),
      labelValueMode: normalizeDiagramImportRelatedLabelValueMode(item && item.labelValueMode),
      labelSeparator: String(item && item.labelSeparator || ', '),
      structuredFields: uniqueStrings(item && item.structuredFields || []),
      conditions: diagramImportPlacementFilters(item && item.conditions)
    })).filter((item) => item.stageId || item.structuredFields.length || item.conditions.rules.length || item.legacyTraversal)
  };
}

function diagramImportRoleMapping(role, existing = {}) {
  const source = existing && typeof existing === 'object' && !Array.isArray(existing) ? existing : {};
  return {
    id: String(source.id || diagramImportStableId('role_mapping', role.id)).trim(),
    roleId: role.id,
    ...diagramImportRoleMappingData(role, source)
  };
}

function diagramImportStructureItemMapping(role, existing = {}, itemId = '') {
  const mapping = diagramImportRoleMappingData(role, existing, 0);
  mapping.id = String(existing && existing.id || diagramImportStableId('structure_mapping', `${role && role.id || 'role'}:${itemId || 'item'}`)).trim();
  mapping.roleId = String(role && role.id || '');
  return mapping;
}

function diagramImportContainerSignature(structure, key) {
  const elements = structure && typeof structure === 'object' ? structure : {};
  const all = (Array.isArray(elements.nodes) ? elements.nodes : []).concat(Array.isArray(elements.groups) ? elements.groups : []);
  return all.filter((item) => String(item && item.parentKey || '') === String(key || '')).map((item) => ({
    kind: Array.isArray(elements.groups) && elements.groups.some((group) => group && group.key === item.key) ? 'group' : 'node',
    classes: uniqueStrings(item && item.classKeys || []).sort()
  })).sort((left, right) => JSON.stringify(left).localeCompare(JSON.stringify(right)));
}

function diagramImportRoleExemplar(role, structure) {
  if (!role.exemplarRequired) return { key: role.exemplarKey || '', automatic: false };
  const candidates = Array.isArray(role.containerKeys) ? role.containerKeys.filter(Boolean) : [];
  if (!candidates.length) return { key: '', automatic: false };
  const signatures = candidates.map((key) => JSON.stringify(diagramImportContainerSignature(structure, key)));
  return signatures.every((signature) => signature === signatures[0])
    ? { key: candidates[0], automatic: true }
    : { key: '', automatic: false };
}

function diagramImportClassRoleDefinitions(ir) {
  const elements = ir && ir.elements || { nodes: [], groups: [] };
  const allElements = (elements.nodes || []).concat(elements.groups || []);
  const declared = new Map((Array.isArray(ir && ir.classes) ? ir.classes : []).map((item) => [String(item.key || ''), item]));
  for (const element of allElements) {
    for (const classKey of Array.isArray(element && element.classKeys) ? element.classKeys : []) {
      if (!declared.has(classKey)) declared.set(classKey, normalizeDiagramImportClass({ key: classKey }));
    }
  }
  const roles = [];
  for (const [classKey, definition] of declared.entries()) {
    const usages = allElements.filter((item) => Array.isArray(item.classKeys) && item.classKeys.includes(classKey));
    if (!usages.length) continue;
    const containerUsages = usages.filter((item) => (elements.groups || []).some((group) => group.key === item.key));
    // D2 nesting is a layout template, not evidence that a CMDB object owns a
    // separate repeated frame. Containers start once and are made dynamic only
    // by an explicit reviewed repeat rule.
    const visualKind = containerUsages.length ? 'container' : 'node';
    roles.push({
      id: diagramImportStableId('d2_class', classKey),
      kind: 'd2Class',
      key: classKey,
      label: definition.label || classKey,
      notes: String(definition.notes || '').trim(),
      elementKeys: usages.map((item) => item.key),
      containerKeys: containerUsages.map((item) => item.key),
      visualKind,
      labelTemplate: visualKind === 'container' ? (definition.label || classKey) : '${Description}',
      visualKindOptions: [visualKind],
      suggestedSemantic: visualKind === 'container' ? 'structural' : 'object',
      semanticReason: containerUsages.length
        ? `D2 class is used by ${containerUsages.length} container object(s). The saved structure tree controls its placement and repetition.`
        : `D2 class is used by ${usages.length} leaf object(s).`,
      options: visualKind === 'container' ? ['container'] : ['node'],
      exemplarKey: '',
      exemplarRequired: false,
      styleHints: cloneJsonValueServer(definition.styleHints, {})
    });
  }
  for (const group of elements.groups || []) {
    if (Array.isArray(group.classKeys) && group.classKeys.length) continue;
    roles.push({
      id: diagramImportStableId('d2_container', group.key),
      kind: 'untypedContainer',
      key: group.key,
      label: group.label || group.key,
      elementKeys: [group.key],
      containerKeys: [group.key],
      visualKind: 'container',
      labelTemplate: group.label || group.key,
      visualKindOptions: ['container'],
      suggestedSemantic: 'structural',
      semanticReason: 'D2 container has no reusable D2 class and starts as one template layout role.',
      options: ['container'],
      exemplarKey: '',
      exemplarRequired: false,
      styleHints: cloneJsonValueServer(group.styleHints, {})
    });
  }
  return roles;
}

function diagramImportWithRoleModelCandidates(roles, structure) {
  const modeled = (Array.isArray(roles) ? roles : []).map((role) => diagramImportApplyRoleModel(role));
  return modeled.map((role) => ({
    ...role,
    allowedOwnerRoleIds: [],
    allowedGroupSourceRoleIds: []
  }));
}

function diagramImportPreviousRoleModel(role, previousRole) {
  const previous = previousRole && typeof previousRole === 'object' ? previousRole : {};
  if (Number(previous.semanticModelRevision || 0) !== D2_IMPORT_SEMANTIC_MODEL_REVISION) {
    return diagramImportApplyRoleModel(role);
  }
  return diagramImportApplyRoleModel({
    ...role,
    visualKind: previous.visualKind,
    labelTemplate: previous.labelTemplate || role.labelTemplate
  });
}

function normalizeDiagramDirectionPolicy(value) {
  const policy = String(value || '').trim();
  return ['dataFields', 'template', 'undirected'].includes(policy) ? policy : '';
}

function diagramImportDirectionPolicySuggestion(rule) {
  const direction = String(rule && rule.direction || '').trim();
  if (direction === '<->' || direction === '--') return 'undirected';
  const text = [
    rule && rule.d2ClassKey,
    rule && rule.d2Notes,
    ...(Array.isArray(rule && rule.d2ExampleLabels) ? rule.d2ExampleLabels : [])
  ].map((item) => String(item || '')).join('\n');
  return /(?:\bacl\b|\b(?:tcp|udp|sctp|icmp)\b|source|destination|источник|назначени|endpoint|ip\s*address)/i.test(text)
    ? 'dataFields'
    : 'template';
}

function diagramImportEffectiveSourceStageId(role, item) {
  const mapping = diagramImportStructureItemMapping(role || {}, item && item.mapping || {}, item && item.id || '');
  return diagramImportOwnMaterializedStageId(mapping);
}

function diagramImportNearestMaterializedAncestor(tree, roles, item) {
  const items = Array.isArray(tree && tree.items) ? tree.items : [];
  const itemById = new Map(items.map((candidate) => [String(candidate && candidate.id || ''), candidate]).filter(([id]) => id));
  const roleById = new Map((Array.isArray(roles) ? roles : []).map((role) => [String(role && role.id || ''), role]));
  const visited = new Set([String(item && item.id || '')]);
  let parentId = String(item && item.parentId || '');
  while (parentId && !visited.has(parentId)) {
    visited.add(parentId);
    const parent = itemById.get(parentId);
    if (!parent) return null;
    const parentRole = roleById.get(String(parent.roleId || '')) || {};
    const parentMapping = diagramImportStructureItemMapping(parentRole, parent.mapping || {}, parent.id || '');
    const stageId = diagramImportOwnMaterializedStageId(parentMapping);
    if (stageId) return { item: parent, role: parentRole, mapping: parentMapping, stageId };
    parentId = String(parent.parentId || '');
  }
  return null;
}

// Older saved mappings stored parent-child comparisons beside ordinary result
// filters. They execute identically, but must remain editable in the dedicated
// hierarchy editor after the contract split.
function diagramImportMigrateLegacyHierarchyConditions(tree, roles) {
  const normalized = tree && typeof tree === 'object' && !Array.isArray(tree)
    ? tree
    : { version: D2_IMPORT_STRUCTURE_TREE_VERSION, items: [] };
  const roleById = new Map((Array.isArray(roles) ? roles : [])
    .map((role) => [String(role && role.id || ''), role]));
  for (const item of Array.isArray(normalized.items) ? normalized.items : []) {
    const role = roleById.get(String(item && item.roleId || '')) || {};
    const mapping = diagramImportStructureItemMapping(role, item && item.mapping || {}, item && item.id || '');
    const ancestor = diagramImportNearestMaterializedAncestor(normalized, roles, item);
    const ownStageId = diagramImportOwnMaterializedStageId(mapping);
    if (!ancestor || !ancestor.stageId || !ownStageId || ownStageId === String(ancestor.stageId)) {
      item.mapping = mapping;
      continue;
    }
    const conditions = diagramImportPlacementFilters(mapping.conditions);
    const hierarchyConditions = diagramImportPlacementFilters(mapping.hierarchyConditions);
    const retained = [];
    for (const condition of conditions.rules) {
      const isLegacyHierarchyCondition = condition && condition.action === 'include' && !condition.negate &&
        condition.right && condition.right.kind === 'stage' &&
        String(condition.right.stageId || '') === String(ancestor.stageId || '');
      if (!isLegacyHierarchyCondition) {
        retained.push(condition);
        continue;
      }
      const duplicate = hierarchyConditions.rules.some((existing) => (
        String(existing && existing.action || '') === String(condition.action || '') &&
        Boolean(existing && existing.negate) === Boolean(condition.negate) &&
        String(existing && existing.operator || '') === String(condition.operator || '') &&
        String(existing && existing.left && existing.left.column || '') === String(condition.left && condition.left.column || '') &&
        String(existing && existing.right && existing.right.stageId || '') === String(condition.right && condition.right.stageId || '') &&
        String(existing && existing.right && existing.right.column || '') === String(condition.right && condition.right.column || '')
      ));
      if (!duplicate) hierarchyConditions.rules.push(condition);
    }
    item.mapping = {
      ...mapping,
      conditions: { ...conditions, rules: retained },
      hierarchyConditions
    };
  }
  return normalized;
}

function diagramImportSourceProvenanceDescriptor(fieldName) {
  let value = String(fieldName || '');
  let depth = 0;
  while (value.startsWith('Source_')) {
    value = value.slice('Source_'.length);
    depth += 1;
  }
  const technicalFields = new Set([
    'Class', '_id', 'Id', 'Code', 'Description', 'SourceClass', 'SourceId',
    'SourceCode', 'SourceDescription', 'Domain', 'RelationId',
    'RelationDirection', 'RelationSourceSide', 'RelatedClass', 'RelatedId'
  ]);
  if (!depth || !value || technicalFields.has(value)) return null;
  return { tail: value, depth };
}

function diagramImportParentCorrelationCandidates(sourceStage, parentStage) {
  const fieldsByTail = (stage) => {
    const result = new Map();
    for (const field of Array.isArray(stage && stage.columns) ? stage.columns : []) {
      const name = String(field || '');
      const descriptor = diagramImportSourceProvenanceDescriptor(name);
      if (!descriptor) continue;
      const fields = result.get(descriptor.tail) || [];
      fields.push({ name, ...descriptor });
      result.set(descriptor.tail, fields);
    }
    return result;
  };
  const sourceByTail = fieldsByTail(sourceStage);
  const parentByTail = fieldsByTail(parentStage);
  const candidates = [];
  for (const [tail, sourceFields] of sourceByTail.entries()) {
    const parentFields = parentByTail.get(tail) || [];
    if (sourceFields.length !== 1 || parentFields.length !== 1) continue;
    candidates.push({
      leftColumn: sourceFields[0].name,
      rightColumn: parentFields[0].name,
      tail,
      provenanceDepth: sourceFields[0].depth + parentFields[0].depth
    });
  }
  if (!candidates.length) return [];
  const minimumDepth = Math.min(...candidates.map((candidate) => candidate.provenanceDepth));
  return candidates.filter((candidate) => candidate.provenanceDepth === minimumDepth);
}

function diagramImportPreviewTreeWithParentCorrelationRepairs(tree, roles, currentSpec = {}, structure = null) {
  const normalized = diagramImportStructureTree(tree, structure, roles);
  const repairedTree = cloneJsonValueServer(normalized, { version: D2_IMPORT_STRUCTURE_TREE_VERSION, items: [] });
  const stages = new Map(assistantObjectFlowDiagramStages(currentSpec, objectFlowFromSpecServer(currentSpec))
    .map((stage) => [String(stage && stage.id || ''), stage]));
  const roleById = new Map((Array.isArray(roles) ? roles : []).map((role) => [String(role && role.id || ''), role]));
  const repairs = [];

  for (const item of repairedTree.items || []) {
    const role = roleById.get(String(item && item.roleId || '')) || {};
    const mapping = diagramImportStructureItemMapping(role, item && item.mapping || {}, item && item.id || '');
    const stageId = diagramImportOwnMaterializedStageId(mapping);
    if (!stageId) continue;
    const ancestor = diagramImportNearestMaterializedAncestor(repairedTree, roles, item);
    if (!ancestor || !ancestor.stageId || String(ancestor.stageId) === stageId) continue;
    const sourceStage = stages.get(stageId);
    const parentStage = stages.get(String(ancestor.stageId));
    if (!sourceStage || !parentStage || diagramImportStageDirectlyDependsOn(sourceStage, parentStage)) continue;
    const hierarchyConditions = diagramImportPlacementFilters(mapping.hierarchyConditions);
    const hasParentCondition = hierarchyConditions.rules.some((condition) => condition && condition.right &&
      condition.right.kind === 'stage' && String(condition.right.stageId || '') === String(ancestor.stageId));
    if (hasParentCondition) continue;
    const candidates = diagramImportParentCorrelationCandidates(sourceStage, parentStage);
    if (candidates.length !== 1) continue;
    const candidate = candidates[0];
    hierarchyConditions.rules.push({
      id: diagramImportStableId('preview_parent_correlation', `${item.id}:${stageId}:${ancestor.stageId}:${candidate.leftColumn}:${candidate.rightColumn}`),
      action: 'include',
      negate: false,
      operator: 'equals',
      caseSensitive: false,
      left: { column: candidate.leftColumn, regex: '' },
      right: { kind: 'stage', stageId: String(ancestor.stageId), column: candidate.rightColumn, regex: '', value: '', name: '' }
    });
    item.mapping = { ...mapping, hierarchyConditions };
    repairs.push({
      structureItemId: String(item.id || ''),
      roleLabel: String(role.label || role.key || item.id || ''),
      parentRoleLabel: String(ancestor.role && (ancestor.role.label || ancestor.role.key) || '')
    });
  }
  return { tree: repairedTree, repairs };
}

function diagramImportStructureTreeContextCatalog(structure, roles) {
  const all = [].concat(
    Array.isArray(structure && structure.groups) ? structure.groups : [],
    Array.isArray(structure && structure.nodes) ? structure.nodes : []
  ).slice().sort((left, right) => {
    const leftDepth = Array.isArray(left && left.pathSegments) ? left.pathSegments.length : 0;
    const rightDepth = Array.isArray(right && right.pathSegments) ? right.pathSegments.length : 0;
    return leftDepth - rightDepth || String(left && left.key || '').localeCompare(String(right && right.key || ''));
  });
  const roleByElementKey = new Map();
  for (const role of Array.isArray(roles) ? roles : []) {
    for (const elementKey of Array.isArray(role && role.elementKeys) ? role.elementKeys : []) {
      if (elementKey && !roleByElementKey.has(String(elementKey))) roleByElementKey.set(String(elementKey), role);
    }
  }
  const contextByElementKey = new Map();
  const contextsByKey = new Map();
  for (const element of all) {
    const elementKey = String(element && element.key || '').trim();
    const role = roleByElementKey.get(elementKey) || {};
    if (!elementKey || !role.id) continue;
    const parentContextKey = contextByElementKey.get(String(element && element.parentKey || '').trim()) || '';
    const parentContext = contextsByKey.get(parentContextKey) || null;
    const rolePath = parentContext
      ? parentContext.rolePath.concat(String(role.id))
      : [String(role.id)];
    const key = diagramImportStableId('structure_context', rolePath.join('>'));
    const context = contextsByKey.get(key) || {
      key,
      roleId: String(role.id),
      rolePath,
      parentContextKey,
      elementKeys: []
    };
    context.elementKeys.push(elementKey);
    contextsByKey.set(key, context);
    contextByElementKey.set(elementKey, key);
  }
  return Array.from(contextsByKey.values()).map((context) => ({
    ...context,
    elementKeys: uniqueStrings(context.elementKeys).sort()
  })).sort((left, right) => left.rolePath.length - right.rolePath.length || left.key.localeCompare(right.key));
}

function diagramImportStructureTreeContextByKey(structure, roles) {
  return new Map(diagramImportStructureTreeContextCatalog(structure, roles).map((context) => [context.key, context]));
}

function diagramImportStructureTreeSeed(structure, roles) {
  const roleById = new Map((Array.isArray(roles) ? roles : []).map((role) => [String(role && role.id || ''), role]));
  const contexts = diagramImportStructureTreeContextCatalog(structure, roles);
  const itemIdByContextKey = new Map(contexts.map((context) => [context.key, diagramImportStableId('structure_item', context.key)]));
  return contexts.map((context) => {
    const role = roleById.get(context.roleId) || {};
    const itemId = itemIdByContextKey.get(context.key) || diagramImportStableId('structure_item', context.key);
    const mapping = diagramImportStructureItemMapping(role, {}, itemId);
    // This is a new analysis proposal, not persisted authoring. Seed an
    // explicit choice so later validation can distinguish it from an older
    // saved tree that omitted materialization altogether.
    mapping.materialization = {
      kind: diagramImportRoleVisualKind(role) === 'container' ? 'structural' : 'stage',
      stageId: ''
    };
    return {
      id: itemId,
      roleId: String(role.id || ''),
      templateContextKey: context.key,
      templateElementKey: String(context.elementKeys[0] || ''),
      templateElementKeys: context.elementKeys,
      parentId: itemIdByContextKey.get(context.parentContextKey) || '',
      mapping
    };
  });
}

function diagramImportStructureTree(value, structure, roles) {
  const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
  const hasExplicitItems = Array.isArray(value) || Object.prototype.hasOwnProperty.call(source, 'items');
  const rawItems = Array.isArray(value)
    ? value
    : Array.isArray(source.items)
      ? source.items
      : [];
  const roleById = new Map((Array.isArray(roles) ? roles : []).map((role) => [String(role && role.id || ''), role]));
  const normalized = rawItems.slice(0, D2_IMPORT_MAX_ELEMENTS).map((item, index) => {
    const roleId = String(item && item.roleId || '').trim();
    const role = roleById.get(roleId) || {};
    const requestedElementKey = String(item && item.templateElementKey || '').trim();
    const requestedElementKeys = uniqueStrings(Array.isArray(item && item.templateElementKeys) ? item.templateElementKeys : [requestedElementKey]).sort();
    return {
      id: String(item && item.id || diagramImportStableId('structure_item', `${roleId}:${requestedElementKey}:${index}`)).trim(),
      roleId,
      templateContextKey: String(item && item.templateContextKey || '').trim(),
      // Preserve explicit values so validation can report stale or invalid
      // structural contexts instead of silently moving a mapped item.
      templateElementKey: requestedElementKey || String(requestedElementKeys[0] || '').trim(),
      templateElementKeys: requestedElementKeys,
      parentId: String(item && item.parentId || '').trim(),
      mapping: diagramImportStructureItemMapping(role, item && item.mapping || {}, String(item && item.id || `${roleId}:${requestedElementKey}:${index}`))
    };
  }).filter((item) => item.id);
  const itemById = new Map(normalized.map((item) => [String(item && item.id || ''), item]).filter(([id]) => id));
  for (const item of normalized) {
    const role = roleById.get(String(item && item.roleId || '')) || {};
    const mapping = diagramImportStructureItemMapping(role, item && item.mapping || {}, item && item.id || '');
    const stageId = String(mapping && mapping.materialization && mapping.materialization.kind === 'stage' && mapping.materialization.stageId || '').trim();
    if (!stageId || diagramImportRoleVisualKind(role) !== 'node') continue;
    const visited = new Set([String(item.id || '')]);
    let parentId = String(item.parentId || '');
    while (parentId && !visited.has(parentId)) {
      visited.add(parentId);
      const parent = itemById.get(parentId);
      if (!parent) break;
      const parentRole = roleById.get(String(parent.roleId || '')) || {};
      const parentMapping = diagramImportStructureItemMapping(parentRole, parent.mapping || {}, parent.id || '');
      const parentStageId = String(parentMapping && parentMapping.materialization && parentMapping.materialization.kind === 'stage' && parentMapping.materialization.stageId || '').trim();
      if (parentStageId) {
        // A nested node mapped to the same deterministic rows as its nearest
        // materialized container inherits that card. Keeping it as an own
        // stage creates duplicate rows and requires an artificial correlation.
        if (parentStageId === stageId) {
          item.mapping = {
            ...mapping,
            materialization: { kind: 'parentCard', stageId: '' }
          };
        }
        break;
      }
      parentId = String(parent.parentId || '');
    }
  }
  return diagramImportMigrateLegacyHierarchyConditions({
    version: D2_IMPORT_STRUCTURE_TREE_VERSION,
    items: hasExplicitItems ? normalized : diagramImportStructureTreeSeed(structure, roles)
  }, roles);
}

function diagramImportCopiedStructureMapping(role, sourceMapping = {}, itemId = '') {
  const mapping = diagramImportStructureItemMapping(role, cloneJsonValueServer(sourceMapping, {}), itemId);
  mapping.id = diagramImportStableId('structure_mapping', `${role && role.id || 'role'}:${itemId || 'item'}`);
  mapping.materialization = normalizeDiagramImportMaterialization(role, mapping.materialization);
  // A branch copy is another instance of the same declared template context.
  // Preserve its complete deterministic binding; the user can then change the
  // copied branch deliberately instead of reconstructing every predicate.
  delete mapping.source;
  return mapping;
}

function diagramImportCloneStructureBranch(tree, structure, roles, sourceItemId) {
  const normalized = diagramImportStructureTree(tree, structure, roles);
  const sourceId = String(sourceItemId || '').trim();
  const source = normalized.items.find((item) => String(item && item.id || '') === sourceId);
  const roleById = new Map((Array.isArray(roles) ? roles : []).map((role) => [String(role && role.id || ''), role]));
  const sourceRole = source && roleById.get(String(source.roleId || ''));
  if (!source || !sourceRole || diagramImportRoleVisualKind(sourceRole) !== 'container') return null;
  const branchIds = new Set([sourceId]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const item of normalized.items) {
      const itemId = String(item && item.id || '');
      if (branchIds.has(String(item && item.parentId || '')) && !branchIds.has(itemId)) {
        branchIds.add(itemId);
        changed = true;
      }
    }
  }
  const branch = normalized.items.filter((item) => branchIds.has(String(item && item.id || '')));
  const usedIds = new Set(normalized.items.map((item) => String(item && item.id || '')));
  const copiedIds = new Map();
  for (const [index, item] of branch.entries()) {
    const sourceKey = String(item && item.id || '');
    let attempt = index + 1;
    let copyId = diagramImportStableId('structure_item_copy', `${sourceId}:${sourceKey}:${attempt}`);
    while (usedIds.has(copyId)) {
      attempt += 1;
      copyId = diagramImportStableId('structure_item_copy', `${sourceId}:${sourceKey}:${attempt}`);
    }
    usedIds.add(copyId);
    copiedIds.set(sourceKey, copyId);
  }
  const copies = branch.map((item) => {
    const itemId = copiedIds.get(String(item && item.id || ''));
    const role = roleById.get(String(item && item.roleId || '')) || {};
    return {
      ...item,
      id: itemId,
      parentId: copiedIds.get(String(item && item.parentId || '')) || String(item && item.parentId || ''),
      mapping: diagramImportCopiedStructureMapping(role, item && item.mapping || {}, itemId)
    };
  });
  return {
    tree: { version: D2_IMPORT_STRUCTURE_TREE_VERSION, items: normalized.items.concat(copies) },
    rootId: copiedIds.get(sourceId),
    copiedItemIds: copies.map((item) => item.id)
  };
}

function diagramImportStageDirectlyDependsOn(stage, ancestorStage) {
  const parentAlias = String(ancestorStage && ancestorStage.alias || '').trim();
  if (!parentAlias || String(stage && stage.from || '').trim() !== parentAlias) return false;
  // A relation expansion reads each child row from the already selected parent
  // rows. This is an explicit deterministic parent-child contract, not an
  // implicit label or class-name match, so it needs no duplicate UI predicate.
  return String(stage && stage.kind || '').trim() === 'relation';
}

function diagramImportChildLabelTokenErrors(tree, roles) {
  const errors = [];
  const items = Array.isArray(tree && tree.items) ? tree.items : [];
  const itemById = new Map(items.map((item, index) => [String(item && item.id || ''), { item, index }]).filter(([id]) => id));
  const roleById = new Map((Array.isArray(roles) ? roles : []).map((role) => [String(role && role.id || ''), role]));
  for (const [index, item] of items.entries()) {
    const role = roleById.get(String(item && item.roleId || '')) || {};
    const mapping = diagramImportStructureItemMapping(role, item && item.mapping || {}, item && item.id || '');
    const templatePath = `$.structureTree.items[${index}].mapping.primary.labelTemplate`;
    for (const entry of diagramImportChildTemplateTokens(mapping.primary && mapping.primary.labelTemplate || '')) {
      const descriptor = entry.descriptor;
      if (!descriptor) {
        errors.push({ path: templatePath, message: `Child label token ${entry.token} is invalid.` });
        continue;
      }
      if (diagramImportRoleVisualKind(role) !== 'container') {
        errors.push({ path: templatePath, message: 'Only a D2 container label may reference a direct child element.' });
        continue;
      }
      const childEntry = itemById.get(String(descriptor.itemId || ''));
      if (!childEntry || String(childEntry.item && childEntry.item.parentId || '') !== String(item && item.id || '')) {
        errors.push({ path: templatePath, message: `Child label token ${entry.token} must reference a direct child of this container.` });
        continue;
      }
      const childRole = roleById.get(String(childEntry.item && childEntry.item.roleId || '')) || {};
      if (diagramImportRoleVisualKind(childRole) !== 'node') {
        errors.push({ path: templatePath, message: `Child label token ${entry.token} must reference a direct D2 node placement.` });
        continue;
      }
      const childMapping = diagramImportStructureItemMapping(childRole, childEntry.item && childEntry.item.mapping || {}, childEntry.item && childEntry.item.id || '');
      if (descriptor.kind === 'primary') {
        const fields = new Set(diagramImportPrimaryStructuredFields(childRole, childMapping.primary || {}));
        if (!fields.has(descriptor.field)) {
          errors.push({ path: templatePath, message: `Child label token ${entry.token} requires materialized field ${descriptor.field} on the direct child mapping.` });
        }
        continue;
      }
      const related = (childMapping.related || []).find((candidate) => diagramImportRelatedBindingSignatureServer(candidate) === descriptor.pathSignature);
      if (!related || !(related.structuredFields || []).map(String).includes(descriptor.field)) {
        errors.push({ path: templatePath, message: `Child label token ${entry.token} requires a matching direct-child related binding and field.` });
      }
    }
  }
  return errors;
}

function diagramImportLabelTemplateSyntaxErrors(template, path) {
  const errors = [];
  const source = String(template || '');
  let offset = 0;
  while (offset < source.length) {
    const start = source.indexOf('${', offset);
    if (start < 0) break;
    const end = source.indexOf('}', start + 2);
    if (end < 0) {
      errors.push({ path, message: 'D2 label template contains an unterminated placeholder.' });
      break;
    }
    if (!source.slice(start + 2, end).trim()) {
      errors.push({ path, message: 'D2 label template contains an empty placeholder.' });
    }
    offset = end + 1;
  }
  return errors;
}

function diagramImportStructureTreeErrors(tree, roles, currentSpec = {}, structure = null) {
  const errors = [];
  if (!tree || typeof tree !== 'object' || Array.isArray(tree) || Number(tree.version || 0) !== D2_IMPORT_STRUCTURE_TREE_VERSION || !Array.isArray(tree.items)) {
    return [{ path: '$.structureTree', message: `D2 mapping must define a persisted structureTree version ${D2_IMPORT_STRUCTURE_TREE_VERSION}. Analyze the current D2 source again.` }];
  }
  for (const [index, item] of tree.items.entries()) {
    const mapping = item && item.mapping && typeof item.mapping === 'object' && !Array.isArray(item.mapping) ? item.mapping : {};
    if (!diagramImportHasExplicitMaterialization(mapping)) {
      errors.push({
        path: `$.structureTree.items[${index}].mapping.materialization`,
        message: 'D2 placement must persist an explicit materialization. Choose structural, stage, or parentCard before applying the mapping.'
      });
    }
    if (Object.prototype.hasOwnProperty.call(mapping, 'source')) {
      errors.push({
        path: `$.structureTree.items[${index}].mapping.source`,
        message: 'D2 placement uses the retired source mapping. Choose an explicit materialization in Diagram Editor or apply a current Assistant proposal.'
      });
    }
  }
  const normalized = diagramImportStructureTree(tree, structure, roles);
  const items = normalized.items;
  const itemById = new Map();
  const roleById = new Map((Array.isArray(roles) ? roles : []).map((role) => [String(role && role.id || ''), role]));
  const contextByKey = diagramImportStructureTreeContextByKey(structure, roles);
  for (const [index, item] of items.entries()) {
    if (itemById.has(item.id)) {
      errors.push({ path: `$.structureTree.items[${index}].id`, message: `Structure item id ${item.id} is duplicated.` });
      continue;
    }
    itemById.set(item.id, item);
    const role = roleById.get(item.roleId);
    if (!role) {
      errors.push({ path: `$.structureTree.items[${index}].roleId`, message: `Structure item references an unavailable D2 role ${item.roleId || '(empty)'}.` });
      continue;
    }
    if (!Array.isArray(role.elementKeys) || !role.elementKeys.map(String).includes(item.templateElementKey)) {
      errors.push({ path: `$.structureTree.items[${index}].templateElementKey`, message: `Structure item ${item.id} must use a D2 element declared by role ${role.label || role.key || role.id}.` });
    }
    const context = contextByKey.get(String(item.templateContextKey || ''));
    if (!item.templateContextKey || !context) {
      errors.push({ path: `$.structureTree.items[${index}].templateContextKey`, message: `Structure item ${item.id} must use a current D2 template context. Analyze the current D2 source again.` });
    } else {
      if (String(context.roleId || '') !== String(item.roleId || '')) {
        errors.push({ path: `$.structureTree.items[${index}].templateContextKey`, message: `Structure item ${item.id} context does not match D2 role ${role.label || role.key || role.id}.` });
      }
      const contextElementKeys = uniqueStrings(context.elementKeys || []).sort();
      const itemElementKeys = uniqueStrings(item.templateElementKeys || []).sort();
      if (JSON.stringify(contextElementKeys) !== JSON.stringify(itemElementKeys)) {
        errors.push({ path: `$.structureTree.items[${index}].templateElementKeys`, message: `Structure item ${item.id} must retain the complete D2 blueprint set for its template context.` });
      }
      if (String(item.templateElementKey || '') !== String(contextElementKeys[0] || '')) {
        errors.push({ path: `$.structureTree.items[${index}].templateElementKey`, message: `Structure item ${item.id} must use the canonical D2 blueprint for its template context.` });
      }
    }
  }
  const stages = new Map(assistantObjectFlowDiagramStages(currentSpec, objectFlowFromSpecServer(currentSpec))
    .map((stage) => [String(stage && stage.id || ''), stage]));
  for (const [index, item] of items.entries()) {
    const role = roleById.get(item.roleId);
    if (item.parentId) {
      const parent = itemById.get(item.parentId);
      if (!parent) {
        errors.push({ path: `$.structureTree.items[${index}].parentId`, message: `Structure parent ${item.parentId} is unavailable.` });
      } else {
        const parentRole = roleById.get(parent.roleId);
        if (parentRole && diagramImportRoleVisualKind(parentRole) !== 'container') {
          errors.push({ path: `$.structureTree.items[${index}].parentId`, message: `D2 node ${parentRole.label || parentRole.key || parentRole.id} cannot contain children.` });
        }
      }
    }
    const context = contextByKey.get(String(item.templateContextKey || ''));
    if (context) {
      const expectedParentContextKey = String(context.parentContextKey || '');
      const parent = item.parentId ? itemById.get(String(item.parentId || '')) : null;
      if (!expectedParentContextKey && item.parentId) {
        errors.push({ path: `$.structureTree.items[${index}].parentId`, message: `D2 template context for ${role.label || role.key || item.id} must remain at the root.` });
      } else if (expectedParentContextKey && (!parent || String(parent.templateContextKey || '') !== expectedParentContextKey)) {
        errors.push({ path: `$.structureTree.items[${index}].parentId`, message: `D2 template context for ${role.label || role.key || item.id} requires its declared parent container.` });
      }
    }
    const mapping = diagramImportStructureItemMapping(role || {}, item && item.mapping || {}, item && item.id || '');
    errors.push(...diagramImportLabelTemplateSyntaxErrors(
      mapping.primary && mapping.primary.labelTemplate || '',
      `$.structureTree.items[${index}].mapping.primary.labelTemplate`
    ));
    const visualKind = diagramImportRoleVisualKind(role);
    const materialization = mapping.materialization || {};
    const materializationKind = String(materialization.kind || '');
    const ancestor = diagramImportNearestMaterializedAncestor(normalized, roles, item);
    let stageId = '';
    if (materializationKind === 'stage') {
      stageId = String(materialization.stageId || '').trim();
    } else if (materializationKind === 'parentCard') {
      stageId = String(ancestor && ancestor.stageId || '').trim();
      if (visualKind !== 'node') {
        errors.push({ path: `$.structureTree.items[${index}].mapping.materialization.kind`, message: 'Only D2 node placements may inherit a parent card.' });
      }
      if (!stageId) {
        errors.push({ path: `$.structureTree.items[${index}].mapping.materialization.kind`, message: `D2 node placement ${role && (role.label || role.key || role.id) || item.id} has no materialized parent card to inherit.` });
      }
    } else if (materializationKind !== 'structural') {
      errors.push({ path: `$.structureTree.items[${index}].mapping.materialization.kind`, message: 'D2 placement must choose structural, stage, or parentCard materialization.' });
    }
    if (visualKind === 'node' && materializationKind === 'structural') {
      errors.push({
        path: `$.structureTree.items[${index}].mapping.materialization.kind`,
        message: `D2 node placement ${role && (role.label || role.key || role.id) || item.id} must use a stage or inherit a parent card.`
      });
    }
    const conditions = diagramImportPlacementFilters(mapping.conditions);
    const hierarchyConditions = diagramImportPlacementFilters(mapping.hierarchyConditions);
    if (materializationKind === 'structural' && (conditions.rules.length || hierarchyConditions.rules.length)) {
      errors.push({ path: `$.structureTree.items[${index}].mapping.conditions`, message: 'A structural D2 container has no Object Flow source and cannot define data filters.' });
    }
    if (materializationKind === 'stage' && !stageId) {
      errors.push({
        path: `$.structureTree.items[${index}].mapping.materialization.stageId`,
        message: `D2 ${visualKind === 'node' ? 'node' : 'container'} placement ${role && (role.label || role.key || role.id) || item.id} requires a materialized Object Flow result.`
      });
    }
    if (!stageId) continue;
    const stagePath = `$.structureTree.items[${index}].mapping.materialization.stageId`;
    const stage = stages.get(stageId);
    if (!stage) {
      errors.push({ path: stagePath, message: `D2 role ${role && (role.label || role.key) || item.id} references unavailable Object Flow result ${stageId}.` });
      continue;
    }
    if (!String(stage.className || '').trim()) {
      errors.push({ path: stagePath, message: `Object Flow result ${stage.label || stage.id} is not a materialized CMDBuild class result.` });
      continue;
    }
    const expectedClass = String(mapping && mapping.primary && mapping.primary.className || '').trim();
    if (expectedClass && expectedClass !== String(stage.className || '').trim()) {
      errors.push({ path: stagePath, message: `Object Flow result ${stage.label || stage.id} returns ${stage.className}, but D2 role ${role.label || role.key} is configured for ${expectedClass}.` });
    }
    const available = new Set((stage.columns || []).map(String));
    for (const field of uniqueStrings([mapping.primary && mapping.primary.idAttribute]
      .concat(mapping.primary && mapping.primary.structuredFields || [])
      .concat(diagramImportPrimaryTemplateFieldNames(mapping.primary && mapping.primary.labelTemplate || '')))
      .map((field) => String(field || '').replace(/^primary\./, '')).filter(Boolean)) {
      if (!['_id', 'Class'].includes(field) && !available.has(field)) {
        errors.push({ path: `$.structureTree.items[${index}].mapping.primary`, message: `Field ${field} is not materialized by Object Flow result ${stage.label || stage.id}.` });
      }
    }
    if (materializationKind === 'stage' && ancestor && ancestor.stageId) {
      if (String(ancestor.stageId) === stageId) {
        errors.push({ path: `$.structureTree.items[${index}].mapping.materialization.kind`, message: 'Use parentCard instead of selecting the same Object Flow result as the materialized parent.' });
      } else if (
        !diagramImportStageDirectlyDependsOn(stage, stages.get(String(ancestor.stageId || ''))) &&
        !hierarchyConditions.rules.some((condition) => condition && condition.right && condition.right.kind === 'stage' && String(condition.right.stageId || '') === String(ancestor.stageId)) &&
        !conditions.rules.some((condition) => condition && condition.right && condition.right.kind === 'stage' && String(condition.right.stageId || '') === String(ancestor.stageId))
      ) {
        errors.push({ path: `$.structureTree.items[${index}].mapping.hierarchyConditions`, message: `A nested Object Flow result must explicitly match the parent result ${String(ancestor.stageId)} before it can be placed in this container.` });
      }
    }
    for (const [conditionIndex, condition] of conditions.rules.entries()) {
      const conditionPath = `$.structureTree.items[${index}].mapping.conditions.rules[${conditionIndex}]`;
      if (!DIAGRAM_IMPORT_CONDITION_OPERATORS.has(condition.operator)) {
        errors.push({ path: `${conditionPath}.operator`, message: 'D2 placement filter uses an unsupported matching operator.' });
      }
      if (!condition.left.column) {
        errors.push({ path: `${conditionPath}.left.column`, message: 'D2 placement filter requires a source field.' });
      }
      if (condition.left.regex) errors.push(...validateRegexPattern(condition.left.regex, '', `${conditionPath}.left.regex`, false));
      if (condition.right.regex) errors.push(...validateRegexPattern(condition.right.regex, '', `${conditionPath}.right.regex`, false));
      if (condition.right.kind === 'param') {
        if (!condition.right.name || !currentSpec || !currentSpec.params || !Object.prototype.hasOwnProperty.call(currentSpec.params, condition.right.name)) {
          errors.push({ path: `${conditionPath}.right.name`, message: `Report parameter ${condition.right.name || '(empty)'} is not available for this D2 condition.` });
        }
      } else if (condition.right.kind === 'stage') {
        const comparisonStage = stages.get(String(condition.right.stageId || ''));
        if (!comparisonStage) {
          errors.push({ path: `${conditionPath}.right.stageId`, message: `Comparison Object Flow result ${condition.right.stageId || '(empty)'} is not available.` });
        } else if (!condition.right.column) {
          errors.push({ path: `${conditionPath}.right.column`, message: 'D2 placement filter requires a comparison field.' });
        }
      }
    }
    for (const [conditionIndex, condition] of hierarchyConditions.rules.entries()) {
      const conditionPath = `$.structureTree.items[${index}].mapping.hierarchyConditions.rules[${conditionIndex}]`;
      if (!ancestor || !ancestor.stageId) {
        errors.push({ path: conditionPath, message: 'A hierarchy condition requires a materialized parent placement.' });
        continue;
      }
      if (!DIAGRAM_IMPORT_CONDITION_OPERATORS.has(condition.operator)) {
        errors.push({ path: `${conditionPath}.operator`, message: 'D2 hierarchy condition uses an unsupported matching operator.' });
      }
      if (!condition.left.column) {
        errors.push({ path: `${conditionPath}.left.column`, message: 'D2 hierarchy condition requires a child result field.' });
      }
      if (!condition.right || condition.right.kind !== 'stage' || String(condition.right.stageId || '') !== String(ancestor.stageId) || !condition.right.column) {
        errors.push({ path: `${conditionPath}.right`, message: 'D2 hierarchy condition must compare a child field with the nearest materialized parent result.' });
      }
      if (condition.left.regex) errors.push(...validateRegexPattern(condition.left.regex, '', `${conditionPath}.left.regex`, false));
      if (condition.right && condition.right.regex) errors.push(...validateRegexPattern(condition.right.regex, '', `${conditionPath}.right.regex`, false));
    }
  }
  for (const item of items) {
    const visited = new Set([item.id]);
    let parentId = String(item.parentId || '');
    while (parentId) {
      if (visited.has(parentId)) {
        errors.push({ path: '$.structureTree.items', message: `Structure tree contains a containment cycle at ${item.id}.` });
        break;
      }
      visited.add(parentId);
      parentId = String((itemById.get(parentId) || {}).parentId || '');
    }
  }
  errors.push(...diagramImportChildLabelTokenErrors(normalized, roles));
  return errors;
}

function rejectDiagramImportMigration(options, reason) {
  if (options && Array.isArray(options.diagnostics) && reason) options.diagnostics.push(reason);
  return null;
}

function diagramImportCanonicalMappingSignature(mapping) {
  const source = mapping && typeof mapping === 'object' && !Array.isArray(mapping) ? mapping : {};
  return stableJsonStringify({
    materialization: source.materialization && typeof source.materialization === 'object'
      ? { kind: String(source.materialization.kind || ''), stageId: String(source.materialization.stageId || '') }
      : {},
    ...(Object.prototype.hasOwnProperty.call(source, 'showEmpty') ? { showEmpty: source.showEmpty !== false } : {}),
    primary: source.primary && typeof source.primary === 'object'
      ? {
          className: String(source.primary.className || ''),
          idAttribute: String(source.primary.idAttribute || ''),
          labelTemplate: String(source.primary.labelTemplate || ''),
          structuredFields: uniqueStrings(source.primary.structuredFields || []),
          filters: cloneJsonValueServer(source.primary.filters || [], [])
        }
      : {},
    conditions: diagramImportPlacementFilters(source.conditions),
    hierarchyConditions: diagramImportPlacementFilters(source.hierarchyConditions),
    related: (Array.isArray(source.related) ? source.related : []).map((related) => ({
      id: String(related && related.id || ''),
      stageId: String(related && related.stageId || ''),
      legacyTraversal: Boolean(related && related.legacyTraversal),
      labelValueMode: normalizeDiagramImportRelatedLabelValueMode(related && related.labelValueMode),
      labelSeparator: String(related && related.labelSeparator || ', '),
      structuredFields: uniqueStrings(related && related.structuredFields || []),
      conditions: diagramImportPlacementFilters(related && related.conditions)
    }))
  });
}

function diagramImportLegacyV3StructureTree(spec, imported, structure, roles) {
  const contexts = diagramImportStructureTreeContextCatalog(structure, roles);
  const contextByElementKey = new Map();
  const roleById = new Map((Array.isArray(roles) ? roles : []).map((role) => [String(role && role.id || ''), role]));
  for (const context of contexts) {
    for (const elementKey of context.elementKeys || []) contextByElementKey.set(String(elementKey), context);
  }
  const candidatesByContext = new Map();
  for (const rawItem of Array.isArray(imported && imported.structureTree && imported.structureTree.items) ? imported.structureTree.items : []) {
    const elementKey = String(rawItem && rawItem.templateElementKey || '').trim();
    const context = contextByElementKey.get(elementKey);
    const role = context && roleById.get(String(context.roleId || ''));
    if (!context || !role) return { error: 'legacyContextMissing' };
    const existing = rawItem && rawItem.mapping && typeof rawItem.mapping === 'object' && !Array.isArray(rawItem.mapping)
      ? cloneJsonValueServer(rawItem.mapping, {})
      : {};
    const source = existing.source && typeof existing.source === 'object' && !Array.isArray(existing.source) ? existing.source : {};
    const stageId = String(source.stageId || '').trim();
    const visualKind = diagramImportRoleVisualKind(role);
    if (visualKind === 'node' && !stageId) return { error: 'legacyNodeSourceMissing' };
    if (String(existing.primary && existing.primary.labelTemplate || '').includes('child:')) return { error: 'legacyChildLabelToken' };
    delete existing.source;
    existing.materialization = stageId
      ? { kind: 'stage', stageId }
      : { kind: 'structural', stageId: '' };
    const canonicalItemId = diagramImportStableId('structure_item', context.key);
    const mapping = diagramImportStructureItemMapping(role, existing, canonicalItemId);
    const candidates = candidatesByContext.get(context.key) || [];
    candidates.push({ mapping, signature: diagramImportCanonicalMappingSignature(mapping) });
    candidatesByContext.set(context.key, candidates);
  }
  const items = [];
  for (const context of contexts) {
    const role = roleById.get(String(context.roleId || ''));
    const candidates = candidatesByContext.get(context.key) || [];
    if (!role || !candidates.length) return { error: 'legacyContextMappingMissing' };
    const signatures = uniqueStrings(candidates.map((candidate) => candidate.signature));
    if (signatures.length !== 1) return { error: 'legacyContextMappingConflict' };
    const itemId = diagramImportStableId('structure_item', context.key);
    items.push({
      id: itemId,
      roleId: String(role.id || ''),
      templateContextKey: context.key,
      templateElementKey: String((context.elementKeys || [])[0] || ''),
      templateElementKeys: uniqueStrings(context.elementKeys || []).sort(),
      parentId: context.parentContextKey ? diagramImportStableId('structure_item', context.parentContextKey) : '',
      mapping: candidates[0].mapping
    });
  }
  const tree = diagramImportStructureTree({ version: D2_IMPORT_STRUCTURE_TREE_VERSION, items }, structure, roles);
  const errors = diagramImportStructureTreeErrors(tree, roles, spec || {}, structure);
  return errors.length ? { error: 'legacyMaterializationSemanticsRequired' } : { tree };
}

function migrateDiagramImportToCurrentRevision(spec, value, options = {}) {
  const imported = value && typeof value === 'object' && !Array.isArray(value)
    ? cloneJsonValueServer(value, {})
    : null;
  if (!imported) return rejectDiagramImportMigration(options, 'mappingMissing');
  const revision = Number(imported.semanticModelRevision || 0);
  const treeVersion = Number(imported.structureTree && imported.structureTree.version || 0);
  const currentRevision = revision === D2_IMPORT_SEMANTIC_MODEL_REVISION && treeVersion === D2_IMPORT_STRUCTURE_TREE_VERSION;
  if (!currentRevision || !Array.isArray(imported.structureTree && imported.structureTree.items)) {
    return rejectDiagramImportMigration(options, 'materializationRevisionRequired');
  }
  if (diagramImportStoredMaterializationIssues(imported).length) {
    return rejectDiagramImportMigration(options, 'materializationContractRequired');
  }
  if (options.rebuildCurrent !== true) return imported;

  const source = String(templateAuthoringD2(spec || {}, { allowLegacy: false }).source || '');
  if (!source || source !== String(imported.source || '') || sha256Hex(source) !== String(imported.sourceHash || '')) {
    return rejectDiagramImportMigration(options, 'sourceMismatch');
  }
  if (!String(imported.structureHash || '').trim() || !String(imported.mappingContractHash || '').trim()) {
    return rejectDiagramImportMigration(options, 'identityMetadataMissing');
  }
  const ownerId = String(options.diagramId || '').trim();
  const importedDiagramId = String(imported.diagramId || '').trim();
  if (ownerId && importedDiagramId && ownerId !== importedDiagramId) {
    return rejectDiagramImportMigration(options, 'diagramOwnerMismatch');
  }
  const identity = options.identity && typeof options.identity === 'object' ? options.identity : null;
  const ir = identity && identity.ok && identity.ir && typeof identity.ir === 'object' ? identity.ir : null;
  if (!ir ||
    String(identity.sourceHash || '') !== String(imported.sourceHash || '') ||
    String(identity.structureHash || '') !== String(imported.structureHash || '') ||
    String(identity.mappingContractHash || '') !== String(imported.mappingContractHash || '')) {
    return rejectDiagramImportMigration(options, 'sourceIdentityMismatch');
  }
  const structure = ir.elements && typeof ir.elements === 'object' && !Array.isArray(ir.elements) ? ir.elements : null;
  const classes = Array.isArray(ir.classes) ? ir.classes : [];
  const template = ir.template && typeof ir.template === 'object' && !Array.isArray(ir.template) ? ir.template : {};
  if (!structure || !classes.length) return rejectDiagramImportMigration(options, 'canonicalStructureMissing');

  const roles = diagramImportWithRoleModelCandidates(
    diagramImportClassRoleDefinitions(ir).map((role) => ({
      ...diagramImportApplyRoleModel(role),
      semanticModelRevision: D2_IMPORT_SEMANTIC_MODEL_REVISION
    })),
    structure
  );
  const roleById = new Map(roles.map((role) => [String(role && role.id || ''), role]));
  const migratedItems = [];
  for (const item of imported.structureTree.items) {
    const role = roleById.get(String(item && item.roleId || ''));
    if (!role) return rejectDiagramImportMigration(options, 'roleSetMismatch');
    const existing = item && item.mapping && typeof item.mapping === 'object' && !Array.isArray(item.mapping)
      ? cloneJsonValueServer(item.mapping, {})
      : {};
    const explicit = existing.materialization && typeof existing.materialization === 'object' && !Array.isArray(existing.materialization)
      ? existing.materialization
      : {};
    const explicitKind = String(explicit.kind || '').trim();
    if (!DIAGRAM_IMPORT_MATERIALIZATION_KINDS.has(explicitKind) ||
      (explicitKind === 'stage' && !String(explicit.stageId || '').trim()) ||
      Object.prototype.hasOwnProperty.call(existing, 'source')) {
      return rejectDiagramImportMigration(options, 'materializationContractRequired');
    }
    existing.materialization = {
      kind: explicitKind,
      stageId: explicitKind === 'stage' ? String(explicit.stageId || '').trim() : ''
    };
    const mapping = diagramImportStructureItemMapping(role, existing, String(item && item.id || ''));
    migratedItems.push({ ...item, mapping });
  }
  const structureTree = diagramImportStructureTree({
    version: D2_IMPORT_STRUCTURE_TREE_VERSION,
    items: migratedItems
  }, structure, roles);
  if (diagramImportStructureTreeErrors(structureTree, roles, spec || {}, structure).length) {
    return rejectDiagramImportMigration(options, 'materializationSemanticsRequired');
  }

  return {
    ...imported,
    version: 3,
    semanticModelRevision: D2_IMPORT_SEMANTIC_MODEL_REVISION,
    diagramId: ownerId || importedDiagramId,
    sourceHash: String(identity.sourceHash || ''),
    structureHash: String(identity.structureHash || ''),
    mappingContractHash: String(identity.mappingContractHash || ''),
    parser: String(ir.source && ir.source.parser || imported.parser || ''),
    source,
    template: cloneJsonValueServer(template, {}),
    structure: cloneJsonValueServer(structure, {}),
    classes: cloneJsonValueServer(classes, []),
    roles,
    relationRules: diagramImportTopologyRules(roles, structure, imported.relationRules || [], classes),
    structureTree,
    templateGrammar: diagramImportTemplateGrammar(roles, structure, classes)
  };
}

function diagramImportMigrationProposal(spec, imported) {
  const source = String(templateAuthoringD2(spec || {}, { allowLegacy: false }).source || '');
  return {
    version: 3,
    semanticModelRevision: D2_IMPORT_SEMANTIC_MODEL_REVISION,
    proposalId: String(imported && imported.proposalId || diagramImportStableId('migration', String(imported && imported.diagramId || ''))),
    createdAt: Date.now(),
    deterministicSpecHash: diagramImportDeterministicSpecHash(spec || {}),
    source: {
      hash: String(imported && imported.sourceHash || ''),
      structureHash: String(imported && imported.structureHash || ''),
      mappingContractHash: String(imported && imported.mappingContractHash || ''),
      parser: String(imported && imported.parser || '')
    },
    sourceText: source,
    template: cloneJsonValueServer(imported && imported.template, {}),
    structure: cloneJsonValueServer(imported && imported.structure, {}),
    classes: cloneJsonValueServer(imported && imported.classes, []),
    roles: cloneJsonValueServer(imported && imported.roles, []),
    relationRules: cloneJsonValueServer(imported && imported.relationRules, []),
    structureTree: cloneJsonValueServer(imported && imported.structureTree, { version: D2_IMPORT_STRUCTURE_TREE_VERSION, items: [] }),
    templateGrammar: cloneJsonValueServer(imported && imported.templateGrammar, {}),
    diagramId: String(imported && imported.diagramId || ''),
    warnings: [],
    unresolved: []
  };
}

function diagramImportV3Unresolved(roles, relationRules = [], structureTree, currentSpec = {}, structure = null) {
  const unresolved = [];
  const normalizedTreeCandidate = diagramImportStructureTree(structureTree, structure, roles);
  const roleById = new Map((Array.isArray(roles) ? roles : []).map((role) => [String(role && role.id || ''), role]));
  const stagesById = new Map(assistantObjectFlowDiagramStages(currentSpec, objectFlowFromSpecServer(currentSpec))
    .map((stage) => [String(stage && stage.id || ''), stage]));
  const itemsById = new Map((normalizedTreeCandidate.items || []).map((item) => [String(item && item.id || ''), item]));
  const effectiveStageId = (item, visited = new Set()) => {
    const itemId = String(item && item.id || '');
    if (!item || visited.has(itemId)) return '';
    const role = roleById.get(String(item && item.roleId || '')) || {};
    const mapping = diagramImportStructureItemMapping(role, item.mapping || {}, itemId);
    if (String(mapping && mapping.materialization && mapping.materialization.kind || '') === 'stage') return String(mapping.materialization.stageId || '');
    if (String(mapping && mapping.materialization && mapping.materialization.kind || '') !== 'parentCard') return '';
    return effectiveStageId(itemsById.get(String(item.parentId || '')), new Set(visited).add(itemId));
  };
  const treeErrors = diagramImportStructureTreeErrors(structureTree, roles, currentSpec, structure);
  for (const error of treeErrors) {
    const itemIndex = Number(String(error.path || '').match(/^\$\.structureTree\.items\[(\d+)\]/)?.[1]);
    const roleIndex = Number(String(error.path || '').match(/^\$\.roles\[(\d+)\]/)?.[1]);
    const item = Number.isInteger(itemIndex) ? normalizedTreeCandidate.items[itemIndex] : null;
    const role = item
      ? roleById.get(String(item.roleId || ''))
      : Number.isInteger(roleIndex) ? (Array.isArray(roles) ? roles[roleIndex] : null) : null;
    unresolved.push({
      id: String(error.path || 'structureTree'),
      displayName: role && (role.label || role.key || role.id) || '',
      family: 'structureTree',
      fields: [String(error.message || 'invalid')]
    });
  }
  const normalizedTree = treeErrors.length
    ? { version: D2_IMPORT_STRUCTURE_TREE_VERSION, items: [] }
    : normalizedTreeCandidate;
  for (const item of normalizedTreeCandidate.items) {
    const role = roleById.get(String(item && item.roleId || '')) || {};
    const mapping = diagramImportStructureItemMapping(role, item && item.mapping || {}, item && item.id || '');
    const primaryStageId = effectiveStageId(item);
    for (const related of Array.isArray(mapping.related) ? mapping.related : []) {
      const stage = stagesById.get(String(related && related.stageId || ''));
      const conditions = diagramImportPlacementFilters(related && related.conditions);
      const validStageCorrelation = conditions.rules.length && conditions.rules.every((rule) =>
        String(rule && rule.left && rule.left.column || '') &&
        String(rule && rule.right && rule.right.kind || '') === 'stage' &&
        String(rule && rule.right && rule.right.stageId || '') === primaryStageId &&
        String(rule && rule.right && rule.right.column || ''));
      if (!stage || !validStageCorrelation) {
        unresolved.push({
          id: related.id,
          structureItemId: String(item && item.id || ''),
          displayName: String(role.label || role.key || item && item.id || ''),
          family: 'related',
          fields: ['stageId', 'explicit correlation']
        });
      }
    }
  }
  for (const rule of Array.isArray(relationRules) ? relationRules : []) {
    if (!rule || !rule.parentRoleId || !rule.childRoleId || !['relationCard', 'networkEndpoints', 'deterministicEndpoints'].includes(String(rule.mode || ''))) {
      unresolved.push({ id: rule && rule.id || 'relation', family: 'relationRules', fields: ['parentRoleId', 'childRoleId', 'Object Flow result'] });
    }
  }
  unresolved.push(...diagramImportTopologyUnresolved(roles, relationRules));
  return unresolved;
}

function diagramImportEdgeClassContract(edge, classes = []) {
  const classKeys = uniqueStrings(Array.isArray(edge && edge.classKeys) ? edge.classKeys : []).sort();
  const classByKey = new Map((Array.isArray(classes) ? classes : []).map((item) => [String(item && item.key || ''), item]));
  const notes = uniqueStrings(classKeys.map((key) => String(classByKey.get(key) && classByKey.get(key).notes || '').trim()).filter(Boolean));
  const directionPolicies = uniqueStrings(classKeys.map((key) => normalizeDiagramDirectionPolicy(classByKey.get(key) && classByKey.get(key).directionPolicy)).filter(Boolean));
  const edgeKey = String(edge && edge.key || '').trim();
  return {
    key: classKeys.length ? classKeys.join('+') : `edge:${edgeKey}`,
    classKeys,
    notes: notes.join('\n\n'),
    directionPolicy: directionPolicies.length === 1 ? directionPolicies[0] : '',
    synthetic: classKeys.length === 0
  };
}

function diagramImportTopologyRules(roles, structure, explicitRules = [], classes = []) {
  const roleByElementKey = new Map();
  for (const role of Array.isArray(roles) ? roles : []) {
    for (const key of Array.isArray(role && role.elementKeys) ? role.elementKeys : []) {
      const text = String(key || '').trim();
      if (text && !roleByElementKey.has(text)) roleByElementKey.set(text, role);
    }
  }
  const previousRules = Array.isArray(explicitRules) ? cloneJsonValueServer(explicitRules, []) : [];
  const contracts = new Map();
  for (const edge of Array.isArray(structure && structure.edges) ? structure.edges : []) {
    const d2ElementKey = String(edge && edge.key || '').trim();
    const sourceRole = roleByElementKey.get(String(edge && edge.sourceKey || '').trim());
    const targetRole = roleByElementKey.get(String(edge && edge.targetKey || '').trim());
    if (!d2ElementKey || !sourceRole || !targetRole) continue;
    const edgeClass = diagramImportEdgeClassContract(edge, classes);
    const direction = String(edge && edge.direction || '->').trim() || '->';
    const contractId = `${edgeClass.key}\u0000${sourceRole.id}\u0000${targetRole.id}\u0000${direction}`;
    const existing = contracts.get(contractId);
    if (existing) {
      existing.d2ElementKeys.push(d2ElementKey);
      existing.d2ExampleLabels.push(String(edge.label || `${edge.sourceKey} -> ${edge.targetKey}`).trim());
      continue;
    }
    contracts.set(contractId, {
      contractId,
      d2ClassKey: edgeClass.key,
      d2ClassKeys: edgeClass.classKeys,
      d2Notes: edgeClass.notes,
      directionPolicy: edgeClass.directionPolicy,
      d2ElementKeys: [d2ElementKey],
      d2ExampleLabels: [String(edge.label || `${edge.sourceKey} -> ${edge.targetKey}`).trim()],
      direction,
      parentRoleId: sourceRole.id,
      childRoleId: targetRole.id
    });
  }
  const rules = [];
  const consumed = new Set();
  for (const contract of contracts.values()) {
    const previousIndex = previousRules.findIndex((rule, index) => !consumed.has(index) &&
      String(rule && rule.d2ClassKey || '') === contract.d2ClassKey &&
      String(rule && rule.parentRoleId || '') === String(contract.parentRoleId) &&
      String(rule && rule.childRoleId || '') === String(contract.childRoleId));
    const previous = previousIndex >= 0 ? previousRules[previousIndex] : {};
    if (previousIndex >= 0) consumed.add(previousIndex);
    rules.push({
      ...previous,
      id: String(previous && previous.id || diagramImportStableId('topology_rule', contract.contractId)),
      kind: 'connection',
      mode: ['relationCard', 'networkEndpoints', 'deterministicEndpoints'].includes(String(previous && previous.mode || ''))
        ? String(previous.mode)
        : 'deterministicEndpoints',
      d2ClassKey: contract.d2ClassKey,
      d2ClassKeys: contract.d2ClassKeys,
      d2Notes: contract.d2Notes,
      d2ElementKey: contract.d2ElementKeys[0],
      d2ElementKeys: contract.d2ElementKeys,
      d2ExampleLabels: contract.d2ExampleLabels,
      d2Label: contract.d2ClassKeys.length ? contract.d2ClassKey : contract.d2ExampleLabels[0],
      parentRoleId: contract.parentRoleId,
      childRoleId: contract.childRoleId,
      direction: contract.direction,
      directionPolicy: normalizeDiagramDirectionPolicy(contract.directionPolicy) || normalizeDiagramDirectionPolicy(previous && previous.directionPolicy),
      directionPolicySuggestion: normalizeDiagramDirectionPolicy(contract.directionPolicy) || diagramImportDirectionPolicySuggestion({
        direction: contract.direction,
        d2ClassKey: contract.d2ClassKey,
        d2Notes: contract.d2Notes,
        d2ExampleLabels: contract.d2ExampleLabels
      }),
      path: [],
      automatic: true
    });
  }
  previousRules.forEach((rule, index) => {
    if (!consumed.has(index) && !String(rule && rule.d2ElementKey || '') && !String(rule && rule.d2ClassKey || '')) rules.push(rule);
  });
  return rules;
}

function diagramImportTopologyUnresolved(roles, relationRules = []) {
  const roleById = new Map((Array.isArray(roles) ? roles : []).map((role) => [String(role && role.id || ''), role]));
  const result = [];
  for (const rule of Array.isArray(relationRules) ? relationRules : []) {
    if (!rule || (!rule.d2ElementKey && !rule.d2ClassKey)) continue;
    const sourceRole = roleById.get(String(rule.parentRoleId || ''));
    const targetRole = roleById.get(String(rule.childRoleId || ''));
    if (!sourceRole || !targetRole) continue;
    const directionReady = Boolean(normalizeDiagramDirectionPolicy(rule && rule.directionPolicy));
    // Direction is part of the runtime edge contract. A connection can still
    // be materialized from a dedicated result when one D2 endpoint is a
    // structural/static role, so do not skip this validation by role semantic.
    if (!directionReady) {
      const label = String(rule.d2Label || rule.d2ClassKey || rule.d2ElementKey || '').trim();
      result.push({
        id: `topology:connection:${String(rule.d2ClassKey || rule.d2ElementKey || rule.id || '')}`,
        family: 'topology',
        displayName: label,
        fields: ['directionPolicy'],
        directionPolicySuggestion: normalizeDiagramDirectionPolicy(rule.directionPolicySuggestion),
        sourceRoleId: sourceRole.id,
        targetRoleId: targetRole.id,
        d2ClassKey: String(rule.d2ClassKey || ''),
        d2ClassKeys: Array.isArray(rule.d2ClassKeys) ? rule.d2ClassKeys.map(String).filter(Boolean) : [],
        d2ElementKeys: Array.isArray(rule.d2ElementKeys) ? rule.d2ElementKeys.map(String) : [String(rule.d2ElementKey || '')].filter(Boolean)
      });
      continue;
    }
    if (!diagramImportRoleNeedsStage(sourceRole) || !diagramImportRoleNeedsStage(targetRole)) continue;
    const cardReady = directionReady && rule && ['relationCard', 'networkEndpoints', 'deterministicEndpoints'].includes(String(rule.mode || '')) && String(rule.sourceStageId || '').trim() && String(rule.sourceField || '').trim() && String(rule.targetField || '').trim();
    if (cardReady) continue;
    const label = String(rule.d2Label || rule.d2ClassKey || rule.d2ElementKey || '').trim();
    result.push({
      id: `topology:connection:${String(rule.d2ClassKey || rule.d2ElementKey || rule.id || '')}`,
      family: 'topology',
      displayName: label,
      fields: directionReady ? ['connection relation rule'] : ['directionPolicy'],
      directionPolicySuggestion: normalizeDiagramDirectionPolicy(rule.directionPolicySuggestion),
      sourceRoleId: sourceRole.id,
      targetRoleId: targetRole.id,
      d2ClassKey: String(rule.d2ClassKey || ''),
      d2ClassKeys: Array.isArray(rule.d2ClassKeys) ? rule.d2ClassKeys.map(String).filter(Boolean) : [],
      d2ElementKeys: Array.isArray(rule.d2ElementKeys) ? rule.d2ElementKeys.map(String) : [String(rule.d2ElementKey || '')].filter(Boolean)
    });
  }
  return result;
}

function diagramImportUnresolvedDiagnostics(proposal, currentSpec = null) {
  const roles = Array.isArray(proposal && proposal.roles) ? proposal.roles : [];
  const roleById = new Map(roles.map((role) => [String(role && role.id || ''), role]));
  const unresolved = Array.isArray(proposal && proposal.unresolved)
    ? proposal.unresolved
    : diagramImportV3Unresolved(roles, proposal && proposal.relationRules, proposal && proposal.structureTree, currentSpec || {}, proposal && proposal.structure);
  return unresolved.map((item) => {
    const role = roleById.get(String(item && item.id || ''));
    const relatedOwner = !role && item && item.family === 'related'
      ? roles.find((candidate) => (candidate && candidate.mapping && Array.isArray(candidate.mapping.related) ? candidate.mapping.related : []).some((related) => String(related && related.id || '') === String(item.id || '')))
      : null;
    const fallbackName = String(item && item.displayName || '') || (item && item.family === 'relationRules'
      ? 'D2 relation'
      : item && item.family === 'structureTree'
        ? 'D2 structure'
        : item && item.family === 'topology'
          ? 'D2 topology relation'
          : item && item.id || '');
    const diagnostic = {
      roleId: String(role && role.id || relatedOwner && relatedOwner.id || ''),
      displayName: String(role && (role.label || role.key) || relatedOwner && (relatedOwner.label || relatedOwner.key) || fallbackName),
      family: String(item && item.family || ''),
      fields: Array.isArray(item && item.fields) ? item.fields : []
    };
    const directionPolicySuggestion = normalizeDiagramDirectionPolicy(item && item.directionPolicySuggestion);
    if (directionPolicySuggestion) diagnostic.directionPolicySuggestion = directionPolicySuggestion;
    const d2ElementKeys = Array.isArray(item && item.d2ElementKeys) ? item.d2ElementKeys.map(String).filter(Boolean) : [];
    if (d2ElementKeys.length) diagnostic.d2ElementKeys = d2ElementKeys;
    const d2ClassKeys = Array.isArray(item && item.d2ClassKeys) ? item.d2ClassKeys.map(String).filter(Boolean) : [];
    if (d2ClassKeys.length) diagnostic.d2ClassKeys = d2ClassKeys;
    return diagnostic;
  });
}

function diagramImportAppliedMappingForReanalysis(currentDiagram, ir) {
  const imported = currentDiagram && currentDiagram.authoring && currentDiagram.authoring.d2Import;
  if (!imported || typeof imported !== 'object' || Array.isArray(imported)) {
    return { value: {}, mode: 'none', warning: '' };
  }
  if (Number(imported.version || 0) !== 3) {
    return {
      value: {},
      mode: 'none',
      warning: 'Existing D2 authoring mapping uses an unsupported importer version and was not restored. Analyze and map the D2 source again.'
    };
  }

  const sourceHash = String(ir && ir.source && ir.source.hash || '').trim();
  const structureHash = String(ir && ir.source && ir.source.structureHash || '').trim();
  const mappingContractHash = String(ir && ir.source && ir.source.mappingContractHash || '').trim();
  const storedSourceHash = String(imported.sourceHash || '').trim();
  const storedStructureHash = String(imported.structureHash || '').trim();
  const storedMappingContractHash = String(imported.mappingContractHash || '').trim();
  const sourceMatches = Boolean(sourceHash && storedSourceHash && sourceHash === storedSourceHash);
  const structureMatches = Boolean(structureHash && (!storedStructureHash || storedStructureHash === structureHash));
  const mappingContractMatches = Boolean(mappingContractHash && storedMappingContractHash && mappingContractHash === storedMappingContractHash);
  const revision = Number(imported.semanticModelRevision || 0);
  const supportedRevision = revision === D2_IMPORT_SEMANTIC_MODEL_REVISION;
  if (!supportedRevision) {
    return {
      value: {},
      mode: 'none',
      warning: 'Existing D2 authoring mapping uses an unsupported semantic revision and was not restored. Analyze and map the D2 source again.'
    };
  }
  if (!imported.structureTree || Number(imported.structureTree.version || 0) !== D2_IMPORT_STRUCTURE_TREE_VERSION || !Array.isArray(imported.structureTree.items)) {
    return {
      value: {},
      mode: 'none',
      warning: 'Existing D2 authoring mapping uses the retired placement model and was not restored. Analyze and map the D2 source again.'
    };
  }
  if (diagramImportStoredMaterializationIssues(imported).length) {
    return {
      value: {},
      mode: 'none',
      warning: 'Existing D2 authoring mapping has placements without an explicit materialization and was not restored. Choose a source for every dynamic placement in Diagram Editor or apply a current Assistant proposal.'
    };
  }
  if (sourceMatches && structureMatches && mappingContractMatches && revision === D2_IMPORT_SEMANTIC_MODEL_REVISION) {
    return { value: imported, mode: 'full', warning: '' };
  }
  return {
    value: {},
    mode: 'none',
    warning: !structureMatches
      ? 'D2 source structure changed. The saved structure tree was not reused; analyze and map the current source again.'
      : !mappingContractMatches
        ? 'D2 mapping contract changed. The saved mapping was not reused; analyze and map the current source again.'
        : 'D2 source changed. The saved structure tree was not reused; analyze and map the current source again.'
  };
}

function createDiagramImportProposal(currentSpec, ir, options = {}) {
  if (!ir || ir.version < 3) {
    const error = new Error('D2 importer result version is no longer supported. Rebuild the class-aware importer and analyze again.');
    error.code = 'diagram_import_ir_version';
    error.statusCode = 409;
    throw error;
  }
  const sourceSpec = cloneJsonValueServer(currentSpec, {});
  const currentDiagrams = Array.isArray(sourceSpec.result && sourceSpec.result.diagrams) ? sourceSpec.result.diagrams : [];
  const currentDiagram = currentDiagrams.find((item) => item && typeof item === 'object' && !Array.isArray(item) && item.authoring && item.authoring.d2Import) ||
    currentDiagrams.find((item) => item && typeof item === 'object' && !Array.isArray(item)) || {};
  const previousMapping = diagramImportAppliedMappingForReanalysis(currentDiagram, ir);
  const previousImport = previousMapping.value;
  const rawRoleDefinitions = diagramImportClassRoleDefinitions(ir);
  const previousRoles = new Map((Array.isArray(previousImport.roles) ? previousImport.roles : []).map((role) => [String(role.id || ''), role]));
  const rawRoles = rawRoleDefinitions.map((role) => {
    const previousRole = previousRoles.get(role.id) || {};
    const automaticExemplar = diagramImportRoleExemplar(role, ir.elements);
    const model = diagramImportPreviousRoleModel(role, previousRole);
    return {
      ...model,
      semanticModelRevision: D2_IMPORT_SEMANTIC_MODEL_REVISION,
      exemplarKey: '',
      exemplarAutomatic: false
    };
  });
  const roles = diagramImportWithRoleModelCandidates(rawRoles, ir.elements);
  const relationRules = diagramImportTopologyRules(roles, ir.elements, Array.isArray(previousImport.relationRules) ? cloneJsonValueServer(previousImport.relationRules, []) : [], ir.classes);
  const preserveTree = String(previousImport.sourceHash || '') === String(ir.source && ir.source.hash || '');
  const structureTree = diagramImportStructureTree(
    preserveTree ? previousImport.structureTree : null,
    ir.elements,
    roles
  );
  const templateGrammar = diagramImportTemplateGrammar(roles, ir.elements, ir.classes);
  const catalog = options.catalog && typeof options.catalog === 'object' ? options.catalog : null;
  const warnings = [];
  if (previousMapping.warning) warnings.push(previousMapping.warning);
  return {
    version: 3,
    semanticModelRevision: D2_IMPORT_SEMANTIC_MODEL_REVISION,
    proposalId: crypto.randomUUID(),
    createdAt: Date.now(),
    templateCode: String(options.templateCode || '').trim(),
    baseSpecHash: String(options.baseSpecHash || '').trim(),
    deterministicSpecHash: diagramImportDeterministicSpecHash(sourceSpec),
    source: ir.source,
    sourceText: String(options.sourceText || ''),
    template: ir.template,
    structure: cloneJsonValueServer(ir.elements, {}),
    classes: cloneJsonValueServer(ir.classes, []),
    catalogHash: catalog ? hashJson({ classes: catalog.classes, domains: catalog.domains }) : '',
    roles,
    relationRules,
    structureTree,
    templateGrammar,
    diagramId: String(currentDiagram.id || diagramImportStableId('diagram', currentDiagram.name || options.templateCode || 'topology')).trim(),
    unresolved: diagramImportV3Unresolved(roles, relationRules, structureTree, sourceSpec, ir.elements),
    warnings
  };
}

function diagramImportProposalSignaturePayload(proposal) {
  const payload = cloneJsonValueServer(proposal, {});
  delete payload.signature;
  return payload;
}

function signDiagramImportProposal(proposal, authToken) {
  const next = cloneJsonValueServer(proposal, {});
  next.signature = crypto
    .createHmac('sha256', CSRF_SECRET)
    .update(String(authToken || ''))
    .update('\n')
    .update(stableJsonStringify(diagramImportProposalSignaturePayload(next)))
    .digest('hex');
  return next;
}

function diagramImportMappingValidationPayload(imported) {
  const payload = cloneJsonValueServer(imported, {});
  delete payload.mappingValidation;
  return payload;
}

function signDiagramImportMappingValidation(imported) {
  return crypto
    .createHmac('sha256', CSRF_SECRET)
    .update(stableJsonStringify(diagramImportMappingValidationPayload(imported)))
    .digest('hex');
}

function diagramImportMappingValidationIsCurrent(imported) {
  const validation = imported && imported.mappingValidation && typeof imported.mappingValidation === 'object' && !Array.isArray(imported.mappingValidation)
    ? imported.mappingValidation
    : {};
  if (validation.status !== 'valid' || !String(validation.signature || '').trim()) return false;
  if (diagramImportStoredMaterializationIssues(imported).length) return false;
  return timingSafeEqualString(validation.signature, signDiagramImportMappingValidation(imported));
}

function diagramImportMappingInputStageIds(imported) {
  const stageIds = [];
  const push = (value) => {
    const stageId = String(value || '').trim();
    if (stageId) stageIds.push(stageId);
  };
  const structureTree = imported && imported.structureTree && typeof imported.structureTree === 'object' && !Array.isArray(imported.structureTree)
    ? imported.structureTree
    : {};
  for (const item of Array.isArray(structureTree.items) ? structureTree.items : []) {
    const mapping = item && item.mapping && typeof item.mapping === 'object' && !Array.isArray(item.mapping) ? item.mapping : {};
    const materialization = mapping.materialization && typeof mapping.materialization === 'object' && !Array.isArray(mapping.materialization)
      ? mapping.materialization
      : {};
    if (String(materialization.kind || '') === 'stage') push(materialization.stageId);
    const conditions = mapping.conditions && typeof mapping.conditions === 'object' && !Array.isArray(mapping.conditions)
      ? mapping.conditions
      : {};
    for (const rule of Array.isArray(conditions.rules) ? conditions.rules : []) {
      const right = rule && rule.right && typeof rule.right === 'object' && !Array.isArray(rule.right) ? rule.right : {};
      if (String(right.kind || '').trim() === 'stage') push(right.stageId);
    }
  }
  for (const rule of Array.isArray(imported && imported.relationRules) ? imported.relationRules : []) {
    push(rule && rule.sourceStageId);
  }
  return uniqueStrings(stageIds).sort();
}

function diagramImportMappingInputStageContracts(spec, imported) {
  let stages = [];
  try {
    stages = assistantObjectFlowDiagramStages(spec || {}, objectFlowFromSpecServer(spec || {}));
  } catch {
    stages = [];
  }
  const byId = new Map(stages.map((stage) => [String(stage && stage.id || ''), stage]));
  return diagramImportMappingInputStageIds(imported).map((stageId) => {
    const stage = byId.get(stageId);
    if (!stage) return { id: stageId, missing: true };
    return {
      id: stageId,
      alias: String(stage.alias || ''),
      kind: String(stage.kind || ''),
      className: String(stage.className || ''),
      columns: uniqueStrings(Array.isArray(stage.columns) ? stage.columns.map(String) : []).sort()
    };
  });
}

function diagramImportMappingInputRevision(spec, imported) {
  const authoring = templateAuthoring(spec || {}, { allowLegacy: true }) || { d2: { source: '' } };
  const d2 = authoring.d2 && typeof authoring.d2 === 'object' && !Array.isArray(authoring.d2)
    ? authoring.d2
    : {};
  const source = String(d2.source || '');
  return {
    version: D2_IMPORT_MAPPING_INPUT_REVISION,
    sourceHash: source ? sha256Hex(source) : '',
    stageContracts: diagramImportMappingInputStageContracts(spec || {}, imported)
  };
}

function diagramImportMappingInputRevisionStatus(spec, imported) {
  const stored = imported && imported.mappingInputRevision && typeof imported.mappingInputRevision === 'object' && !Array.isArray(imported.mappingInputRevision)
    ? imported.mappingInputRevision
    : null;
  const storedVersion = Number(stored && stored.version || 0);
  if (!stored || ![1, D2_IMPORT_MAPPING_INPUT_REVISION].includes(storedVersion)) {
    return { current: false, missing: true, reasons: ['inputRevision'] };
  }
  const current = diagramImportMappingInputRevision(spec, imported);
  const reasons = [];
  if (String(stored.sourceHash || '') !== current.sourceHash) reasons.push('source');
  if (stableJsonStringify(Array.isArray(stored.stageContracts) ? stored.stageContracts : []) !== stableJsonStringify(current.stageContracts)) reasons.push('stages');
  return { current: reasons.length === 0, missing: false, reasons, value: current, migrationRequired: storedVersion !== D2_IMPORT_MAPPING_INPUT_REVISION };
}

function withDiagramImportMappingInputRevision(spec, imported) {
  return {
    ...imported,
    mappingInputRevision: diagramImportMappingInputRevision(spec, imported)
  };
}

function diagramImportRecoveryPayloadHash(imported) {
  const payload = cloneJsonValueServer(imported, {});
  delete payload.mappingValidation;
  delete payload.mappingInputRevision;
  return hashJson(payload);
}

function diagramImportLegacyHistoricalAttestation(imported) {
  const validation = imported && imported.mappingValidation && typeof imported.mappingValidation === 'object' && !Array.isArray(imported.mappingValidation)
    ? imported.mappingValidation
    : {};
  return Number(imported && imported.semanticModelRevision || 0) === 8 &&
    Number(imported && imported.structureTree && imported.structureTree.version || 0) === 3 &&
    !imported.mappingInputRevision &&
    validation.status === 'valid' &&
    /^[a-f0-9]{64}$/i.test(String(validation.signature || ''));
}

function diagramImportForSpec(spec, diagramId = '') {
  const diagrams = spec && spec.result && Array.isArray(spec.result.diagrams) ? spec.result.diagrams : [];
  const diagram = diagrams.find((item) => item && item.authoring && item.authoring.d2Import &&
    (!diagramId || String(item.id || '') === diagramId)) ||
    diagrams.find((item) => item && item.authoring && item.authoring.d2Import) || null;
  const imported = diagram && diagram.authoring && diagram.authoring.d2Import;
  return imported && typeof imported === 'object' && !Array.isArray(imported) ? { diagram, imported } : null;
}

function diagramImportRolesForStoredStructure(imported) {
  const source = imported && typeof imported === 'object' && !Array.isArray(imported) ? imported : {};
  const structure = source.structure && typeof source.structure === 'object' && !Array.isArray(source.structure)
    ? source.structure
    : {};
  const storedRoles = Array.isArray(source.roles) ? source.roles : [];
  const storedById = new Map(storedRoles
    .map((role) => [String(role && role.id || ''), role])
    .filter(([id]) => id));
  const canonicalRoles = diagramImportClassRoleDefinitions({
    elements: structure,
    classes: Array.isArray(source.classes) ? source.classes : []
  });
  if (!canonicalRoles.length) return storedRoles.map((role) => cloneJsonValueServer(role, {}));
  const restored = canonicalRoles.map((role) => {
    const stored = storedById.get(String(role.id || '')) || {};
    const modeled = { ...role, ...stored };
    return diagramImportApplyRoleModel({
      ...role,
      label: String(stored.label || role.label || role.key || ''),
      notes: String(stored.notes !== undefined ? stored.notes : role.notes || ''),
      visualKind: diagramImportRoleVisualKind(modeled),
      labelTemplate: String(stored.labelTemplate || role.labelTemplate || '')
    });
  });
  return diagramImportWithRoleModelCandidates(restored, structure);
}

function diagramImportRecoveryCandidate(spec, imported, recoveryVersions = []) {
  const currentAuthoring = templateAuthoring(spec, { allowLegacy: true });
  const currentSource = String(currentAuthoring && currentAuthoring.d2 && currentAuthoring.d2.source || '');
  if (!currentSource || String(imported && imported.sourceHash || '') !== sha256Hex(currentSource)) return null;
  const currentPayloadHash = diagramImportRecoveryPayloadHash(imported);
  const currentInput = diagramImportMappingInputRevision(spec, imported);
  for (const version of Array.isArray(recoveryVersions) ? recoveryVersions : []) {
    const versionSpec = safeJsonValue(version && (version.spec !== undefined ? version.spec : version.SpecJson), null);
    if (!versionSpec || typeof versionSpec !== 'object' || Array.isArray(versionSpec)) continue;
    const candidate = diagramImportForSpec(versionSpec, String(imported && imported.diagramId || ''));
    if (!candidate) continue;
    const verified = diagramImportMappingValidationIsCurrent(candidate.imported);
    // CSRF signing secrets can legitimately rotate between the historical
    // version and this normal Save. A legacy signature is never accepted at
    // runtime: it is only an attestation source for the narrow 8/3 -> 9/4
    // write-time migration below, which re-parses, recompiles, validates, and
    // signs the result with the current secret.
    const legacyHistoricalAttestation = !verified && diagramImportLegacyHistoricalAttestation(candidate.imported);
    if (!verified && !legacyHistoricalAttestation) continue;
    const candidateAuthoring = templateAuthoring(versionSpec, { allowLegacy: true });
    const candidateSource = String(candidateAuthoring && candidateAuthoring.d2 && candidateAuthoring.d2.source || '');
    if (candidateSource !== currentSource || String(candidate.imported.sourceHash || '') !== sha256Hex(candidateSource)) continue;
    if (diagramImportRecoveryPayloadHash(candidate.imported) !== currentPayloadHash) continue;
    const candidateInput = diagramImportMappingInputRevision(versionSpec, candidate.imported);
    if (stableJsonStringify(candidateInput) !== stableJsonStringify(currentInput)) continue;
    return {
      imported: cloneJsonValueServer(candidate.imported, {}),
      version: Number(version && version.version || version && version.Version || 0) || null,
      verification: verified ? 'currentSignature' : 'legacyHistoricalAttestation'
    };
  }
  return null;
}

function assertDiagramImportProposal(proposal, authToken) {
  if (!proposal || typeof proposal !== 'object' || Array.isArray(proposal)) {
    const error = new Error('Diagram import proposal is required.');
    error.code = 'diagram_import_proposal_required';
    error.statusCode = 422;
    throw error;
  }
  if (proposal.version !== 3) {
    const error = new Error('D2 import proposal version is no longer supported. Analyze the D2 source again.');
    error.code = 'diagram_import_proposal_version';
    error.statusCode = 409;
    throw error;
  }
  if (!isSpecHash(String(proposal.deterministicSpecHash || ''))) {
    const error = new Error('D2 import proposal has no deterministic template revision. Analyze the D2 source again.');
    error.code = 'diagram_import_deterministic_revision_missing';
    error.statusCode = 409;
    throw error;
  }
  const createdAt = Number(proposal.createdAt || 0);
  if (!Number.isFinite(createdAt) || createdAt <= 0 || Date.now() - createdAt > D2_IMPORT_PROPOSAL_TTL_MS) {
    const error = new Error('D2 import proposal expired. Analyze the D2 source again.');
    error.code = 'diagram_import_proposal_expired';
    error.statusCode = 409;
    throw error;
  }
  const expected = signDiagramImportProposal(proposal, authToken).signature;
  if (!proposal.signature || !timingSafeEqualString(proposal.signature, expected)) {
    const error = new Error('D2 import proposal provenance is invalid. Analyze the D2 source again.');
    error.code = 'diagram_import_proposal_invalid';
    error.statusCode = 409;
    throw error;
  }
  if (proposal.source && proposal.source.hash && sha256Hex(proposal.sourceText || '') !== proposal.source.hash) {
    const error = new Error('D2 source changed after analysis. Analyze it again.');
    error.code = 'diagram_import_source_conflict';
    error.statusCode = 409;
    throw error;
  }
  return proposal;
}

function assertDiagramImportProposalDeterministicSpec(proposal, spec, action = 'using Assistant') {
  if (diagramImportDeterministicSpecHash(spec) === String(proposal && proposal.deterministicSpecHash || '')) return;
  const error = new Error(`Deterministic template configuration changed after D2 analysis. Analyze the D2 source again before ${action}.`);
  error.code = 'diagram_import_deterministic_conflict';
  error.statusCode = 409;
  throw error;
}

function assertDiagramImportStoredSource(proposal, spec, action = 'applying its mapping') {
  const storedSource = String(templateAuthoringD2(spec, { allowLegacy: false }).source || '');
  if (!storedSource || sha256Hex(storedSource) === String(proposal && proposal.source && proposal.source.hash || '')) return;
  const error = new Error(`D2 source changed after analysis. Analyze the current source again before ${action}.`);
  error.code = 'diagram_import_source_conflict';
  error.statusCode = 409;
  throw error;
}

function diagramImportAssistantSpec(currentSpec, proposal = null) {
  const next = cloneJsonValueServer(currentSpec, {});
  next.result = next.result && typeof next.result === 'object' && !Array.isArray(next.result) ? next.result : {};
  const diagrams = Array.isArray(next.result.diagrams) ? next.result.diagrams : [];
  for (const diagram of diagrams) {
    const d2Import = diagram && diagram.authoring && diagram.authoring.d2Import;
    if (d2Import && typeof d2Import === 'object' && !Array.isArray(d2Import)) {
      delete d2Import.source;
      delete d2Import.structure;
      delete d2Import.template;
    }
    for (const family of ['nodeMappings', 'edgeMappings', 'groupMappings', 'hierarchyMappings']) {
      for (const mapping of normalizeDiagramMappingList(diagram[family])) delete mapping.d2Template;
    }
  }
  if (proposal && proposal.version === 3) {
    const diagram = diagrams.find((item) => item && typeof item === 'object' && !Array.isArray(item)) || { name: 'topology', type: 'topology' };
    if (!diagrams.includes(diagram)) diagrams.push(diagram);
    diagram.authoring = diagram.authoring && typeof diagram.authoring === 'object' && !Array.isArray(diagram.authoring) ? diagram.authoring : {};
    diagram.authoring.d2Import = {
      version: 3,
      semanticModelRevision: D2_IMPORT_SEMANTIC_MODEL_REVISION,
      roles: (proposal.roles || []).map((role) => ({
        id: role.id,
        key: role.key,
        kind: role.kind,
        notes: truncateText(String(role.notes || ''), 8000),
        visualKind: diagramImportRoleVisualKind(role),
        labelTemplate: String(role.labelTemplate || '')
      })),
      // A D2 class may be used by several placements. The Assistant must see
      // every placement independently; a role-level mapping cannot preserve
      // different parent contexts, filters, or materialization modes.
      placementMappings: (proposal.structureTree && Array.isArray(proposal.structureTree.items) ? proposal.structureTree.items : [])
        .map((item) => {
          const role = (proposal.roles || []).find((candidate) => String(candidate && candidate.id || '') === String(item && item.roleId || '')) || {};
          return {
            structureItemId: String(item && item.id || ''),
            roleId: String(role.id || ''),
            templateElementKey: String(item && item.templateElementKey || ''),
            parentStructureItemId: String(item && item.parentId || ''),
            visualKind: diagramImportRoleVisualKind(role),
            mapping: diagramImportStructureItemMapping(role, item && item.mapping || {}, item && item.id || '')
          };
        }),
      relationRules: cloneJsonValueServer(proposal.relationRules, []),
      structureTree: cloneJsonValueServer(proposal.structureTree, {}),
      templateGrammar: cloneJsonValueServer(proposal.templateGrammar, {})
    };
  }
  next.result.diagrams = diagrams;
  const inputBytes = Buffer.byteLength(stableJsonStringify(next), 'utf8');
  if (inputBytes > D2_IMPORT_ASSISTANT_MAX_SPEC_BYTES) {
    const error = new Error(`D2 assistant spec exceeded configured maxSpecBytes=${D2_IMPORT_ASSISTANT_MAX_SPEC_BYTES}.`);
    error.code = 'd2_import_assistant_spec_limit';
    error.statusCode = 413;
    throw error;
  }
  return next;
}

function diagramImportV3WithOverrides(proposal, roleOverrides = [], relationRules, structureTree, currentSpec = {}) {
  const next = cloneJsonValueServer(proposal, {});
  const overrides = new Map((Array.isArray(roleOverrides) ? roleOverrides : []).filter((item) => item && item.id).map((item) => [String(item.id), item]));
  const structure = next.structure && typeof next.structure === 'object' && !Array.isArray(next.structure) ? next.structure : {};
  next.roles = (Array.isArray(next.roles) ? next.roles : []).map((role) => {
    const override = overrides.get(String(role.id || '')) || {};
    const overrideValue = (name, fallback) => Object.prototype.hasOwnProperty.call(override, name) ? override[name] : fallback;
    const modeled = diagramImportApplyRoleModel({
      ...role,
      visualKind: overrideValue('visualKind', role.visualKind),
      labelTemplate: overrideValue('labelTemplate', role.labelTemplate)
    });
    return { ...modeled, structure };
  });
  next.roles = diagramImportWithRoleModelCandidates(next.roles, structure);
  if (Array.isArray(relationRules)) next.relationRules = cloneJsonValueServer(relationRules, []);
  const requestedStructureTree = structureTree === undefined ? next.structureTree : structureTree;
  next.structureTree = requestedStructureTree && typeof requestedStructureTree === 'object' && !Array.isArray(requestedStructureTree) &&
    Number(requestedStructureTree.version || 0) === D2_IMPORT_STRUCTURE_TREE_VERSION && Array.isArray(requestedStructureTree.items)
    ? diagramImportStructureTree(requestedStructureTree, next.structure, next.roles)
    : null;
  next.relationRules = diagramImportTopologyRules(next.roles, next.structure, next.relationRules, next.classes);
  next.templateGrammar = diagramImportTemplateGrammar(next.roles, next.structure, next.classes);
  next.unresolved = diagramImportV3Unresolved(next.roles, next.relationRules, next.structureTree, currentSpec, next.structure);
  return next;
}

function diagramImportRoleMappedClassNames(proposal, roleId) {
  const roles = new Map((Array.isArray(proposal && proposal.roles) ? proposal.roles : []).map((role) => [String(role && role.id || ''), role]));
  return uniqueStrings((proposal && proposal.structureTree && Array.isArray(proposal.structureTree.items) ? proposal.structureTree.items : [])
    .filter((item) => String(item && item.roleId || '') === String(roleId || ''))
    .map((item) => {
      const role = roles.get(String(item && item.roleId || '')) || {};
      const mapping = diagramImportStructureItemMapping(role, item && item.mapping || {}, item && item.id || '');
      return String(mapping && mapping.primary && mapping.primary.className || '').trim();
    }).filter(Boolean));
}

// The uploaded D2 document is an immutable role/style catalog. The saved
// structure tree is the executable parent grammar; runtime elements still
// have to use a declared role and D2 blueprint from this catalog.
function diagramImportTemplateGrammar(roles, structure, classes = []) {
  const source = structure && typeof structure === 'object' && !Array.isArray(structure) ? structure : {};
  const nodes = Array.isArray(source.nodes) ? source.nodes : [];
  const groups = Array.isArray(source.groups) ? source.groups : [];
  const edges = Array.isArray(source.edges) ? source.edges : [];
  const all = nodes.concat(groups);
  const roleByElementKey = new Map();
  const classByKey = new Map((Array.isArray(classes) ? classes : []).map((item) => [String(item && item.key || ''), item]));
  for (const role of Array.isArray(roles) ? roles : []) {
    for (const key of Array.isArray(role && role.elementKeys) ? role.elementKeys : []) {
      if (key) roleByElementKey.set(String(key), role);
    }
  }
  const elements = all.map((element) => {
    const key = String(element && element.key || '').trim();
    const parentKey = String(element && element.parentKey || '').trim();
    const role = roleByElementKey.get(key) || {};
    const parentRole = roleByElementKey.get(parentKey) || {};
    const kind = groups.includes(element) ? 'group' : 'node';
    return {
      key,
      kind,
      roleId: String(role.id || ''),
      roleKey: String(role.key || ''),
      pathSegments: Array.isArray(element && element.pathSegments) ? element.pathSegments.map(String) : [],
      parentKey,
      parentRoleId: String(parentRole.id || ''),
      parentRoleKey: String(parentRole.key || ''),
      childKeys: uniqueStrings(element && element.childrenKeys || []),
      fingerprint: hashJson({ kind, roleKey: String(role.key || ''), parentRoleKey: String(parentRole.key || ''), key })
    };
  }).filter((element) => element.key && element.roleKey);
  const elementByKey = new Map(elements.map((element) => [element.key, element]));
  const roleContracts = (Array.isArray(roles) ? roles : []).map((role) => {
    const roleElements = elements.filter((element) => element.roleId === String(role && role.id || ''));
    const parentRoleKeys = uniqueStrings(roleElements.map((element) => element.parentRoleKey).filter(Boolean));
    const childRoleKeys = uniqueStrings(roleElements.flatMap((element) => all
      .filter((candidate) => String(candidate && candidate.parentKey || '') === element.key)
      .map((candidate) => roleByElementKey.get(String(candidate && candidate.key || '')))
      .filter(Boolean)
      .map((candidate) => String(candidate.key || ''))));
    const visualKind = diagramImportRoleVisualKind(role);
    return {
      roleId: String(role && role.id || ''),
      roleKey: String(role && role.key || ''),
      label: String(role && (role.labelTemplate || role.label || role.key) || ''),
      visualKind,
      semantic: diagramImportInternalSemantic(role),
      rootAllowed: roleElements.some((element) => !element.parentKey),
      parentRoleKeys,
      childRoleKeys,
      elementKeys: roleElements.map((element) => element.key),
      nodeElementKeys: roleElements.filter((element) => element.kind === 'node').map((element) => element.key),
      groupElementKeys: roleElements.filter((element) => element.kind === 'group').map((element) => element.key),
      exemplarKey: ''
    };
  }).filter((role) => role.roleId && role.roleKey);
  const edgeBlueprints = edges.map((edge) => {
    const key = String(edge && edge.key || '').trim();
    const sourceKey = String(edge && edge.sourceKey || '').trim();
    const targetKey = String(edge && edge.targetKey || '').trim();
    const sourceElement = elementByKey.get(sourceKey) || {};
    const targetElement = elementByKey.get(targetKey) || {};
    const edgeClass = diagramImportEdgeClassContract(edge, classes);
    return {
      key,
      label: String(edge && edge.label || ''),
      sourceKey,
      targetKey,
      sourcePathSegments: Array.isArray(edge && edge.sourcePathSegments) ? edge.sourcePathSegments.map(String) : [],
      targetPathSegments: Array.isArray(edge && edge.targetPathSegments) ? edge.targetPathSegments.map(String) : [],
      sourceRoleKey: String(sourceElement.roleKey || ''),
      targetRoleKey: String(targetElement.roleKey || ''),
      classKey: edgeClass.key,
      classKeys: edgeClass.classKeys,
      classNotes: edgeClass.notes,
      direction: String(edge && edge.direction || '->'),
      styleHints: cloneJsonValueServer(edge && edge.styleHints, {}),
      fingerprint: hashJson({ sourceRoleKey: String(sourceElement.roleKey || ''), targetRoleKey: String(targetElement.roleKey || ''), classKey: edgeClass.key, direction: String(edge && edge.direction || '->'), key })
    };
  }).filter((edge) => edge.key && edge.sourceRoleKey && edge.targetRoleKey);
  const relationClasses = [];
  const relationClassByKey = new Map();
  for (const edge of edgeBlueprints) {
    const key = String(edge.classKey || '').trim();
    if (!key) continue;
    let contract = relationClassByKey.get(key);
    if (!contract) {
      const definition = classByKey.get(key) || {};
      contract = {
        key,
        classKeys: Array.isArray(edge.classKeys) ? edge.classKeys.map(String) : [],
        notes: String(edge.classNotes || definition.notes || ''),
        elementKeys: [],
        endpointRolePairs: []
      };
      relationClassByKey.set(key, contract);
      relationClasses.push(contract);
    }
    contract.elementKeys.push(edge.key);
    const pair = {
      sourceRoleKey: String(edge.sourceRoleKey || ''),
      targetRoleKey: String(edge.targetRoleKey || ''),
      direction: String(edge.direction || '->')
    };
    if (!contract.endpointRolePairs.some((item) => hashJson(item) === hashJson(pair))) contract.endpointRolePairs.push(pair);
  }
  const structureContexts = diagramImportStructureTreeContextCatalog(structure, roles).map((context) => ({
    key: String(context.key || ''),
    roleId: String(context.roleId || ''),
    parentContextKey: String(context.parentContextKey || ''),
    elementKeys: uniqueStrings(context.elementKeys || []).sort()
  }));
  return {
    version: 3,
    elements,
    roles: roleContracts,
    edges: edgeBlueprints,
    relationClasses,
    contexts: structureContexts,
    fingerprint: hashJson({ elements, roles: roleContracts, edges: edgeBlueprints, relationClasses, contexts: structureContexts })
  };
}

function diagramImportManagedAlias(prefix, id) {
  return `${prefix}_${sha256Hex(String(id || prefix)).slice(0, 12)}`;
}

function diagramImportStaticRoleRows(role, family) {
  const structure = role && role.structure && typeof role.structure === 'object' ? role.structure : {};
  const source = family === 'groupMappings'
    ? Array.isArray(structure.groups) ? structure.groups : []
    : Array.isArray(structure.nodes) ? structure.nodes : [];
  const allowed = new Set(Array.isArray(role && role.elementKeys) ? role.elementKeys.map(String) : []);
  return source.filter((item) => item && allowed.has(String(item.key || ''))).map((item) => ({
    id: item.key,
    _id: item.key,
    Code: item.key,
    Description: item.label || item.key,
    Class: family === 'groupMappings' ? 'D2StaticContainer' : 'D2StaticNode',
    ParentKey: item.parentKey || '',
    GroupKey: Array.isArray(item.groupKeys) && item.groupKeys.length ? item.groupKeys[0] : item.parentKey || ''
  }));
}

function diagramImportEnsureStepColumn(step, column) {
  const name = String(column || '').trim();
  if (!step || !name) return;
  step.columns = uniqueStrings([].concat(step.columns || [], name));
}

function diagramImportCompileTraversal(options) {
  const path = Array.isArray(options.path) ? options.path : [];
  const steps = [];
  let from = options.from;
  let currentClass = options.startClass;
  let sourceProducer = options.sourceProducer || null;
  let rootIdField = '_id';
  let targetIdField = '_id';
  for (const [index, hop] of path.entries()) {
    const alias = diagramImportManagedAlias(options.aliasPrefix || 'd2_path', `${options.id}:${index}`);
    const nextHop = path[index + 1];
    const columns = uniqueStrings(index === path.length - 1
      ? options.finalColumns || []
      : nextHop && nextHop.kind === 'reference' ? [nextHop.name] : []);
    const relationDomain = String(hop.domain || (hop.kind === 'domain' ? hop.name : '')).trim();
    if (hop.kind === 'reference' && !relationDomain) {
      diagramImportEnsureStepColumn(sourceProducer, hop.name);
      const step = {
        type: 'selectCards',
        as: alias,
        from,
        className: hop.targetClass,
        columns,
        filters: [{ path: 'Description', op: 'equals', valueColumn: hop.name }],
        sourcePrefix: 'Root_',
        managedBy: 'd2ImportV3'
      };
      steps.push(step);
      rootIdField = `Root_${rootIdField}`;
      targetIdField = '_id';
      sourceProducer = step;
    } else {
      const step = {
        type: 'expandRelations',
        as: alias,
        from,
        sourceClass: index === 0 ? currentClass : undefined,
        targetClass: hop.targetClass,
        domain: relationDomain,
        direction: hop.direction || 'both',
        columns,
        distinct: true,
        sourcePrefix: 'Root_',
        managedBy: 'd2ImportV3'
      };
      steps.push(step);
      rootIdField = index === 0 ? 'SourceId' : `Root_${rootIdField}`;
      targetIdField = 'RelatedId';
      sourceProducer = step;
    }
    from = alias;
    currentClass = hop.targetClass || currentClass;
  }
  return { alias: from, steps, rootIdField, targetIdField, targetClass: currentClass };
}

function diagramImportRuntimeLabelTemplate(role, primary = {}) {
  let template = String(primary && primary.labelTemplate || role && role.labelTemplate || '${Description}');
  template = template.replace(/\$\{primary\.([^{}]+)\}/g, '${$1}');
  return template;
}

function diagramImportConditionSetOperation(type, from, rightAlias, itemId, suffix) {
  return {
    type,
    as: diagramImportManagedAlias('d2_condition_set', `${itemId}:${suffix}:${type}`),
    from,
    with: rightAlias,
    on: ['Class', '_id'],
    distinct: true,
    managedBy: 'd2ImportV3'
  };
}

function diagramImportStageHasMaterializedField(stage, field) {
  const name = String(field || '').trim();
  return Boolean(name) && new Set(Array.isArray(stage && stage.columns) ? stage.columns.map(String) : []).has(name);
}

function diagramImportConditionPathCorrelationKey(field) {
  const path = String(field || '').trim();
  const terminalSeparator = path.lastIndexOf('.');
  if (terminalSeparator <= 0) return '';
  const relationPath = path.slice(0, terminalSeparator);
  return relationPath.includes('{') ? relationPath : '';
}

function diagramImportConditionSourceKey(source) {
  const normalized = normalizeDiagramImportConditionCardSource(source);
  return normalized ? [normalized.className, normalized.classColumn, normalized.idColumn].join(':').toLowerCase() : '';
}

function diagramImportConditionFieldKey(path, source) {
  return `${String(path || '').trim()}\u0000${diagramImportConditionSourceKey(source)}`;
}

// Older saved D2 mappings did not record which retained Object Flow card a
// deep field belonged to. New editor selections always persist that source.
// Runtime can read every retained source and accepts a value only when exactly
// one source provides it. This avoids both a guessed branch and the previous
// silent loss of all rows when a field was read from the wrong ancestor.
function diagramImportImplicitConditionSources(stage, path) {
  const field = String(path || '').trim();
  if (!field || diagramImportStageHasMaterializedField(stage, field)) return [];
  const available = new Set(Array.isArray(stage && stage.columns) ? stage.columns.map(String) : []);
  return (Array.isArray(stage && stage.cardSources) ? stage.cardSources : [])
    .map((source) => normalizeDiagramImportConditionCardSource(source))
    .filter(Boolean)
    .filter((source) => available.has(source.classColumn) && available.has(source.idColumn));
}

function diagramImportInferImplicitConditionSource(stage, path) {
  const candidates = diagramImportImplicitConditionSources(stage, path);
  return candidates.length === 1 ? candidates[0] : null;
}

function diagramImportHierarchyParentFieldKey(childItemId, conditionId) {
  return `hierarchy-parent:${String(childItemId || '')}:${String(conditionId || '')}`;
}

function diagramImportCompileConditionEnrichment(from, stage, fields, treeItemId, suffix) {
  const requests = [];
  const requestByKey = new Map();
  for (const [index, value] of (Array.isArray(fields) ? fields : []).entries()) {
    const candidate = value && typeof value === 'object' && !Array.isArray(value) ? value : { path: value };
    const path = String(candidate.path || candidate.column || '').trim();
    const explicitSource = normalizeDiagramImportConditionCardSource(candidate.source);
    const implicitSources = explicitSource ? [] : diagramImportImplicitConditionSources(stage, path);
    const implicitCurrent = implicitSources.length === 1 &&
      implicitSources[0].classColumn === 'Class' && implicitSources[0].idColumn === '_id';
    const source = explicitSource || (implicitSources.length === 1 && !implicitCurrent ? implicitSources[0] : null);
    const sourceCandidates = !explicitSource && implicitSources.length > 1 ? implicitSources : [];
    const key = String(candidate.key || `${index}:${path}:${diagramImportConditionSourceKey(source)}`).trim();
    if (!path || requestByKey.has(key)) continue;
    const request = {
      key,
      path,
      source,
      sourceCandidates,
      inferredSource: !explicitSource && (Boolean(source) || sourceCandidates.length > 0)
    };
    requestByKey.set(key, request);
    requests.push(request);
  }
  if (!from || !requests.length) return { alias: from, steps: [], fieldColumns: new Map(), inferredSources: [] };

  const steps = [];
  const fieldColumns = new Map();
  const groups = [];
  const groupBySource = new Map();
  for (const request of requests) {
    const sourceKey = diagramImportConditionSourceKey(request.source);
    const sourceCandidatesKey = request.sourceCandidates.map(diagramImportConditionSourceKey).join('|');
    if (!sourceKey && diagramImportStageHasMaterializedField(stage, request.path)) {
      fieldColumns.set(request.key, request.path);
      continue;
    }
    const key = sourceKey || (sourceCandidatesKey ? `retained:${sourceCandidatesKey}` : 'current');
    let group = groupBySource.get(key);
    if (!group) {
      group = { source: request.source, sourceCandidates: request.sourceCandidates, requests: [] };
      groupBySource.set(key, group);
      groups.push(group);
    }
    group.requests.push(request);
  }
  let alias = from;
  let generatedIndex = 0;
  for (const group of groups) {
    generatedIndex += 1;
    const as = diagramImportManagedAlias('d2_condition_enrich', `${treeItemId}:${suffix}:${generatedIndex}`);
    const columns = group.requests.map((request, requestIndex) => {
      const outputColumn = group.source
        ? `__d2_condition_${String(treeItemId || 'item').replace(/[^A-Za-z0-9_]/g, '_')}_${String(suffix || 'field').replace(/[^A-Za-z0-9_]/g, '_')}_${generatedIndex}_${requestIndex + 1}`
        : request.path;
      const correlationKey = diagramImportConditionPathCorrelationKey(request.path);
      const baseColumn = correlationKey
        ? { path: request.path, as: outputColumn, multiMode: 'rows', correlationKey }
        : group.source || (group.sourceCandidates && group.sourceCandidates.length)
          ? { path: request.path, as: outputColumn }
          : request.path;
      const column = group.sourceCandidates && group.sourceCandidates.length
        ? { ...baseColumn, sourceCandidates: group.sourceCandidates }
        : baseColumn;
      fieldColumns.set(request.key, outputColumn);
      return column;
    });
    steps.push({
      type: 'enrichRows',
      as,
      from: alias,
      columns,
      ...(group.source ? { classColumn: group.source.classColumn, idColumn: group.source.idColumn } : {}),
      purpose: 'd2PlacementFilter',
      managedBy: 'd2ImportV3'
    });
    alias = as;
  }
  return {
    alias,
    steps,
    fieldColumns,
    inferredSources: requests.filter((request) => request.inferredSource).map((request) => ({
      key: request.key,
      path: request.path,
      source: request.source,
      sourceCandidates: request.sourceCandidates
    }))
  };
}

function diagramImportCompileMappingConditions(mapping, treeItemId, primaryAlias, stageById = new Map(), primaryStage = null) {
  const conditions = diagramImportPlacementFilters(mapping && mapping.conditions);
  if (!primaryAlias || !conditions.rules.length) return { alias: primaryAlias, steps: [], stageCorrelations: [], inferredSources: [] };

  const steps = [];
  const primaryEnrichment = diagramImportCompileConditionEnrichment(
    primaryAlias,
    primaryStage,
    conditions.rules.map((condition, index) => ({
      key: `left:${index}`,
      path: condition && condition.left && condition.left.column,
      source: condition && condition.left && condition.left.source
    })),
    treeItemId,
    'primary'
  );
  steps.push(...primaryEnrichment.steps);
  const conditionSourceAlias = primaryEnrichment.alias;
  const comparisonEnrichments = new Map();
  for (const [index, condition] of conditions.rules.entries()) {
    if (!condition || !condition.right || condition.right.kind !== 'stage') continue;
    const stageId = String(condition.right.stageId || '');
    const comparisonStage = stageById.get(stageId) || {};
    const current = comparisonEnrichments.get(stageId) || {
      from: String(comparisonStage.alias || condition.right.stageId || ''),
      stage: comparisonStage,
      fields: []
    };
    current.fields.push({
      key: `right:${index}`,
      path: condition.right.column,
      source: condition.right.source
    });
    comparisonEnrichments.set(stageId, current);
  }
  const comparisonAliases = new Map();
  for (const [stageId, candidate] of comparisonEnrichments.entries()) {
    const enrichment = diagramImportCompileConditionEnrichment(
      candidate.from,
      candidate.stage,
      candidate.fields,
      treeItemId,
      `comparison:${stageId}`
    );
    steps.push(...enrichment.steps);
    comparisonAliases.set(stageId, enrichment.alias);
    candidate.fieldColumns = enrichment.fieldColumns;
  }
  const includedAliases = [];
  const excludedAliases = [];
  const stageCorrelations = [];
  for (const [index, condition] of conditions.rules.entries()) {
    const conditionId = String(condition.id || `condition_${index + 1}`);
    const as = diagramImportManagedAlias('d2_condition', `${treeItemId}:${conditionId}`);
    const matchesAfterNegationAreExcluded = (condition.action === 'exclude') !== Boolean(condition.negate);
    const leftColumn = primaryEnrichment.fieldColumns.get(`left:${index}`) || String(condition.left && condition.left.column || '');
    if (condition.right.kind === 'stage') {
      const comparisonStage = stageById.get(String(condition.right.stageId || '')) || {};
      const comparisonAlias = comparisonAliases.get(String(condition.right.stageId || '')) || String(comparisonStage.alias || condition.right.stageId || '');
      const comparisonCandidate = comparisonEnrichments.get(String(condition.right.stageId || '')) || {};
      const rightColumn = comparisonCandidate.fieldColumns && comparisonCandidate.fieldColumns.get(`right:${index}`) || String(condition.right.column || '');
      stageCorrelations.push({
        stageId: String(condition.right.stageId || ''),
        stageAlias: comparisonAlias,
        childColumn: leftColumn,
        childRegex: String(condition.left.regex || ''),
        parentColumn: rightColumn,
        parentRegex: String(condition.right.regex || ''),
        operator: String(condition.operator || 'equals'),
        caseSensitive: condition.caseSensitive === true,
        action: String(condition.action || 'include'),
        negate: Boolean(condition.negate)
      });
      steps.push({
        type: 'semiJoinRows',
        as,
        from: conditionSourceAlias,
        with: comparisonAlias,
        ruleJoin: 'all',
        rules: [{
          action: 'include',
          operator: condition.operator,
          leftColumn,
          leftRegex: condition.left.regex || '',
          rightColumn,
          rightRegex: condition.right.regex || '',
          caseSensitive: condition.caseSensitive === true
        }],
        managedBy: 'd2ImportV3'
      });
    } else {
      const filter = {
        matchCondition: true,
        action: 'include',
        op: condition.operator,
        column: leftColumn,
        leftRegex: condition.left.regex || '',
        rightRegex: condition.right.regex || '',
        caseSensitive: condition.caseSensitive === true
      };
      if (condition.right.kind === 'param') filter.valueParam = condition.right.name;
      else filter.value = condition.right.value;
      steps.push({
        type: 'filterRows',
        as,
        from: conditionSourceAlias,
        ruleJoin: 'all',
        filters: [filter],
        managedBy: 'd2ImportV3'
      });
    }
    (matchesAfterNegationAreExcluded ? excludedAliases : includedAliases).push(as);
  }

  let alias = conditionSourceAlias;
  if (includedAliases.length) {
    alias = includedAliases[0];
    for (const [index, candidate] of includedAliases.slice(1).entries()) {
      const step = diagramImportConditionSetOperation(
        conditions.ruleJoin === 'all' ? 'intersectRows' : 'unionRows',
        alias,
        candidate,
        treeItemId,
        `include_${index + 2}`
      );
      steps.push(step);
      alias = step.as;
    }
  }
  if (excludedAliases.length) {
    let excludedAlias = excludedAliases[0];
    for (const [index, candidate] of excludedAliases.slice(1).entries()) {
      const step = diagramImportConditionSetOperation('unionRows', excludedAlias, candidate, treeItemId, `exclude_${index + 2}`);
      steps.push(step);
      excludedAlias = step.as;
    }
    const step = diagramImportConditionSetOperation('differenceRows', alias, excludedAlias, treeItemId, 'excluded');
    steps.push(step);
    alias = step.as;
  }
  return { alias, steps, stageCorrelations, inferredSources: primaryEnrichment.inferredSources || [] };
}

// Hierarchy rules describe placement in an already materialized parent branch.
// They must never change the membership of the child Object Flow result.
function diagramImportCompileHierarchyCorrelations(mapping, treeItemId, primaryAlias, primaryStage = null, parentFieldColumns = new Map()) {
  const conditions = diagramImportPlacementFilters(mapping && mapping.hierarchyConditions);
  if (!primaryAlias || !conditions.rules.length) return { alias: primaryAlias, steps: [], stageCorrelations: [], inferredSources: [] };

  const primaryEnrichment = diagramImportCompileConditionEnrichment(
    primaryAlias,
    primaryStage,
    conditions.rules.map((condition, index) => ({
      key: `left:${index}`,
      path: condition && condition.left && condition.left.column,
      source: condition && condition.left && condition.left.source
    })),
    treeItemId,
    'hierarchy'
  );
  const stageCorrelations = conditions.rules.map((condition, index) => {
    const conditionId = String(condition && condition.id || `condition_${index + 1}`);
    const parentKey = diagramImportHierarchyParentFieldKey(treeItemId, conditionId);
    return {
      stageId: String(condition && condition.right && condition.right.stageId || ''),
      childColumn: primaryEnrichment.fieldColumns.get(`left:${index}`) || String(condition && condition.left && condition.left.column || ''),
      childRegex: String(condition && condition.left && condition.left.regex || ''),
      parentColumn: parentFieldColumns.get(parentKey) || String(condition && condition.right && condition.right.column || ''),
      parentRegex: String(condition && condition.right && condition.right.regex || ''),
      operator: String(condition && condition.operator || 'equals'),
      caseSensitive: condition && condition.caseSensitive === true,
      action: String(condition && condition.action || 'include'),
      negate: Boolean(condition && condition.negate)
    };
  });
  return {
    alias: primaryEnrichment.alias,
    steps: primaryEnrichment.steps,
    stageCorrelations,
    inferredSources: primaryEnrichment.inferredSources || []
  };
}

function diagramImportCompileRoleMapping(role, mapping, treeItemId = '', stageById = new Map(), runtimeSource = {}, parentFieldColumns = new Map(), requiredFields = []) {
  const source = runtimeSource && typeof runtimeSource === 'object' && !Array.isArray(runtimeSource)
    ? runtimeSource
    : {};
  const primary = mapping.primary || {};
  const visualKind = diagramImportRoleVisualKind(role);
  const materialization = mapping.materialization || {};
  const semantic = visualKind === 'container'
    ? (String(materialization.kind || '') === 'structural' ? 'structural' : 'group')
    : 'object';
  const idAttribute = diagramImportPrimaryIdAttribute(role, primary);
  const steps = [];
  const primaryAlias = String(source.alias || '').trim() || (primary.className ? diagramImportManagedAlias('d2_primary', `${role.id}:${treeItemId || 'mapping'}`) : '');
  const relatedBindings = [];
  if (primaryAlias && !source.alias) {
    const columns = uniqueStrings(['Class', '_id', 'Code', 'Description', idAttribute]
      .concat(primary.structuredFields || [])
      .concat(diagramImportPrimaryTemplateFieldNames(primary.labelTemplate || '')));
    steps.push({
      type: 'selectCards',
      as: primaryAlias,
      className: primary.className,
      columns,
      limit: semantic === 'static' ? 2 : undefined,
      managedBy: 'd2ImportV3'
    });
  }
  const sourceStage = stageById.get(String(source.stageId || '')) || null;
  const requiredEnrichment = diagramImportCompileConditionEnrichment(
    primaryAlias,
    sourceStage,
    requiredFields,
    treeItemId,
    'hierarchy-parent'
  );
  const filters = diagramImportCompileMappingConditions({ conditions: mapping.conditions }, treeItemId || role.id, requiredEnrichment.alias, stageById, sourceStage);
  const hierarchy = diagramImportCompileHierarchyCorrelations(mapping, treeItemId || role.id, filters.alias, sourceStage, parentFieldColumns);
  steps.push(...requiredEnrichment.steps, ...filters.steps, ...hierarchy.steps);
  const runtimePrimaryAlias = hierarchy.alias;
  if (runtimePrimaryAlias) {
    for (const related of Array.isArray(mapping.related) ? mapping.related : []) {
      const relatedStage = stageById.get(String(related && related.stageId || '')) || null;
      if (!relatedStage || !String(relatedStage.alias || '').trim()) continue;
      relatedBindings.push({
        id: related.id,
        alias: String(relatedStage.alias || '').trim(),
        sourceStageId: String(relatedStage.id || ''),
        labelValueMode: normalizeDiagramImportRelatedLabelValueMode(related.labelValueMode),
        labelSeparator: String(related.labelSeparator || ', '),
        structuredFields: uniqueStrings(related.structuredFields || []),
        conditions: diagramImportPlacementFilters(related.conditions)
      });
    }
  }
  const importRole = {
    roleId: String(role.id || ''),
    key: role.key,
    label: role.label,
    kind: role.kind,
    semantic,
    visualKind,
    elementKeys: Array.isArray(role.elementKeys) ? role.elementKeys.map(String) : [],
    exemplarKey: String(role.exemplarKey || ''),
    styleHints: cloneJsonValueServer(role.styleHints, {}),
    sourceStageId: String(source.stageId || ''),
    sourceAlias: String(source.baseAlias || source.alias || ''),
    sourceLabel: String(source.label || '')
  };
  const runtimeMapping = {
    // Authoring mapping ids identify editable bindings. Runtime mapping ids must
    // remain role-scoped because a repeated group can inherit those bindings.
    id: '',
    from: runtimePrimaryAlias,
    fields: { id: idAttribute, label: 'Description' },
    labelTemplate: diagramImportRuntimeLabelTemplate(role, primary),
    dataProfile: {
      name: role.key,
      className: primary.className || '',
      fields: uniqueStrings((primary.structuredFields || []).concat(relatedBindings.flatMap((related) => related.structuredFields.map((field) => `${related.id}.${field}`)))),
      includeSourceRef: true
    },
    relatedBindings,
    disableImplicitGroup: true,
    singleton: semantic === 'static' && Boolean(runtimePrimaryAlias),
    staticRows: !runtimePrimaryAlias && diagramImportSemanticIsStructural(semantic) ? [{
      id: role.id,
      _id: role.id,
      Code: role.key,
      Description: role.label,
      Class: 'D2StaticContainer'
    }] : [],
    importRole
  };
  let runtimeMappings;
  if (!runtimePrimaryAlias && diagramImportSemanticIsStructural(semantic) && role.kind === 'd2Class') {
    const families = Array.isArray(role.containerKeys) && role.containerKeys.length
      ? ['groupMappings']
      : ['nodeMappings'];
    runtimeMappings = families.map((family) => {
      const staticRows = diagramImportStaticRoleRows(role, family);
      if (!staticRows.length) return null;
      return {
        family,
        mapping: {
          ...cloneJsonValueServer(runtimeMapping, {}),
          id: diagramImportStableId('mapping', `${role.id}:${treeItemId || 'mapping'}:${family}`),
          fields: family === 'groupMappings'
            ? { id: '_id', label: 'Description', parent: 'ParentKey' }
            : { id: '_id', label: 'Description', group: 'GroupKey' },
          disableImplicitGroup: family === 'nodeMappings' ? false : runtimeMapping.disableImplicitGroup,
          staticRows
        }
      };
    }).filter(Boolean);
  } else {
    const family = semantic === 'group' || diagramImportSemanticIsStructural(semantic) && (role.kind === 'untypedContainer' || (role.containerKeys || []).length)
      ? 'groupMappings'
      : 'nodeMappings';
    runtimeMappings = [{
      family,
      mapping: {
        ...runtimeMapping,
        id: diagramImportStableId('mapping', `${role.id}:${treeItemId || 'mapping'}:${family}`)
      }
    }];
  }
  return {
    semantic,
    steps,
    primaryAlias: runtimePrimaryAlias,
    primaryStep: steps.find((step) => step.type === 'selectCards' && step.as === primaryAlias),
    runtimeMapping,
    runtimeMappings,
    hierarchyFieldColumns: requiredEnrichment.fieldColumns,
    stageCorrelations: hierarchy.stageCorrelations,
    conditionSourceRepairs: (filters.inferredSources || []).concat(hierarchy.inferredSources || []).map((repair) => ({
      ...repair,
      structureItemId: String(treeItemId || ''),
      stageId: String(source.stageId || '')
    })),
    mappingId: String(mapping && mapping.id || ''),
    className: String(primary.className || '')
  };
}

function diagramImportCompileStructureTree(structureTree, roles, stageById) {
  const normalizedTree = diagramImportStructureTree(structureTree, null, roles);
  const roleById = new Map((Array.isArray(roles) ? roles : []).map((role) => [String(role && role.id || ''), role]));
  const itemById = new Map(normalizedTree.items.map((item) => [String(item && item.id || ''), item]).filter(([id]) => id));
  const compiledByItemId = new Map();
  const compiledByRoleId = new Map();
  const runtimeMappings = [];
  const steps = [];
  const conditionSourceRepairs = [];
  const hierarchyParentFieldRequirements = new Map();
  for (const item of normalizedTree.items) {
    const role = roleById.get(String(item && item.roleId || '')) || {};
    const mapping = diagramImportStructureItemMapping(role, item && item.mapping || {}, String(item && item.id || ''));
    const ancestor = diagramImportNearestMaterializedAncestor(normalizedTree, roles, item);
    if (!ancestor || !ancestor.item || !ancestor.stageId) continue;
    const fields = hierarchyParentFieldRequirements.get(String(ancestor.item.id || '')) || [];
    for (const [index, condition] of diagramImportPlacementFilters(mapping.hierarchyConditions).rules.entries()) {
      if (!condition || !condition.right || condition.right.kind !== 'stage' || String(condition.right.stageId || '') !== String(ancestor.stageId || '')) continue;
      const key = diagramImportHierarchyParentFieldKey(item && item.id, condition.id || `condition_${index + 1}`);
      if (fields.some((field) => String(field && field.key || '') === key)) continue;
      fields.push({ key, path: String(condition.right.column || ''), source: condition.right.source });
    }
    if (fields.length) hierarchyParentFieldRequirements.set(String(ancestor.item.id || ''), fields);
  }
  const depthForItem = (item) => {
    let depth = 0;
    const visited = new Set([String(item && item.id || '')]);
    let parentId = String(item && item.parentId || '');
    while (parentId && !visited.has(parentId)) {
      visited.add(parentId);
      depth += 1;
      parentId = String((itemById.get(parentId) || {}).parentId || '');
    }
    return depth;
  };
  const nearestCompiledParent = (item) => {
    const visited = new Set([String(item && item.id || '')]);
    let parentId = String(item && item.parentId || '');
    while (parentId && !visited.has(parentId)) {
      visited.add(parentId);
      const compiled = compiledByItemId.get(parentId);
      if (compiled && compiled.primaryAlias) return compiled;
      parentId = String((itemById.get(parentId) || {}).parentId || '');
    }
    return null;
  };
  const orderedItems = normalizedTree.items.slice().sort((left, right) => depthForItem(left) - depthForItem(right) || String(left && left.id || '').localeCompare(String(right && right.id || '')));
  for (const item of orderedItems) {
    const role = roleById.get(String(item && item.roleId || ''));
    if (!role) continue;
    const storedMapping = item && item.mapping && typeof item.mapping === 'object' && !Array.isArray(item.mapping)
      ? item.mapping
      : {};
    // Normalization supplies editor defaults, but it must never turn a saved
    // incomplete placement into a structural runtime binding.
    if (!diagramImportHasExplicitMaterialization(storedMapping)) continue;
    const mapping = diagramImportStructureItemMapping(role, storedMapping, String(item && item.id || ''));
    const materialization = mapping.materialization || {};
    const materializationKind = String(materialization.kind || '');
    let stage = stageById.get(String(materialization.stageId || '')) || null;
    const nearestParent = nearestCompiledParent(item);
    const inherited = materializationKind === 'parentCard' ? nearestParent : null;
    if (inherited) stage = inherited.stage || null;
    const visualKind = diagramImportRoleVisualKind(role);
    const importRole = {
      roleId: String(role.id || ''),
      key: String(role.key || ''),
      label: String(role.label || role.key || ''),
      kind: String(role.kind || ''),
      semantic: visualKind === 'container' ? (materializationKind === 'structural' ? 'structural' : 'group') : 'object',
      visualKind,
      materialization: materializationKind,
      ...(visualKind === 'container' ? { showEmpty: mapping.showEmpty !== false } : {}),
      elementKey: String(item.templateElementKey || ''),
      elementKeys: uniqueStrings(item && item.templateElementKeys || [String(item.templateElementKey || '')]).filter(Boolean),
      structureItemId: String(item.id || ''),
      parentStructureItemId: String(item.parentId || ''),
      styleHints: cloneJsonValueServer(role.styleHints || {}, {})
    };
    if (materializationKind === 'structural' && visualKind === 'container') {
      const staticLabelTemplate = diagramImportRuntimeLabelTemplate(role, mapping.primary || {});
      const structuralElements = role && role.structure && Array.isArray(role.structure.groups)
        ? role.structure.groups
        : [];
      const declaredElement = structuralElements.find((element) => String(element && element.key || '') === String(item.templateElementKey || '')) || {};
      runtimeMappings.push({
        family: 'groupMappings',
        item,
        mapping: {
          id: diagramImportStableId('mapping', `structure:${item.id}:static`),
          from: '',
          fields: { id: '_id', label: 'Description', parent: 'ParentKey' },
          labelTemplate: staticLabelTemplate,
          dataProfile: { name: String(role.key || ''), className: '', fields: [], includeSourceRef: false },
          disableImplicitGroup: true,
          staticRows: [{
            id: `structure:${item.id}`,
            _id: `structure:${item.id}`,
            Code: String(declaredElement.key || role.key || item.id || ''),
            // An explicitly blank D2 container label is intentional. Falling
            // back to the class key leaks a technical name such as scope_vlan
            // into a preview that has no dynamic rows.
            Description: Object.prototype.hasOwnProperty.call(declaredElement, 'label')
              ? String(declaredElement.label || '')
              : String(role.label || role.key || ''),
            Class: 'D2StaticContainer',
            ParentKey: ''
          }],
          importRole
        }
      });
      compiledByItemId.set(String(item.id), { item, role, stage: null, primaryAlias: '', primaryStep: null, runtimeMappings: [] });
      continue;
    }
    if (!stage) continue;
    // Every structure item is an independent data binding. Sharing a compiled
    // source by role or Object Flow stage silently makes sibling D2 placements
    // inherit each other's filters, labels, and related traversals.
    const compiledMapping = cloneJsonValueServer(mapping, {});
    const runtimeSource = {
      stageId: String(stage.id || ''),
      alias: inherited ? String(inherited.primaryAlias || '') : String(stage.alias || ''),
      baseAlias: inherited
        ? String(inherited.runtimeMapping && inherited.runtimeMapping.importRole && inherited.runtimeMapping.importRole.sourceAlias || stage.alias || '')
        : String(stage.alias || ''),
      kind: String(stage.kind || ''),
      className: String(stage.className || ''),
      label: String(stage.label || '')
    };
    compiledMapping.primary = {
      ...(compiledMapping.primary || {}),
      className: String(compiledMapping.primary && compiledMapping.primary.className || stage.className || '')
    };
    const compilerRole = {
      ...cloneJsonValueServer(role, {}),
      id: `${String(role.id || 'role')}_${sha256Hex(String(item.id || '')).slice(0, 12)}`
    };
    const compiled = diagramImportCompileRoleMapping(
      compilerRole,
      compiledMapping,
      String(item.id || 'mapping'),
      stageById,
      runtimeSource,
      nearestParent && nearestParent.hierarchyFieldColumns || new Map(),
      hierarchyParentFieldRequirements.get(String(item.id || '')) || []
    );
    compiled.role = role;
    compiled.stage = stage;
    compiled.item = item;
    compiled.className = String(compiledMapping.primary && compiledMapping.primary.className || stage.className || '');
    steps.push(...(compiled.steps || []));
    conditionSourceRepairs.push(...(compiled.conditionSourceRepairs || []));
    compiledByItemId.set(String(item.id), { ...compiled, item, role, stage });
    const roleCompilations = compiledByRoleId.get(String(role.id || '')) || [];
    roleCompilations.push(compiled);
    compiledByRoleId.set(String(role.id || ''), roleCompilations);
    for (const runtime of compiled.runtimeMappings || []) {
      const mappingValue = cloneJsonValueServer(runtime.mapping || {}, {});
      mappingValue.id = diagramImportStableId('mapping', `structure:${item.id}:${runtime.family}`);
      const parentStageId = String(nearestParent && nearestParent.stage && nearestParent.stage.id || '');
      const hierarchyRuleJoin = diagramImportPlacementFilters(compiledMapping.hierarchyConditions).ruleJoin;
      const parentCorrelations = materializationKind === 'stage' && parentStageId
        ? (compiled.stageCorrelations || []).filter((correlation) =>
          String(correlation && correlation.stageId || '') === parentStageId &&
          String(correlation && correlation.childColumn || '') &&
          String(correlation && correlation.parentColumn || '')
        ).map((correlation) => ({
          parentStructureItemId: String(nearestParent && nearestParent.item && nearestParent.item.id || ''),
          childColumn: String(correlation.childColumn || ''),
          childRegex: String(correlation.childRegex || ''),
          parentColumn: String(correlation.parentColumn || ''),
          parentRegex: String(correlation.parentRegex || ''),
          operator: String(correlation.operator || 'equals'),
          caseSensitive: correlation.caseSensitive === true,
          action: String(correlation.action || 'include'),
          negate: Boolean(correlation.negate),
          ruleJoin: hierarchyRuleJoin === 'all' ? 'all' : 'any'
        }))
        : [];
      mappingValue.importRole = {
        ...(mappingValue.importRole && typeof mappingValue.importRole === 'object' ? mappingValue.importRole : {}),
        ...importRole,
        parentCorrelations
      };
      runtimeMappings.push({ family: runtime.family, item, mapping: mappingValue });
    }
  }
  return { tree: normalizedTree, runtimeMappings, steps, compiledByItemId, compiledByRoleId, conditionSourceRepairs };
}

function diagramImportCompileRelationRule(rule, roleById, compiledByItemId, stageById = new Map()) {
  const parentRole = roleById.get(String(rule.parentRoleId || ''));
  const childRole = roleById.get(String(rule.childRoleId || ''));
  const mode = String(rule && rule.mode || '');
  const stage = stageById.get(String(rule && rule.sourceStageId || ''));
  if (!parentRole || !childRole || !['relationCard', 'networkEndpoints', 'deterministicEndpoints'].includes(mode) ||
    !stage || !String(rule.sourceField || '').trim() || !String(rule.targetField || '').trim()) return [];
  const cardSources = Array.isArray(stage.cardSources) ? stage.cardSources : [];
  const matchEndpointSources = mode === 'deterministicEndpoints' && String(stage.kind || '') === 'match' && cardSources.length >= 2
    ? [cardSources[0], cardSources[1]]
    : null;
  // A match stage carries two source-card lineages. Its compared business
  // fields (for example Location) establish eligibility but are not endpoint
  // identities. Resolve the D2 edge through the card id columns instead.
  const sourceField = String(matchEndpointSources && matchEndpointSources[0] && matchEndpointSources[0].idColumn || rule.sourceField);
  const targetField = String(matchEndpointSources && matchEndpointSources[1] && matchEndpointSources[1].idColumn || rule.targetField);
  if (!sourceField || !targetField) return [];
  return [{
    rule: cloneJsonValueServer(rule, {}),
    alias: stage.alias,
    steps: [],
    rootIdField: sourceField,
    targetIdField: targetField,
    labelField: String(rule.labelField || '').trim()
  }];
}

function diagramImportRuntimeRelationMappings(compiledRules, roleById, templateGrammar) {
  const edgeMappings = [];
  const hierarchyMappings = [];
  const classRelationRules = [];
  for (const compiled of compiledRules) {
    const rule = compiled.rule || {};
    const parentRole = roleById.get(String(rule.parentRoleId || ''));
    const childRole = roleById.get(String(rule.childRoleId || ''));
    const edgeBlueprint = (templateGrammar && Array.isArray(templateGrammar.edges) ? templateGrammar.edges : [])
      .find((edge) => String(edge && edge.key || '') === String(rule.d2ElementKey || '')) || {};
    const mapping = {
      id: diagramImportStableId('mapping', `${rule.id}:${compiled.sourceStructureItemId || compiled.alias || ''}`),
      from: compiled.alias,
      fields: rule.kind === 'hierarchy'
        ? { parent: compiled.rootIdField, child: compiled.targetIdField, label: 'Domain' }
        : { source: compiled.rootIdField, target: compiled.targetIdField, label: compiled.labelField || 'Domain' },
      importRole: {
        key: rule.id,
        label: String(edgeBlueprint.label || rule.d2Label || ''),
        semantic: rule.kind || 'connection',
        elementKey: String(rule.d2ElementKey || ''),
        elementKeys: Array.isArray(rule.d2ElementKeys) ? rule.d2ElementKeys.map(String) : [String(rule.d2ElementKey || '')].filter(Boolean),
        edgeClassKey: String(rule.d2ClassKey || ''),
        edgeClassKeys: Array.isArray(rule.d2ClassKeys) ? rule.d2ClassKeys.map(String) : [],
        edgeClassNotes: truncateText(String(rule.d2Notes || ''), 8000),
        edgeClassExampleLabels: Array.isArray(rule.d2ExampleLabels) ? rule.d2ExampleLabels.map(String) : [],
        parentKey: parentRole && parentRole.key || '',
        childKey: childRole && childRole.key || '',
        sourceKey: parentRole && parentRole.key || '',
        targetKey: childRole && childRole.key || '',
        directionPolicy: normalizeDiagramDirectionPolicy(rule.directionPolicy),
        styleHints: cloneJsonValueServer(edgeBlueprint.styleHints, {})
      },
      direction: normalizeDiagramDirectionPolicy(rule.directionPolicy) === 'undirected' ? '--' : String(edgeBlueprint.direction || '->'),
      label: String(edgeBlueprint.label || rule.d2Label || ''),
      labelTemplate: String(rule.labelTemplate || '').trim()
    };
    if (rule.kind === 'hierarchy') hierarchyMappings.push(mapping);
    else if (rule.kind === 'group') classRelationRules.push({
      ...rule,
      alias: compiled.alias,
      sourceField: compiled.rootIdField,
      targetField: compiled.targetIdField,
      parentRoleKey: parentRole && parentRole.key || '',
      childRoleKey: childRole && childRole.key || ''
    });
    else if (String(rule.mode || '') === 'networkEndpoints') {
      edgeMappings.push({
        ...mapping,
        type: 'networkEndpoints',
        endpointResolution: {
          strategy: 'ipv4ObjectThenRange',
          sourceField: compiled.rootIdField,
          targetField: compiled.targetIdField,
          directionPolicy: normalizeDiagramDirectionPolicy(rule.directionPolicy)
        }
      });
    } else {
      const mode = String(rule.mode || 'deterministicEndpoints');
      edgeMappings.push({
        ...mapping,
        type: mode === 'relationCard' ? 'relationObject' : mode === 'deterministicEndpoints' ? 'computed' : 'domain'
      });
    }
  }
  return { edgeMappings, hierarchyMappings, classRelationRules };
}

function objectFlowFromSpecServer(spec) {
  const models = Array.isArray(spec && spec.visualModels) ? spec.visualModels.slice() : [];
  if (spec && spec.visualModel && typeof spec.visualModel === 'object' && !Array.isArray(spec.visualModel)) {
    models.push(spec.visualModel);
  }
  const objectGroup = models.find((model) => model && model.mode === 'objectGroup') || {};
  const objectMatching = models.find((model) => model && model.mode === 'objectMatching') || {};
  const selections = Array.isArray(objectMatching.selections) && objectMatching.selections.length
    ? objectMatching.selections
    : (Array.isArray(objectGroup.selections) ? objectGroup.selections.map((selection) => ({
      ...selection,
      rules: selection && (selection.rules || selection.scopeRules) || []
    })) : []);
  const publishedOutput = (Array.isArray(objectMatching.outputs) ? objectMatching.outputs : [])
    .find((output) => output && output.published === true && String(output.alias || '').trim());
  const publishedTable = spec && spec.result && Array.isArray(spec.result.tables)
    ? spec.result.tables.find((table) => table && table.published === true && String(table.name || '').trim())
    : null;
  const flow = {
    selections,
    publishedAlias: String(publishedOutput && publishedOutput.alias || publishedTable && publishedTable.name || '').trim()
  };
  if (Array.isArray(objectMatching.operations)) {
    flow.operations = objectMatching.operations;
  } else {
    flow.blocks = objectMatching.blocks || [];
    flow.setOperations = objectMatching.setOperations || [];
  }
  return normalizeObjectFlow(flow);
}

function assistantObjectFlowTerminalAliases(spec) {
  const models = Array.isArray(spec && spec.visualModels) ? spec.visualModels : [];
  const objectMatching = models.find((model) => model && model.mode === 'objectMatching') || {};
  const outputs = Array.isArray(objectMatching.outputs) ? objectMatching.outputs : [];
  const terminalByBlockId = new Map();
  let assistantManaged = false;
  for (const output of outputs) {
    if (!output || output.assistantManaged !== true) continue;
    const alias = String(output.alias || '').trim();
    const blockIds = Array.isArray(output.assistantBlockIds)
      ? output.assistantBlockIds
      : [output.assistantBlockId];
    if (!alias || !blockIds.length) continue;
    assistantManaged = true;
    for (const rawBlockId of blockIds) {
      const blockId = String(rawBlockId || '').trim();
      if (blockId) terminalByBlockId.set(blockId, alias);
    }
  }
  return assistantManaged ? new Set(terminalByBlockId.values()) : new Set();
}

function diagramImportStageCardSourceKey(source) {
  return [
    String(source && source.className || '').trim().toLowerCase(),
    String(source && source.classColumn || '').trim(),
    String(source && source.idColumn || '').trim()
  ].join(':');
}

function diagramImportUniqueStageCardSources(values) {
  const result = [];
  const seen = new Set();
  for (const value of Array.isArray(values) ? values : []) {
    const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
    const className = String(source.className || '').trim();
    const classColumn = String(source.classColumn || '').trim();
    const idColumn = String(source.idColumn || '').trim();
    if (!className || !classColumn || !idColumn) continue;
    const item = {
      id: String(source.id || `${classColumn}:${idColumn}`).trim(),
      className,
      classColumn,
      idColumn,
      label: String(source.label || className).trim()
    };
    const key = diagramImportStageCardSourceKey(item);
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(item);
  }
  return result;
}

function diagramImportCurrentStageCardSource(className, label = '') {
  return {
    id: 'current',
    className: String(className || '').trim(),
    classColumn: 'Class',
    idColumn: '_id',
    label: String(label || 'Карточка результата').trim()
  };
}

function diagramImportPrefixedStageCardSource(source, prefix, labelPrefix = '') {
  return {
    id: `${String(prefix || '')}${String(source && source.id || '')}`,
    className: String(source && source.className || ''),
    classColumn: `${String(prefix || '')}${String(source && source.classColumn || '')}`,
    idColumn: `${String(prefix || '')}${String(source && source.idColumn || '')}`,
    label: `${String(labelPrefix || '')}${String(source && source.label || '')}`
  };
}

function assistantObjectFlowDiagramStages(spec, flow = objectFlowFromSpecServer(spec)) {
  const models = Array.isArray(spec && spec.visualModels) ? spec.visualModels : [];
  const objectMatching = models.find((model) => model && model.mode === 'objectMatching') || {};
  const outputByAlias = new Map((Array.isArray(objectMatching.outputs) ? objectMatching.outputs : [])
    .filter((output) => output && String(output.alias || '').trim())
    .map((output) => [String(output.alias), output]));
  const rawStages = objectFlowStageSummaries(flow);
  const rawByAlias = new Map(rawStages.map((stage) => [String(stage && stage.alias || ''), stage]));
  const lineageFor = (stage, seen = new Set()) => {
    const alias = String(stage && stage.alias || '').trim();
    if (!alias || seen.has(alias)) return [];
    const nextSeen = new Set(seen);
    nextSeen.add(alias);
    const dependencies = [stage && stage.from, stage && stage.with]
      .map((value) => rawByAlias.get(String(value || '').trim()))
      .filter(Boolean);
    return uniqueStrings([alias].concat(...dependencies.map((dependency) => lineageFor(dependency, nextSeen))));
  };
  const classNameFor = (stage, seen = new Set()) => {
    const alias = String(stage && stage.alias || '').trim();
    if (!stage || !alias || seen.has(alias)) return '';
    const direct = String(stage.className || (stage.kind === 'relation' ? stage.targetClass : '') || '').trim();
    if (direct) return direct;
    const from = rawByAlias.get(String(stage.from || '').trim());
    return classNameFor(from, new Set(seen).add(alias));
  };
  const cardSourcesByAlias = new Map();
  const cardSourcesFor = (stage, seen = new Set()) => {
    const alias = String(stage && stage.alias || '').trim();
    if (!stage || !alias || seen.has(alias)) return [];
    if (cardSourcesByAlias.has(alias)) return cardSourcesByAlias.get(alias);
    const nextSeen = new Set(seen);
    nextSeen.add(alias);
    const leftStage = rawByAlias.get(String(stage.from || '').trim());
    const rightStage = rawByAlias.get(String(stage.with || '').trim());
    const leftSources = cardSourcesFor(leftStage, nextSeen);
    const rightSources = cardSourcesFor(rightStage, nextSeen);
    let sources;
    if (stage.kind === 'selection') {
      sources = [diagramImportCurrentStageCardSource(classNameFor(stage))].concat(
        leftSources.map((source) => diagramImportPrefixedStageCardSource(source, 'Source_', 'Источник: '))
      );
    } else if (stage.kind === 'relation') {
      const relationSource = leftSources.find((source) => String(source && source.id || '') === 'current') || {};
      sources = [
        diagramImportCurrentStageCardSource(classNameFor(stage), 'Связанная карточка'),
        {
          id: 'relation-source',
          className: String(relationSource.className || ''),
          classColumn: 'SourceClass',
          idColumn: 'SourceId',
          label: 'Исходная карточка связи'
        }
      ].concat(leftSources.filter((source) => String(source && source.id || '') !== 'current')
        .map((source) => diagramImportPrefixedStageCardSource(source, 'Source_', 'Источник: ')));
    } else if (stage.kind === 'match') {
      const prefix = String(stage.rightPrefix || '');
      sources = leftSources.concat(rightSources.map((source) => diagramImportPrefixedStageCardSource(source, prefix, 'Сопоставленный: ')));
    } else if (stage.kind === 'set' && String(stage.operation || stage.type || '') === 'union') {
      sources = leftSources.concat(rightSources);
    } else {
      sources = leftSources;
    }
    const normalized = diagramImportUniqueStageCardSources(sources);
    cardSourcesByAlias.set(alias, normalized);
    return normalized;
  };
  const stages = rawStages.map((stage) => {
    const output = outputByAlias.get(String(stage && stage.alias || '')) || {};
    const lineageAliases = lineageFor(stage);
    const lineageLabels = uniqueStrings(lineageAliases.map((alias) => {
      const dependency = rawByAlias.get(alias) || {};
      const dependencyOutput = outputByAlias.get(alias) || {};
      return String(dependencyOutput.label || dependency.label || dependency.name || alias).trim();
    }).filter(Boolean));
    const assistantBlockIds = uniqueStrings(Array.isArray(output.assistantBlockIds)
      ? output.assistantBlockIds.map(String)
      : [String(output.assistantBlockId || '')].filter(Boolean));
    const relationSourceStage = stage.kind === 'relation' ? rawByAlias.get(String(stage.from || '').trim()) : null;
    const relationSourceFields = relationSourceStage ? uniqueStrings((Array.isArray(relationSourceStage.columns) ? relationSourceStage.columns : [])
      .map(String).filter((field) => !['Class', '_id', 'Code', 'Description'].includes(field))) : [];
    const relationSource = relationSourceStage && relationSourceFields.length ? {
      className: classNameFor(relationSourceStage),
      domain: String(stage.domain || ''),
      direction: String(stage.direction || '') === 'source' ? 'destination' : String(stage.direction || '') === 'destination' ? 'source' : 'both',
      structuredFields: relationSourceFields
    } : null;
    return {
      ...stage,
      label: String(output.label || stage.label || stage.name || stage.alias || stage.id || ''),
      className: classNameFor(stage),
      cardSources: cardSourcesFor(stage),
      assistantBlockIds,
      lineageAliases,
      lineageLabels,
      ...(relationSource && relationSource.className && relationSource.domain ? { relationSource } : {})
    };
  });
  // Diagram bindings are allowed to use every materialized deterministic
  // stage. Restricting Assistant to only named terminal outputs made the UI
  // offer sources that the server later rejected and hid valid intermediate
  // joins from D2 mappings.
  return stages;
}

function objectFlowMaterializedAliases(flow) {
  const normalized = normalizeObjectFlow(flow);
  return new Set(normalized.selections.concat(normalized.operations).map((stage) => String(stage && stage.alias || stage && stage.as || '').trim()).filter(Boolean));
}

function objectFlowStageManifest(flow) {
  const normalized = normalizeObjectFlow(flow);
  if (validateObjectFlow(normalized).length) return new Map();
  return new Map(objectFlowStageSummaries(normalized).map((stage) => [stage.alias, {
    kind: String(stage.kind || ''),
    className: String(stage.className || ''),
    columns: Array.from(new Set(Array.isArray(stage.columns) ? stage.columns.map((column) => String(column || '')).filter(Boolean) : [])).sort()
  }]));
}

function objectFlowStageKindOrClassChanged(previous, next) {
  if (!previous || !next) return false;
  return previous.kind !== next.kind || previous.className !== next.className;
}

function objectFlowDiagramDependencyFields(spec) {
  const fieldsByAlias = new Map();
  const add = (alias, field) => {
    const sourceAlias = String(alias || '').trim();
    const column = String(field || '').trim();
    if (!sourceAlias || !column) return;
    if (!fieldsByAlias.has(sourceAlias)) fieldsByAlias.set(sourceAlias, new Set());
    fieldsByAlias.get(sourceAlias).add(column);
  };
  const diagrams = spec && spec.result && Array.isArray(spec.result.diagrams) ? spec.result.diagrams : [];
  diagrams.forEach((diagram) => addResultDiagramDependencies(add, diagram));
  return fieldsByAlias;
}

function staleObjectFlowDiagramSourceErrors(currentSpec, nextFlow) {
  const previousFlow = objectFlowFromSpecServer(currentSpec || {});
  if (validateObjectFlow(previousFlow).length) return [];
  const previousStages = objectFlowStageManifest(previousFlow);
  if (!previousStages.size) return [];
  const nextStages = objectFlowStageManifest(nextFlow);
  const diagrams = currentSpec && currentSpec.result && Array.isArray(currentSpec.result.diagrams) ? currentSpec.result.diagrams : [];
  const dependencyFields = objectFlowDiagramDependencyFields(currentSpec);
  const errors = [];
  const schemaError = (path, alias, mapping) => {
    const previous = previousStages.get(alias);
    const next = nextStages.get(alias);
    if (!previous || !next) return;
    if (objectFlowStageKindOrClassChanged(previous, next)) {
      errors.push({ path, message: `Diagram ${mapping ? 'mapping ' : ''}source ${alias} changes its Object Flow kind or class. Remap the diagram before applying the flow.` });
      return;
    }
    const missingFields = Array.from(dependencyFields.get(alias) || []).filter((field) => previous.columns.includes(field) && !next.columns.includes(field));
    if (missingFields.length) {
      errors.push({ path, message: `Diagram ${mapping ? 'mapping ' : ''}source ${alias} no longer materializes required fields: ${missingFields.join(', ')}. Remap the diagram before applying the flow.` });
    }
  };
  const mappingFamilies = ['nodeMappings', 'edgeMappings', 'groupMappings', 'hierarchyMappings'];
  diagrams.forEach((diagram, diagramIndex) => {
    ['nodes', 'edges', 'groups', 'hierarchy'].forEach((kind) => {
      const alias = resultDiagramSourceName(diagram, kind);
      if (alias && previousStages.has(alias) && !nextStages.has(alias)) {
        errors.push({
          path: `$.result.diagrams[${diagramIndex}].source.${kind}`,
          message: `Diagram source ${alias} is removed by this Object Flow. Remap the diagram before applying the flow.`
        });
      } else if (alias) {
        schemaError(`$.result.diagrams[${diagramIndex}].source.${kind}`, alias, false);
      }
    });
    mappingFamilies.forEach((family) => {
      normalizeDiagramMappingList(diagram && diagram[family]).forEach((mapping, mappingIndex) => {
        const alias = diagramMappingSourceName(mapping);
        if (alias && previousStages.has(alias) && !nextStages.has(alias)) {
          errors.push({
            path: `$.result.diagrams[${diagramIndex}].${family}[${mappingIndex}]`,
            message: `Diagram mapping source ${alias} is removed by this Object Flow. Remap the diagram before applying the flow.`
          });
        } else if (alias) {
          schemaError(`$.result.diagrams[${diagramIndex}].${family}[${mappingIndex}]`, alias, true);
        }
      });
    });
  });
  return errors;
}

function validateDiagramImportV3Catalog(proposal, catalog, currentSpec = {}) {
  const errors = [];
  const classes = new Map((catalog && Array.isArray(catalog.classes) ? catalog.classes : []).map((item) => [String(item.name || ''), item]));
  const domains = new Map((catalog && Array.isArray(catalog.domains) ? catalog.domains : []).map((item) => [String(item.name || ''), item]));
  const classAttribute = (className, attributeName) => {
    const owner = classes.get(String(className || ''));
    return owner && Array.isArray(owner.attributes) ? owner.attributes.find((item) => String(item.name || '') === String(attributeName || '')) : null;
  };
  const flow = objectFlowFromSpecServer(currentSpec);
  const flowErrors = validateObjectFlow(flow);
  const stages = flowErrors.length ? [] : assistantObjectFlowDiagramStages(currentSpec, flow);
  const stageById = new Map(stages.map((stage) => [String(stage.id || ''), stage]));
  const validateClass = (className, path) => {
    if (className && !classes.has(String(className))) errors.push({ path, message: `CMDBuild class ${className} is not readable in the current catalog.` });
  };
  const validatePath = (startClass, path, basePath) => {
    let currentClass = String(startClass || '');
    for (const [index, hop] of (Array.isArray(path) ? path : []).entries()) {
      const hopPath = `${basePath}[${index}]`;
      if (hop.kind === 'reference') {
        const attribute = classAttribute(currentClass, hop.name);
        if (!attribute || !isReferenceAttribute(attribute)) errors.push({ path: `${hopPath}.name`, message: `Reference ${currentClass}.${hop.name} is not readable.` });
        if (hop.domain && !domains.has(String(hop.domain))) errors.push({ path: `${hopPath}.domain`, message: `CMDBuild domain ${hop.domain} backing reference ${currentClass}.${hop.name} is not readable.` });
        currentClass = String(hop.targetClass || attribute && (attribute.targetClass || attribute.targetType) || '');
      } else {
        const domain = domains.get(String(hop.name || ''));
        if (!domain) errors.push({ path: `${hopPath}.name`, message: `CMDBuild domain ${hop.name} is not readable.` });
        currentClass = String(hop.targetClass || currentClass);
      }
      validateClass(currentClass, `${hopPath}.targetClass`);
    }
    return currentClass;
  };
  const systemFields = new Set(['Class', '_id', 'Code', 'Description']);
  const validateFieldPath = (startClass, rawPath, basePath) => {
    const path = String(rawPath || '').trim();
    if (!path) {
      errors.push({ path: basePath, message: 'D2 placement filter requires a CMDBuild field.' });
      return false;
    }
    if (systemFields.has(path)) return true;
    let currentClass = String(startClass || '').trim();
    let rest = path;
    let depth = 0;
    while (rest) {
      if (!currentClass || !classes.has(currentClass)) {
        errors.push({ path: basePath, message: `CMDBuild class ${currentClass || '(empty)'} is not readable while resolving filter field ${path}.` });
        return false;
      }
      if (depth > ABSOLUTE_EXECUTION_LIMITS.maxTraversalDepth) {
        errors.push({ path: basePath, message: `Filter field ${path} exceeds the configured CMDBuild traversal depth.` });
        return false;
      }
      if (rest.startsWith('{')) {
        const match = rest.match(/^\{([^:}]+):([^}]+)\}(?:\.(.*))?$/);
        if (!match) {
          errors.push({ path: basePath, message: `Filter field ${path} has an invalid CMDBuild domain path.` });
          return false;
        }
        const domain = domains.get(String(match[1] || ''));
        const targetClass = String(match[2] || '').trim();
        if (!domain || !diagramImportCatalogDomainRelatedClasses(domain, currentClass, catalog).includes(targetClass) || !classes.has(targetClass)) {
          errors.push({ path: basePath, message: `CMDBuild domain path ${match[1]} from ${currentClass} to ${targetClass || '(empty)'} is not readable for filter field ${path}.` });
          return false;
        }
        currentClass = targetClass;
        rest = String(match[3] || '').trim();
        depth += 1;
        continue;
      }
      const dotIndex = rest.indexOf('.');
      const field = dotIndex === -1 ? rest : rest.slice(0, dotIndex);
      const attribute = classAttribute(currentClass, field);
      if (!attribute) {
        errors.push({ path: basePath, message: `CMDBuild attribute ${currentClass}.${field || '(empty)'} is not readable for filter field ${path}.` });
        return false;
      }
      if (dotIndex === -1) return true;
      if (!diagramImportCatalogReferenceAttribute(attribute)) {
        errors.push({ path: basePath, message: `CMDBuild attribute ${currentClass}.${field} is not a readable reference in filter field ${path}.` });
        return false;
      }
      currentClass = String(attribute.targetClass || attribute.targetType || '').trim();
      rest = rest.slice(dotIndex + 1);
      depth += 1;
    }
    errors.push({ path: basePath, message: `Filter field ${path} has no terminal CMDBuild attribute.` });
    return false;
  };
  const structureTree = proposal && proposal.structureTree && typeof proposal.structureTree === 'object' && !Array.isArray(proposal.structureTree) &&
    Number(proposal.structureTree.version || 0) === D2_IMPORT_STRUCTURE_TREE_VERSION && Array.isArray(proposal.structureTree.items)
    ? diagramImportStructureTree(proposal.structureTree, proposal && proposal.structure, proposal && proposal.roles)
    : null;
  if (!structureTree) {
    errors.push({ path: '$.structureTree', message: `D2 mapping must define a persisted structureTree version ${D2_IMPORT_STRUCTURE_TREE_VERSION}. Analyze the current D2 source again.` });
  }
  const structureItemById = new Map((structureTree && structureTree.items || []).map((item) => [String(item && item.id || ''), item]));
  const effectiveStageId = (item, visited = new Set()) => {
    const itemId = String(item && item.id || '');
    if (!item || visited.has(itemId)) return '';
    const role = (proposal && proposal.roles || []).find((candidate) => String(candidate && candidate.id || '') === String(item && item.roleId || '')) || {};
    const mapping = diagramImportStructureItemMapping(role, item.mapping || {}, itemId);
    if (String(mapping && mapping.materialization && mapping.materialization.kind || '') === 'stage') return String(mapping.materialization.stageId || '').trim();
    if (String(mapping && mapping.materialization && mapping.materialization.kind || '') !== 'parentCard') return '';
    return effectiveStageId(structureItemById.get(String(item.parentId || '')), new Set(visited).add(itemId));
  };
  const mappingsByRoleId = new Map();
  for (const [index, item] of (structureTree && structureTree.items || []).entries()) {
    const role = (proposal && proposal.roles || []).find((candidate) => String(candidate && candidate.id || '') === String(item && item.roleId || '')) || {};
    const mapping = diagramImportStructureItemMapping(role, item && item.mapping || {}, item && item.id || '');
    const roleMappings = mappingsByRoleId.get(String(role.id || '')) || [];
    roleMappings.push({ item, mapping, index });
    mappingsByRoleId.set(String(role.id || ''), roleMappings);
    const stageId = effectiveStageId(item);
    if (!stageId) continue;
    const sourcePath = `$.structureTree.items[${index}].mapping.materialization.stageId`;
    const stage = stageById.get(stageId);
    if (!stage) {
      errors.push({ path: sourcePath, message: `Object Flow result ${stageId} is not available in the current deterministic spec.` });
      continue;
    }
    const primary = mapping.primary || {};
    const available = new Set((stage.columns || []).map(String));
    const fields = uniqueStrings([primary.idAttribute].concat(primary.structuredFields || []).concat(diagramImportPrimaryTemplateFieldNames(primary.labelTemplate || '')))
      .map((field) => String(field).replace(/^primary\./, ''));
    for (const field of fields) {
      if (field && !available.has(field)) errors.push({ path: sourcePath, message: `Field ${field} is not materialized by Object Flow result ${stage.label || stage.id}.` });
    }
    const conditionSets = [
      { name: 'conditions', value: diagramImportPlacementFilters(mapping.conditions) },
      { name: 'hierarchyConditions', value: diagramImportPlacementFilters(mapping.hierarchyConditions) }
    ];
    const validateConditionField = (conditionStage, fieldName, fieldSource, fieldPath) => {
      const source = normalizeDiagramImportConditionCardSource(fieldSource);
      const field = String(fieldName || '').trim();
      if (!field) return;
      if (!source) {
        if (!(conditionStage.columns || []).map(String).includes(field)) validateFieldPath(conditionStage.className, field, fieldPath);
        return;
      }
      const sourceMatches = (Array.isArray(conditionStage.cardSources) ? conditionStage.cardSources : []).some((candidate) => (
        String(candidate && candidate.className || '') === source.className &&
        String(candidate && candidate.classColumn || '') === source.classColumn &&
        String(candidate && candidate.idColumn || '') === source.idColumn
      ));
      if (!sourceMatches) {
        errors.push({ path: fieldPath, message: `Filter source ${source.label || source.className} is not retained by Object Flow result ${conditionStage.label || conditionStage.id}.` });
        return;
      }
      const sourceColumns = new Set((conditionStage.columns || []).map(String));
      if (!sourceColumns.has(source.classColumn) || !sourceColumns.has(source.idColumn)) {
        errors.push({ path: fieldPath, message: `Filter source ${source.label || source.className} is missing its CMDBuild class or identifier columns in Object Flow result ${conditionStage.label || conditionStage.id}.` });
        return;
      }
      validateFieldPath(source.className, field, fieldPath);
    };
    for (const conditionSet of conditionSets) for (const [conditionIndex, condition] of conditionSet.value.rules.entries()) {
      const conditionPath = `$.structureTree.items[${index}].mapping.${conditionSet.name}.rules[${conditionIndex}]`;
      const sourceField = String(condition && condition.left && condition.left.column || '').trim();
      validateConditionField(stage, sourceField, condition && condition.left && condition.left.source, `${conditionPath}.left.column`);
      if (condition && condition.right && condition.right.kind === 'stage') {
        const comparisonStage = stageById.get(String(condition.right.stageId || ''));
        const comparisonField = String(condition.right.column || '').trim();
        if (comparisonStage) validateConditionField(comparisonStage, comparisonField, condition.right.source, `${conditionPath}.right.column`);
      }
    }
  }
  for (const [roleId, mappedItems] of mappingsByRoleId.entries()) {
    const role = (proposal.roles || []).find((candidate) => String(candidate && candidate.id || '') === roleId) || {};
    for (const { item, mapping, index } of mappedItems) {
      const primary = mapping.primary || {};
      const basePath = `$.structureTree.items[${index}].mapping`;
      validateClass(primary.className, `${basePath}.primary.className`);
      if (primary.className) {
        for (const field of uniqueStrings([primary.idAttribute].concat(primary.structuredFields || []).concat(diagramImportPrimaryTemplateFieldNames(primary.labelTemplate || '')))) {
          const plain = String(field || '').replace(/^primary\./, '');
          if (plain && !['_id', 'Code', 'Description', 'Class'].includes(plain) && !classAttribute(primary.className, plain)) {
            errors.push({ path: `${basePath}.primary`, message: `Attribute ${primary.className}.${plain} is not readable.` });
          }
        }
      }
      for (const [relatedIndex, related] of (mapping.related || []).entries()) {
        const relatedPath = `${basePath}.related[${relatedIndex}]`;
        if (related && related.legacyTraversal) {
          errors.push({ path: relatedPath, message: 'Additional diagram data must use a named Object Flow result; CMDB traversal belongs to Object Flow.' });
          continue;
        }
        const relatedStage = stageById.get(String(related && related.stageId || ''));
        const primaryStageId = effectiveStageId(item);
        const primaryStage = stageById.get(primaryStageId);
        const correlation = diagramImportPlacementFilters(related && related.conditions);
        if (!relatedStage) {
          errors.push({ path: `${relatedPath}.stageId`, message: 'Additional diagram data must select a materialized Object Flow result.' });
          continue;
        }
        const relatedFields = new Set((relatedStage.columns || []).map(String));
        for (const field of uniqueStrings(related.structuredFields || [])) {
          if (field && !relatedFields.has(field)) {
            errors.push({ path: `${relatedPath}.structuredFields`, message: `Field ${field} is not materialized by Object Flow result ${relatedStage.label || relatedStage.id}.` });
          }
        }
        if (!primaryStageId || !primaryStage) {
          errors.push({ path: `${relatedPath}.conditions`, message: 'Additional Object Flow data requires a materialized primary result for explicit correlation.' });
        }
        if (!correlation.rules.length) {
          errors.push({ path: `${relatedPath}.conditions`, message: 'Additional Object Flow data requires at least one explicit correlation with the primary result.' });
        }
        const primaryFields = new Set((primaryStage && primaryStage.columns || []).map(String));
        for (const [conditionIndex, condition] of correlation.rules.entries()) {
          const conditionPath = `${relatedPath}.conditions.rules[${conditionIndex}]`;
          const sourceField = String(condition && condition.left && condition.left.column || '').trim();
          const primaryField = String(condition && condition.right && condition.right.column || '').trim();
          if (!sourceField || !relatedFields.has(sourceField)) {
            errors.push({ path: `${conditionPath}.left.column`, message: `Correlation field must be materialized by Object Flow result ${relatedStage.label || relatedStage.id}.` });
          }
          if (!condition.right || String(condition.right.kind || '') !== 'stage' || String(condition.right.stageId || '') !== primaryStageId || !primaryField || !primaryFields.has(primaryField)) {
            errors.push({ path: `${conditionPath}.right`, message: 'Additional Object Flow data must explicitly compare a field with this primary result.' });
          }
          if (!DIAGRAM_IMPORT_CONDITION_OPERATORS.has(String(condition.operator || 'equals'))) {
            errors.push({ path: `${conditionPath}.operator`, message: 'Additional Object Flow data uses an unsupported matching operator.' });
          }
        }
      }
      const conditions = diagramImportPlacementFilters(mapping.conditions);
      if (conditions.rules.length && String(mapping && mapping.materialization && mapping.materialization.kind || '') === 'structural') {
        errors.push({ path: `${basePath}.conditions`, message: 'A structural D2 container has no Object Flow source and cannot define data filters.' });
      }
    }
  }
  const roleById = new Map((proposal.roles || []).map((role) => [String(role.id), role]));
  for (const [index, rule] of (proposal.relationRules || []).entries()) {
    const parent = roleById.get(String(rule.parentRoleId || ''));
    const child = roleById.get(String(rule.childRoleId || ''));
    errors.push(...diagramImportLabelTemplateSyntaxErrors(
      String(rule && rule.labelTemplate || ''),
      `$.relationRules[${index}].labelTemplate`
    ));
    if (!['relationCard', 'networkEndpoints', 'deterministicEndpoints'].includes(String(rule.mode || ''))) {
      errors.push({ path: `$.relationRules[${index}].mode`, message: 'D2 connection must use a materialized Object Flow result; CMDB relation paths are configured in Object Flow.' });
      continue;
    }
    const stage = stageById.get(String(rule.sourceStageId || ''));
    if (!stage) {
      errors.push({ path: `$.relationRules[${index}].sourceStageId`, message: 'Connection source must reference a materialized Object Flow result.' });
      continue;
    }
    const available = new Set(Array.isArray(stage.columns) ? stage.columns.map(String) : []);
    const requiredFields = ['sourceField', 'targetField', 'labelField'];
    for (const field of uniqueStrings(requiredFields.concat(diagramTemplateFieldNames(rule.labelTemplate || '')))) {
      const value = String(requiredFields.includes(field) ? rule[field] || '' : field).trim();
      if (value && !available.has(value)) {
        errors.push({
          path: requiredFields.includes(field) ? `$.relationRules[${index}].${field}` : `$.relationRules[${index}].labelTemplate`,
          message: `Connection field ${value} is not materialized by Object Flow result ${stage.label || stage.id}.`
        });
      }
    }
  }
  const connectionRulesByStage = new Map();
  for (const [index, rule] of (proposal.relationRules || []).entries()) {
    if (!['relationCard', 'networkEndpoints', 'deterministicEndpoints'].includes(String(rule && rule.mode || ''))) continue;
    const stageId = String(rule && rule.sourceStageId || '').trim();
    if (!stageId) continue;
    if (!connectionRulesByStage.has(stageId)) connectionRulesByStage.set(stageId, []);
    connectionRulesByStage.get(stageId).push({ index, rule });
  }
  for (const [stageId, entries] of connectionRulesByStage.entries()) {
    const classKeys = uniqueStrings(entries.map(({ rule }) => String(rule && (rule.d2ClassKey || rule.d2ElementKey) || '')).filter(Boolean));
    if (classKeys.length < 2) continue;
    for (const { index, rule } of entries) {
      errors.push({
        path: `$.relationRules[${index}].sourceStageId`,
        code: 'diagram_connection_result_not_dedicated',
        message: `Connection source ${stageId} is shared by D2 relation classes ${classKeys.join(', ')}. Create a separate named Object Flow result for ${String(rule && (rule.d2ClassKey || rule.d2ElementKey) || '')}.`
      });
    }
  }
  return errors;
}

function diagramImportCatalogPathSignature(path) {
  return (Array.isArray(path) ? path : []).map((hop) => [
    String(hop && hop.kind || 'domain'),
    String(hop && hop.name || ''),
    String(hop && hop.domain || ''),
    String(hop && hop.targetClass || ''),
    String(hop && hop.direction || 'both')
  ].join(':')).join('>');
}

function diagramImportCatalogValidationDiagnostics(errors, proposal) {
  const rules = Array.isArray(proposal && proposal.relationRules) ? proposal.relationRules : [];
  return (Array.isArray(errors) ? errors : []).map((item) => {
    const match = /^\$\.relationRules\[(\d+)\]/.exec(String(item && item.path || ''));
    const rule = match ? rules[Number(match[1])] : null;
    const label = String(rule && rule.d2Label || rule && rule.d2ElementKey || 'D2 mapping');
    return {
      ...item,
      family: 'catalog',
      displayName: label,
      guidance: rule
        ? `Связь «${label}» должна выбрать отдельный именованный результат Object Flow и его поля endpoint.`
        : 'Выбранный результат Object Flow или его поля больше не доступны. Проверьте детерминированный поток и mapping.'
    };
  });
}

function diagramImportCatalogStrings(values) {
  return uniqueStrings((Array.isArray(values) ? values : [values]).map((value) => String(value || '').trim()).filter(Boolean));
}

function diagramImportCatalogReferenceAttribute(attribute) {
  return Boolean(attribute && (attribute.type === 'reference' || attribute.targetClass || attribute.targetType || attribute.domain));
}

function diagramImportCatalogClassParents(catalog) {
  return new Map((catalog && Array.isArray(catalog.classes) ? catalog.classes : [])
    .map((item) => [String(item && item.name || '').trim().toLowerCase(), String(item && item.parent || '').trim()])
    .filter(([name]) => name));
}

function diagramImportCatalogClassInheritsFrom(className, endpointClass, classParents) {
  const endpoint = String(endpointClass || '').trim().toLowerCase();
  const seen = new Set();
  let current = String(className || '').trim();
  while (current && !seen.has(current.toLowerCase())) {
    if (current.toLowerCase() === endpoint) return true;
    seen.add(current.toLowerCase());
    current = classParents.get(current.toLowerCase()) || '';
  }
  return false;
}

function diagramImportCatalogDomainEndpointAllows(domain, side, className, classParents) {
  const endpoints = diagramImportCatalogStrings([domain && domain[side]].concat(domain && domain[`${side}s`] || []));
  const disabledKey = `disabled${side[0].toUpperCase()}${side.slice(1)}Descendants`;
  const disabled = new Set(diagramImportCatalogStrings(domain && domain[disabledKey] || []).map((item) => item.toLowerCase()));
  const candidate = String(className || '').trim();
  return Boolean(candidate) && !disabled.has(candidate.toLowerCase()) && endpoints.some((endpoint) => (
    diagramImportCatalogClassInheritsFrom(candidate, endpoint, classParents)
  ));
}

function diagramImportCatalogDomainEndpointClasses(domain, side, catalog, classParents) {
  const endpoints = diagramImportCatalogStrings([domain && domain[side]].concat(domain && domain[`${side}s`] || []));
  const classes = Array.isArray(catalog && catalog.classes) ? catalog.classes : [];
  const result = endpoints.slice();
  for (const item of classes) {
    const className = String(item && item.name || '').trim();
    if (className && diagramImportCatalogDomainEndpointAllows(domain, side, className, classParents)) result.push(className);
  }
  return diagramImportCatalogStrings(result);
}

function diagramImportCatalogDomainRelatedClasses(domain, className, catalog) {
  const classParents = diagramImportCatalogClassParents(catalog);
  const related = [];
  if (diagramImportCatalogDomainEndpointAllows(domain, 'source', className, classParents)) {
    related.push(...diagramImportCatalogDomainEndpointClasses(domain, 'destination', catalog, classParents));
  }
  if (diagramImportCatalogDomainEndpointAllows(domain, 'destination', className, classParents)) {
    related.push(...diagramImportCatalogDomainEndpointClasses(domain, 'source', catalog, classParents));
  }
  const current = String(className || '').trim().toLowerCase();
  return diagramImportCatalogStrings(related).filter((name) => name.toLowerCase() !== current);
}

function diagramImportCatalogDomainDirection(domain, className, catalog) {
  const classParents = diagramImportCatalogClassParents(catalog);
  if (diagramImportCatalogDomainEndpointAllows(domain, 'source', className, classParents)) return 'direct';
  if (diagramImportCatalogDomainEndpointAllows(domain, 'destination', className, classParents)) return 'inverse';
  return 'both';
}

function diagramImportCatalogPathCandidates(catalog, sourceClass, targetClass, maxDepth = 1, maxCandidates = 48) {
  const classes = new Map((catalog && Array.isArray(catalog.classes) ? catalog.classes : []).map((item) => [String(item && item.name || ''), item]));
  const domains = Array.isArray(catalog && catalog.domains) ? catalog.domains : [];
  const source = String(sourceClass || '').trim();
  const target = String(targetClass || '').trim();
  const depth = Math.max(1, Math.min(5, Number(maxDepth) || 1));
  if (!source || !target || !classes.has(source) || !classes.has(target)) return [];
  const results = [];
  const signatures = new Set();
  const visit = (currentClass, path, visited) => {
    if (results.length >= maxCandidates || path.length >= depth) return;
    const owner = classes.get(currentClass);
    if (!owner) return;
    const add = (hop) => {
      const nextPath = path.concat([hop]);
      if (hop.targetClass === target) {
        const signature = diagramImportCatalogPathSignature(nextPath);
        if (!signatures.has(signature)) {
          signatures.add(signature);
          results.push({
            id: diagramImportStableId('catalog_path', `${source}:${target}:${signature}`),
            sourceClass: source,
            targetClass: target,
            path: nextPath,
            label: nextPath.map((item) => item.kind === 'reference'
              ? `${item.name} -> ${item.targetClass}`
              : `{${item.name}:${item.targetClass}} ${item.direction}`).join(' > ')
          });
        }
        return;
      }
      if (!visited.has(hop.targetClass)) {
        const nextVisited = new Set(visited);
        nextVisited.add(hop.targetClass);
        visit(hop.targetClass, nextPath, nextVisited);
      }
    };
    for (const attribute of Array.isArray(owner.attributes) ? owner.attributes : []) {
      if (!diagramImportCatalogReferenceAttribute(attribute)) continue;
      const nextClass = String(attribute.targetClass || attribute.targetType || '').trim();
      if (!nextClass || !classes.has(nextClass)) continue;
      add({
        kind: 'reference',
        name: String(attribute.name || ''),
        domain: String(attribute.domain || ''),
        targetClass: nextClass,
        direction: String(attribute.direction || 'direct')
      });
    }
    for (const domain of domains) {
      for (const nextClass of diagramImportCatalogDomainRelatedClasses(domain, currentClass, catalog)) {
        if (!classes.has(nextClass)) continue;
        add({
          kind: 'domain',
          name: String(domain.name || ''),
          targetClass: nextClass,
          direction: diagramImportCatalogDomainDirection(domain, currentClass, catalog)
        });
      }
    }
  };
  visit(source, [], new Set([source]));
  return results;
}

function applyDiagramImportProposal(currentSpec, proposal, roleOverrides = [], relationRules, structureTree) {
  const sourceSpec = cloneJsonValueServer(currentSpec, {});
  if (!proposal || proposal.version !== 3) {
    const error = new Error('D2 import proposal version is no longer supported. Analyze the D2 source again.');
    error.code = 'diagram_import_proposal_version';
    error.statusCode = 409;
    throw error;
  }
  assertDiagramImportProposalDeterministicSpec(proposal, sourceSpec, 'applying it');
  const reviewed = diagramImportV3WithOverrides(proposal, roleOverrides, relationRules, structureTree, sourceSpec);
  const appliedFlow = objectFlowFromSpecServer(sourceSpec);
  const stageById = new Map(assistantObjectFlowDiagramStages(sourceSpec, appliedFlow).map((stage) => [String(stage.id || ''), stage]));
  reviewed.unresolved = diagramImportV3Unresolved(reviewed.roles, reviewed.relationRules, reviewed.structureTree, sourceSpec, reviewed.structure);
  if (reviewed.unresolved.length) {
    const topologyUnresolved = reviewed.unresolved.filter((item) => item && item.family === 'topology');
    const error = new Error(topologyUnresolved.length
      ? 'D2 mapping is incomplete: map every dynamic connection and hierarchy to a named Object Flow result before applying.'
      : 'D2 class mapping has unresolved fields.');
    error.code = topologyUnresolved.length ? 'diagram_import_topology_unresolved' : 'diagram_import_unresolved';
    error.statusCode = 422;
    error.details = reviewed.unresolved;
    throw error;
  }
  const roleById = new Map(reviewed.roles.map((role) => [String(role.id), role]));
  const compiledTree = diagramImportCompileStructureTree(reviewed.structureTree, reviewed.roles, stageById);
  const compiledRules = (reviewed.relationRules || []).flatMap((rule) => diagramImportCompileRelationRule(rule, roleById, compiledTree.compiledByItemId, stageById));
  // D2 source often contains several sample arrows of the same visual type.
  // One dynamic relation-card stage must materialize its CMDB rows once, not
  // once per sample arrow, otherwise every ACL row is duplicated in runtime.
  const distinctCompiledRules = [];
  const compiledRuleKeys = new Set();
  for (const compiled of compiledRules) {
    const rule = compiled.rule || {};
    const key = String(rule.mode || '') === 'networkEndpoints'
      ? [
        'networkEndpoints', String(rule.d2ClassKey || rule.d2ElementKey || rule.id || ''), compiled.alias, compiled.rootIdField, compiled.targetIdField,
        compiled.labelField, rule.parentRoleId, rule.childRoleId
      ].join(':')
      : `rule:${String(rule.id || '')}:${String(compiled.sourceStructureItemId || '')}`;
    if (compiledRuleKeys.has(key)) continue;
    compiledRuleKeys.add(key);
    distinctCompiledRules.push(compiled);
  }
  const managedSteps = compiledTree.steps.concat(distinctCompiledRules.flatMap((item) => item.steps));
  sourceSpec.steps = (Array.isArray(sourceSpec.steps) ? sourceSpec.steps : []).filter((step) => step && step.managedBy !== 'd2ImportV3').concat(managedSteps);
  sourceSpec.result = sourceSpec.result && typeof sourceSpec.result === 'object' && !Array.isArray(sourceSpec.result) ? sourceSpec.result : {};
  const diagrams = Array.isArray(sourceSpec.result.diagrams) ? sourceSpec.result.diagrams.slice() : [];
  const diagramIndex = diagrams.findIndex((item) => item && (item.id === reviewed.diagramId || (!item.id && item.name)));
  const previous = diagramIndex >= 0 ? diagrams[diagramIndex] : {};
  const nodeMappings = [];
  const groupMappings = [];
  for (const item of compiledTree.runtimeMappings) {
    if (item.family === 'groupMappings') groupMappings.push(item.mapping);
    else nodeMappings.push(item.mapping);
  }
  const { edgeMappings, hierarchyMappings, classRelationRules } = diagramImportRuntimeRelationMappings(
    distinctCompiledRules,
    roleById,
    reviewed.templateGrammar
  );
  assertDiagramImportRuntimeMappingsContract({
    nodeMappings,
    groupMappings,
    edgeMappings,
    hierarchyMappings
  }, reviewed.templateGrammar);
  const diagram = {
    ...cloneJsonValueServer(previous, {}),
    id: reviewed.diagramId,
    name: String(previous.name || reviewed.template && (reviewed.template.name || reviewed.template.title) || 'topology').trim() || 'topology',
    title: String(reviewed.template && reviewed.template.title || previous.title || 'Topology').trim() || 'Topology',
    type: 'topology',
    nodeMappings,
    groupMappings,
    edgeMappings,
    hierarchyMappings,
    classRelationRules,
    templateGrammar: cloneJsonValueServer(reviewed.templateGrammar, {}),
    structureTree: cloneJsonValueServer(compiledTree.tree, {}),
    authoring: diagramImportAuthoringFromReviewed(previous, reviewed, compiledTree.tree)
  };
  if (diagramIndex >= 0) diagrams[diagramIndex] = diagram;
  else diagrams.push(diagram);
  sourceSpec.result.diagrams = diagrams;
  synchronizeD2Authoring(sourceSpec, diagram.authoring.d2Import);
  diagram.authoring.d2Import = withDiagramImportMappingInputRevision(sourceSpec, diagram.authoring.d2Import);
  diagram.authoring.d2Import.mappingValidation = {
    version: 1,
    status: 'valid',
    signature: signDiagramImportMappingValidation(diagram.authoring.d2Import)
  };
  const errors = validateTemplateSpecForStorage(sourceSpec);
  if (errors.length) {
    const error = new Error('D2 class mapping produced an invalid deterministic template spec.');
    error.code = 'diagram_import_invalid_spec';
    error.statusCode = 422;
    error.details = errors;
    throw error;
  }
  return sourceSpec;
}

function diagramImportAuthoringFromReviewed(previousDiagram, reviewed, structureTree) {
  return {
    ...(previousDiagram && previousDiagram.authoring && typeof previousDiagram.authoring === 'object' ? previousDiagram.authoring : {}),
    d2Import: {
      version: 3,
      semanticModelRevision: D2_IMPORT_SEMANTIC_MODEL_REVISION,
      proposalId: reviewed.proposalId,
      diagramId: reviewed.diagramId,
      sourceHash: reviewed.source && reviewed.source.hash || '',
      structureHash: reviewed.source && reviewed.source.structureHash || '',
      mappingContractHash: reviewed.source && reviewed.source.mappingContractHash || '',
      parser: reviewed.source && reviewed.source.parser || '',
      source: String(reviewed.sourceText || ''),
      importedAt: new Date().toISOString(),
      template: cloneJsonValueServer(reviewed.template, {}),
      structure: cloneJsonValueServer(reviewed.structure, {}),
      classes: cloneJsonValueServer(reviewed.classes, []),
      roles: reviewed.roles.map((role) => ({
        id: role.id,
        kind: role.kind,
        key: role.key,
        label: role.label,
        notes: truncateText(String(role.notes || ''), 8000),
        semanticModelRevision: D2_IMPORT_SEMANTIC_MODEL_REVISION,
        visualKind: diagramImportRoleVisualKind(role),
        labelTemplate: String(role.labelTemplate || role.label || '')
      })),
      relationRules: cloneJsonValueServer(reviewed.relationRules, []),
      structureTree: cloneJsonValueServer(structureTree, {}),
      templateGrammar: cloneJsonValueServer(reviewed.templateGrammar, {})
    }
  };
}

// Assistant Apply may preserve an incomplete deterministic mapping as local
// authoring state. Preview recompiles only independently valid placements from
// this structure; runtime and publication remain fail-closed until a full
// mapping passes applyDiagramImportProposal above.
function applyPartialDiagramImportProposal(currentSpec, proposal, roleOverrides = [], relationRules, structureTree) {
  const sourceSpec = cloneJsonValueServer(currentSpec, {});
  if (!proposal || proposal.version !== 3) {
    const error = new Error('D2 import proposal version is no longer supported. Analyze the D2 source again.');
    error.code = 'diagram_import_proposal_version';
    error.statusCode = 409;
    throw error;
  }
  assertDiagramImportProposalDeterministicSpec(proposal, sourceSpec, 'applying it');
  const reviewed = diagramImportV3WithOverrides(proposal, roleOverrides, relationRules, structureTree, sourceSpec);
  reviewed.unresolved = diagramImportV3Unresolved(reviewed.roles, reviewed.relationRules, reviewed.structureTree, sourceSpec, reviewed.structure);
  const diagrams = Array.isArray(sourceSpec.result && sourceSpec.result.diagrams) ? sourceSpec.result.diagrams.slice() : [];
  const diagramIndex = diagrams.findIndex((item) => item && (item.id === reviewed.diagramId || (!item.id && item.name)));
  const previous = diagramIndex >= 0 ? diagrams[diagramIndex] : {};
  const diagram = {
    ...cloneJsonValueServer(previous, {}),
    id: reviewed.diagramId,
    name: String(previous.name || reviewed.template && (reviewed.template.name || reviewed.template.title) || 'topology').trim() || 'topology',
    title: String(reviewed.template && reviewed.template.title || previous.title || 'Topology').trim() || 'Topology',
    type: 'topology',
    // Remove previous executable D2 output. A new preview must compile only
    // the valid subset of the current reviewed tree, never stale mappings.
    nodeMappings: [],
    groupMappings: [],
    edgeMappings: [],
    hierarchyMappings: [],
    classRelationRules: [],
    templateGrammar: cloneJsonValueServer(reviewed.templateGrammar, {}),
    structureTree: cloneJsonValueServer(reviewed.structureTree, {}),
    authoring: diagramImportAuthoringFromReviewed(previous, reviewed, reviewed.structureTree)
  };
  if (diagramIndex >= 0) diagrams[diagramIndex] = diagram;
  else diagrams.push(diagram);
  sourceSpec.steps = (Array.isArray(sourceSpec.steps) ? sourceSpec.steps : []).filter((step) => step && step.managedBy !== 'd2ImportV3');
  sourceSpec.result = sourceSpec.result && typeof sourceSpec.result === 'object' && !Array.isArray(sourceSpec.result) ? sourceSpec.result : {};
  sourceSpec.result.diagrams = diagrams;
  synchronizeD2Authoring(sourceSpec, diagram.authoring.d2Import);
  diagram.authoring.d2Import.mappingValidation = {
    version: 1,
    status: 'needsValidation',
    reasons: ['partialMapping']
  };
  delete diagram.authoring.d2Import.mappingInputRevision;
  const errors = validateTemplateSpecForStorage(sourceSpec);
  if (errors.length) {
    const error = new Error('D2 partial mapping produced an invalid authoring template spec.');
    error.code = 'diagram_import_partial_invalid_spec';
    error.statusCode = 422;
    error.details = errors;
    throw error;
  }
  let omissions = [];
  let repairs = [];
  try {
    const previewPlan = draftDiagramPreviewMappingPlan(sourceSpec);
    omissions = previewPlan.omissions;
    repairs = previewPlan.repairs;
  } catch (error) {
    omissions = [{
      kind: 'mapping',
      message: 'The valid subset could not be compiled for preview. Correct the listed D2 mapping fields in Diagram Editor.'
    }];
  }
  return { spec: sourceSpec, reviewed, omissions, repairs };
}

function synchronizeD2Authoring(spec, imported) {
  if (!spec || typeof spec !== 'object' || Array.isArray(spec) || !imported || typeof imported !== 'object') return;
  const authoring = normalizeTemplateAuthoring(spec.authoring) || {
    version: 1,
    assistant: { objectFlowIntent: { context: '', blocks: [] }, diagramInterpretPrompt: '', diagramMappingPrompt: '' },
    d2: { source: '', sourceHash: '' }
  };
  const source = String(imported.source || '');
  spec.authoring = {
    ...authoring,
    d2: {
      source,
      sourceHash: source ? sha256Hex(source) : ''
    }
  };
  delete spec.assistantDraft;
}

function appliedDiagramImportProposalError(message, code, details = []) {
  const error = new Error(message);
  error.code = code;
  error.statusCode = 409;
  error.details = details;
  return error;
}

// Rebuild a server-owned editable model from an already accepted D2 mapping.
// The browser can submit mapping overrides, but never a replacement source or grammar.
async function appliedDiagramImportProposalFromSpec(currentSpec) {
  const sourceSpec = cloneJsonValueServer(currentSpec, {});
  const diagrams = Array.isArray(sourceSpec && sourceSpec.result && sourceSpec.result.diagrams) ? sourceSpec.result.diagrams : [];
  const diagram = diagrams.find((item) => item && item.authoring && item.authoring.d2Import && item.authoring.d2Import.version === 3);
  const imported = diagram && diagram.authoring && diagram.authoring.d2Import;
  if (!imported) {
    throw appliedDiagramImportProposalError('The current draft has no applied D2 mapping. Analyze and apply the D2 source first.', 'diagram_import_mapping_missing');
  }
  if (!imported.structureTree || Number(imported.structureTree.version || 0) !== D2_IMPORT_STRUCTURE_TREE_VERSION || !Array.isArray(imported.structureTree.items)) {
    throw appliedDiagramImportProposalError(
      'The applied D2 mapping uses the retired placement model. Analyze and apply the current D2 source again.',
      'diagram_import_structure_tree_required'
    );
  }
  if (Number(imported.semanticModelRevision || 0) !== D2_IMPORT_SEMANTIC_MODEL_REVISION) {
    throw appliedDiagramImportProposalError(
      'The applied D2 mapping uses an unsupported semantic model revision. Analyze and apply the current D2 source again.',
      'diagram_import_semantic_model_revision_required'
    );
  }
  if (diagramImportStoredMaterializationIssues(imported).length) {
    throw appliedDiagramImportProposalError(
      'The applied D2 mapping has placements without an explicit materialization. Open Diagram Editor, choose the Object Flow source for every dynamic placement, and save the template.',
      'diagram_import_materialization_required'
    );
  }
  const sourceText = String(imported.source || '');
  if (!sourceText.trim()) {
    throw appliedDiagramImportProposalError('The applied D2 mapping has no source. Analyze and apply the D2 source again.', 'diagram_import_source_missing');
  }
  const identity = await d2SourceStructureIdentity(sourceText);
  if (!identity.ok) {
    const error = appliedDiagramImportProposalError(identity.error || 'The applied D2 source is invalid. Analyze it again.', 'diagram_import_source_invalid');
    error.statusCode = 422;
    throw error;
  }
  if (String(imported.sourceHash || '') !== String(identity.sourceHash || '') ||
    String(imported.structureHash || '') !== String(identity.structureHash || '') ||
    String(imported.mappingContractHash || '') !== String(identity.mappingContractHash || '')) {
    throw appliedDiagramImportProposalError('The applied D2 source no longer matches its deterministic mapping. Analyze and apply the current source again.', 'diagram_import_source_changed');
  }

  const storedRoles = Array.isArray(imported.roles) ? imported.roles : [];
  const storedRoleById = new Map(storedRoles.map((role) => [String(role && role.id || ''), role]).filter(([id]) => id));
  const canonicalRoles = diagramImportClassRoleDefinitions(identity.ir);
  const canonicalRoleIds = new Set(canonicalRoles.map((role) => String(role && role.id || '')));
  const missingRoles = canonicalRoles.filter((role) => !storedRoleById.has(String(role && role.id || ''))).map((role) => String(role && (role.key || role.id) || '')).filter(Boolean);
  const removedRoles = storedRoles.filter((role) => !canonicalRoleIds.has(String(role && role.id || ''))).map((role) => String(role && (role.key || role.id) || '')).filter(Boolean);
  if (missingRoles.length || removedRoles.length) {
    throw appliedDiagramImportProposalError(
      'The applied D2 role set no longer matches the saved source. Analyze and apply the current source again.',
      'diagram_import_role_structure_changed',
      [{ missingRoles, removedRoles }]
    );
  }

  const roles = canonicalRoles.map((role) => {
    const stored = storedRoleById.get(String(role.id)) || {};
    const modeled = { ...role, ...stored };
    return {
      ...role,
      label: String(stored.label || role.label || role.key || ''),
      notes: String(stored.notes !== undefined ? stored.notes : role.notes || ''),
      visualKind: diagramImportRoleVisualKind(modeled),
      labelTemplate: String(stored.labelTemplate || role.labelTemplate || '')
    };
  });
  const proposal = {
    version: 3,
    semanticModelRevision: Number(imported.semanticModelRevision || D2_IMPORT_SEMANTIC_MODEL_REVISION),
    proposalId: String(imported.proposalId || ''),
    createdAt: Date.now(),
    deterministicSpecHash: diagramImportDeterministicSpecHash(sourceSpec),
    source: cloneJsonValueServer(identity.ir.source, {}),
    sourceText,
    template: cloneJsonValueServer(identity.ir.template, {}),
    structure: cloneJsonValueServer(identity.ir.elements, {}),
    classes: cloneJsonValueServer(identity.ir.classes, []),
    roles,
    relationRules: cloneJsonValueServer(imported.relationRules, []),
    structureTree: cloneJsonValueServer(imported.structureTree, {}),
    templateGrammar: cloneJsonValueServer(imported.templateGrammar, {}),
    diagramId: String(imported.diagramId || diagram && diagram.id || ''),
    warnings: [],
    unresolved: []
  };
  const roleOverrides = roles.map((role) => ({
    id: role.id,
    visualKind: diagramImportRoleVisualKind(role),
    labelTemplate: String(role.labelTemplate || '')
  }));
  return diagramImportV3WithOverrides(proposal, roleOverrides, proposal.relationRules, proposal.structureTree, sourceSpec);
}

function diagramImportCurrentInputRecompileRequired(spec) {
  const found = diagramImportForSpec(spec || {});
  const validation = found && found.imported && found.imported.mappingValidation && typeof found.imported.mappingValidation === 'object'
    ? found.imported.mappingValidation
    : {};
  const status = String(validation.status || '');
  const reasons = uniqueStrings(Array.isArray(validation.reasons) ? validation.reasons.map(String) : []);
  return status === 'needsValidation' || (status === 'needsReview' && reasons.length === 1 && reasons[0] === 'inputRevision');
}

async function recompileDiagramImportForCurrentInput(spec) {
  if (!diagramImportCurrentInputRecompileRequired(spec)) {
    return { spec, recompiled: false, error: null };
  }
  try {
    const proposal = await appliedDiagramImportProposalFromSpec(spec);
    return {
      spec: applyDiagramImportProposal(spec, proposal, [], proposal.relationRules, proposal.structureTree),
      recompiled: true,
      error: null
    };
  } catch (error) {
    return { spec, recompiled: false, error };
  }
}

async function proposalWithCompatibleD2Source(proposal, source) {
  const identity = await d2SourceStructureIdentity(source);
  if (!identity.ok) {
    const error = new Error(identity.error || 'D2 source is invalid.');
    error.code = 'diagram_import_source_invalid';
    error.statusCode = 422;
    throw error;
  }
  const expectedStructureHash = String(proposal && proposal.source && proposal.source.structureHash || '').trim();
  if (!expectedStructureHash || identity.structureHash !== expectedStructureHash) {
    const error = new Error('D2 source changed structurally after analysis. Analyze and map it again.');
    error.code = 'diagram_import_source_changed';
    error.statusCode = 409;
    throw error;
  }
  const expectedMappingContractHash = String(proposal && proposal.source && proposal.source.mappingContractHash || '').trim();
  if (!expectedMappingContractHash || identity.mappingContractHash !== expectedMappingContractHash) {
    const error = new Error('D2 mapping contract changed after analysis. Analyze and map the current source again.');
    error.code = 'diagram_import_mapping_contract_changed';
    error.statusCode = 409;
    throw error;
  }
  return {
    ...cloneJsonValueServer(proposal, {}),
    source: cloneJsonValueServer(identity.ir.source, {}),
    sourceText: String(source || ''),
    template: cloneJsonValueServer(identity.ir.template, {}),
    structure: cloneJsonValueServer(identity.ir.elements, {}),
    classes: cloneJsonValueServer(identity.ir.classes, [])
  };
}

async function refreshDiagramImportSource(currentSpec, source) {
  const next = cloneJsonValueServer(currentSpec, {});
  const diagrams = next && next.result && Array.isArray(next.result.diagrams) ? next.result.diagrams : [];
  const diagram = diagrams.find((item) => item && item.authoring && item.authoring.d2Import && item.authoring.d2Import.version === 3);
  const imported = diagram && diagram.authoring && diagram.authoring.d2Import;
  if (!imported) {
    const error = new Error('The current draft has no applied D2 mapping to refresh.');
    error.code = 'diagram_import_mapping_missing';
    error.statusCode = 409;
    throw error;
  }
  const appliedStructureHash = String(imported.structureHash || '').trim();
  if (!appliedStructureHash) {
    const error = new Error('The applied D2 mapping predates structural source verification. Analyze and apply it again.');
    error.code = 'diagram_import_structure_hash_missing';
    error.statusCode = 409;
    throw error;
  }
  const appliedMappingContractHash = String(imported.mappingContractHash || '').trim();
  if (!appliedMappingContractHash) {
    const error = new Error('The applied D2 mapping predates mapping-contract verification. Analyze and apply it again.');
    error.code = 'diagram_import_mapping_contract_missing';
    error.statusCode = 409;
    throw error;
  }
  const identity = await d2SourceStructureIdentity(source);
  if (!identity.ok) {
    const error = new Error(identity.error || 'D2 source is invalid.');
    error.code = 'diagram_import_source_invalid';
    error.statusCode = 422;
    throw error;
  }
  if (identity.structureHash !== appliedStructureHash) {
    const error = new Error('D2 source changed structurally after mapping. Analyze and map it again.');
    error.code = 'diagram_import_source_changed';
    error.statusCode = 409;
    throw error;
  }
  if (identity.mappingContractHash !== appliedMappingContractHash) {
    const error = new Error('D2 mapping contract changed after mapping. Analyze and map it again.');
    error.code = 'diagram_import_mapping_contract_changed';
    error.statusCode = 409;
    throw error;
  }
  // Refreshing presentation-only D2 source is an explicit source action, but
  // it must not silently accept a changed Assistant prompt or Object Flow
  // contract. Those inputs need a normal mapping reapply.
  const mappingWasValidated = diagramImportMappingValidationIsCurrent(imported) &&
    diagramImportMappingInputRevisionStatus(next, imported).current;
  diagram.authoring.d2Import = {
    ...imported,
    sourceHash: identity.sourceHash,
    structureHash: identity.structureHash,
    mappingContractHash: identity.mappingContractHash,
    parser: identity.ir.source.parser || imported.parser || '',
    source: String(source || ''),
    template: cloneJsonValueServer(identity.ir.template, {}),
    structure: cloneJsonValueServer(identity.ir.elements, {}),
    classes: cloneJsonValueServer(identity.ir.classes, []),
    sourceUpdatedAt: new Date().toISOString()
  };
  synchronizeD2Authoring(next, diagram.authoring.d2Import);
  if (mappingWasValidated) {
    diagram.authoring.d2Import = withDiagramImportMappingInputRevision(next, diagram.authoring.d2Import);
    diagram.authoring.d2Import.mappingValidation = {
      version: 1,
      status: 'valid',
      signature: signDiagramImportMappingValidation(diagram.authoring.d2Import)
    };
  } else {
    diagram.authoring.d2Import.mappingValidation = { version: 1, status: 'needsValidation' };
  }
  const errors = validateTemplateSpecForStorage(next);
  if (errors.length) {
    const error = new Error('Updated D2 source produced an invalid deterministic template spec.');
    error.code = 'diagram_import_invalid_spec';
    error.statusCode = 422;
    error.details = errors;
    throw error;
  }
  return next;
}

function completeDiagramImportV3FromSpec(proposal, assistantSpec) {
  const next = cloneJsonValueServer(proposal, {});
  const diagram = assistantSpec && assistantSpec.result && Array.isArray(assistantSpec.result.diagrams)
    ? assistantSpec.result.diagrams.find((item) => item && typeof item === 'object' && !Array.isArray(item)) || {}
    : {};
  const imported = diagram.authoring && diagram.authoring.d2Import && diagram.authoring.d2Import.version === 3
    ? diagram.authoring.d2Import
    : {};
  const suggestedMappings = new Map((Array.isArray(imported.placementMappings) ? imported.placementMappings : [])
    .map((mapping) => [String(mapping && mapping.structureItemId || ''), mapping]).filter(([itemId]) => itemId));
  next.roles = (next.roles || []).map((role) => ({ ...role }));
  if (Array.isArray(imported.relationRules)) next.relationRules = cloneJsonValueServer(imported.relationRules, []);
  const importedTree = imported.structureTree && typeof imported.structureTree === 'object' && !Array.isArray(imported.structureTree) &&
    Number(imported.structureTree.version || 0) === D2_IMPORT_STRUCTURE_TREE_VERSION && Array.isArray(imported.structureTree.items)
    ? diagramImportStructureTree(imported.structureTree, next.structure, next.roles)
    : null;
  if (importedTree && suggestedMappings.size) {
    const roleById = new Map((next.roles || []).map((role) => [String(role && role.id || ''), role]));
    importedTree.items = importedTree.items.map((item) => {
      const role = roleById.get(String(item && item.roleId || '')) || {};
      const suggestion = suggestedMappings.get(String(item && item.id || ''));
      if (!suggestion) return item;
      const mapping = diagramImportStructureItemMapping(role, {
        ...cloneJsonValueServer(suggestion.mapping || suggestion, {}),
        id: item && item.mapping && item.mapping.id || ''
      }, item.id);
      return { ...item, mapping };
    });
  }
  next.structureTree = importedTree;
  next.unresolved = diagramImportV3Unresolved(next.roles, next.relationRules, next.structureTree, assistantSpec || {}, next.structure);
  if (!suggestedMappings.size) next.warnings = uniqueStrings([...(next.warnings || []), 'Assistant returned no D2 placement mapping suggestions; manual catalog mapping is still required.']);
  return next;
}

async function analyzeD2ImportSource(source, currentSpec, options = {}) {
  const text = String(source || '');
  const inputBytes = Buffer.byteLength(text, 'utf8');
  if (!text.trim()) {
    const error = new Error('D2 source is required.');
    error.statusCode = 400;
    throw error;
  }
  if (inputBytes > D2_IMPORT_MAX_INPUT_BYTES) {
    const error = new Error(`D2 import source exceeded configured maxInputBytes=${D2_IMPORT_MAX_INPUT_BYTES}.`);
    error.code = 'd2_import_input_limit';
    error.statusCode = 413;
    throw error;
  }
  const result = await runD2ImportProcess(text);
  if (!result.ok) {
    const error = new Error(result.error || 'D2 import failed.');
    error.code = `d2_import_${result.reason || 'failed'}`;
    error.statusCode = result.reason === 'output_limit' ? 413 : 422;
    throw error;
  }
  let parsed;
  try {
    parsed = JSON.parse(result.stdout);
  } catch {
    const error = new Error('D2 import helper returned invalid JSON.');
    error.code = 'd2_import_invalid_output';
    error.statusCode = 502;
    throw error;
  }
  const sourceErrors = parsed && parsed.source && Array.isArray(parsed.source.errors) ? parsed.source.errors : [];
  if (sourceErrors.length) {
    const first = sourceErrors[0] || {};
    const error = new Error(first.message || 'D2 import source is invalid.');
    error.code = `d2_import_${first.code || 'source_error'}`;
    error.statusCode = first.code === 'input_limit_exceeded' || first.code === 'element_limit_exceeded' ? 413 : 422;
    error.details = sourceErrors;
    throw error;
  }
  const ir = normalizeDiagramImportIr(parsed, text);
  return {
    ir,
    proposal: createDiagramImportProposal(currentSpec, ir, { ...options, sourceText: text }),
    diagnostics: {
      elapsedMs: result.elapsedMs,
      inputBytes,
      elements: Object.values(ir.elements).reduce((count, items) => count + items.length, 0)
    }
  };
}

async function restoreD2AnalysisCheckpoint(source, currentSpec, checkpoint, options = {}) {
  const restoredCheckpoint = normalizeD2AnalysisCheckpoint(checkpoint);
  if (!restoredCheckpoint) {
    const error = new Error('Saved D2 analysis checkpoint is incomplete. Analyze the current D2 source again.');
    error.code = 'd2_import_analysis_checkpoint_invalid';
    error.statusCode = 409;
    throw error;
  }
  const currentSource = String(source || '');
  const currentSourceHash = sha256Hex(currentSource);
  const currentSpecHash = diagramImportDeterministicSpecHash(currentSpec || {});
  if (restoredCheckpoint.source.hash !== currentSourceHash) {
    const error = new Error('D2 source changed after the saved deterministic analysis. Analyze the current source again.');
    error.code = 'd2_import_analysis_checkpoint_source_conflict';
    error.statusCode = 409;
    throw error;
  }
  if (restoredCheckpoint.deterministicSpecHash !== currentSpecHash) {
    const error = new Error('Deterministic template configuration changed after the saved D2 analysis. Analyze the current D2 source again.');
    error.code = 'd2_import_analysis_checkpoint_spec_conflict';
    error.statusCode = 409;
    throw error;
  }
  const analyzed = await analyzeD2ImportSource(currentSource, currentSpec, options);
  if (String(analyzed.ir.source.structureHash || '') !== restoredCheckpoint.source.structureHash ||
    String(analyzed.ir.source.mappingContractHash || '') !== restoredCheckpoint.source.mappingContractHash) {
    const error = new Error('D2 structure or mapping contract changed after the saved deterministic analysis. Analyze the current source again.');
    error.code = 'd2_import_analysis_checkpoint_contract_conflict';
    error.statusCode = 409;
    throw error;
  }
  const proposal = diagramImportV3WithOverrides(
    analyzed.proposal,
    restoredCheckpoint.roles,
    restoredCheckpoint.relationRules,
    restoredCheckpoint.structureTree,
    currentSpec
  );
  proposal.proposalId = restoredCheckpoint.proposalId;
  proposal.unresolved = diagramImportV3Unresolved(proposal.roles, proposal.relationRules, proposal.structureTree, currentSpec, proposal.structure);
  proposal.warnings = uniqueStrings(proposal.warnings || []);
  return {
    ...analyzed,
    proposal,
    restoreKind: 'analysis',
    interpretation: {},
    mapping: {}
  };
}

function restoreD2AssistantCheckpointOverlay(restoredAnalysis, currentSpec, checkpoint) {
  const restoredCheckpoint = normalizeD2AssistantCheckpoint(checkpoint);
  if (!restoredCheckpoint) {
    const error = new Error('Saved D2 Assistant result is incomplete. The deterministic D2 analysis was restored.');
    error.code = 'd2_import_assistant_checkpoint_invalid';
    throw error;
  }
  const proposal = restoredAnalysis && restoredAnalysis.proposal;
  if (!proposal || proposal.version !== 3) {
    const error = new Error('Deterministic D2 analysis is unavailable for the saved Assistant result.');
    error.code = 'd2_import_assistant_checkpoint_analysis_missing';
    throw error;
  }
  if (restoredCheckpoint.deterministicSpecHash !== String(proposal.deterministicSpecHash || '') ||
    restoredCheckpoint.source.hash !== String(proposal.source && proposal.source.hash || '') ||
    restoredCheckpoint.source.structureHash !== String(proposal.source && proposal.source.structureHash || '') ||
    restoredCheckpoint.source.mappingContractHash !== String(proposal.source && proposal.source.mappingContractHash || '')) {
    const error = new Error('Saved Assistant result belongs to a different D2 analysis. The deterministic D2 analysis was restored.');
    error.code = 'd2_import_assistant_checkpoint_analysis_conflict';
    throw error;
  }
  const nextProposal = diagramImportV3WithOverrides(
    proposal,
    restoredCheckpoint.roles,
    restoredCheckpoint.relationRules,
    restoredCheckpoint.structureTree,
    currentSpec
  );
  nextProposal.proposalId = restoredCheckpoint.proposalId;
  nextProposal.unresolved = diagramImportV3Unresolved(nextProposal.roles, nextProposal.relationRules, nextProposal.structureTree, currentSpec, nextProposal.structure);
  nextProposal.warnings = uniqueStrings(nextProposal.warnings || []);
  return {
    ...restoredAnalysis,
    proposal: nextProposal,
    restoreKind: 'assistant',
    interpretation: cloneJsonValueServer(restoredCheckpoint.interpretation, {}),
    mapping: cloneJsonValueServer(restoredCheckpoint.mapping, {})
  };
}

async function d2ImportIrForRender(source) {
  const result = await runD2ImportProcess(source);
  if (!result.ok) return { ok: false, reason: result.reason || 'failed', error: result.error || 'D2 import failed.' };
  let parsed;
  try {
    parsed = JSON.parse(result.stdout);
  } catch {
    return { ok: false, reason: 'invalid_output', error: 'D2 import helper returned invalid JSON.' };
  }
  const sourceErrors = parsed && parsed.source && Array.isArray(parsed.source.errors) ? parsed.source.errors : [];
  if (sourceErrors.length) {
    const first = sourceErrors[0] || {};
    return { ok: false, reason: first.code || 'source_error', error: first.message || 'D2 import source is invalid.' };
  }
  try {
    return { ok: true, ir: normalizeDiagramImportIr(parsed, source) };
  } catch (error) {
    return { ok: false, reason: error && error.code || 'normalize_error', error: error && error.message ? error.message : String(error) };
  }
}

function d2MarkdownFrameColor(value) {
  const color = String(value || '').trim();
  return /^(?:#[0-9a-f]{3,8}|[a-z]{1,32}|(?:rgb|rgba|hsl|hsla)\([0-9.%\s,]+\))$/i.test(color) ? color : '';
}

function d2MarkdownFrameNumber(value, max = 10_000) {
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 && number <= max ? String(number) : '';
}

function d2MarkdownFrameAttributes(style) {
  const source = style && typeof style === 'object' && !Array.isArray(style) ? style : {};
  const fill = d2MarkdownFrameColor(source.fill);
  const stroke = d2MarkdownFrameColor(source.stroke);
  if (!fill && !stroke) return '';
  const attributes = ['data-cmdp-d2-markdown-frame="true"'];
  attributes.push(`fill="${fill || 'none'}"`);
  attributes.push(`stroke="${stroke || 'none'}"`);
  const strokeWidth = d2MarkdownFrameNumber(source['stroke-width'], 100);
  if (strokeWidth) attributes.push(`stroke-width="${strokeWidth}"`);
  const radius = d2MarkdownFrameNumber(source['border-radius']);
  if (radius) attributes.push(`rx="${radius}"`);
  const dash = d2MarkdownFrameNumber(source['stroke-dash']);
  if (dash && stroke) {
    const dashLength = Number(dash) * 2;
    attributes.push(`stroke-dasharray="${dashLength},${dashLength}"`);
  }
  return attributes.join(' ');
}

function d2SvgNumericAttributes(rawAttributes) {
  const source = String(rawAttributes || '');
  const values = {};
  for (const name of ['x', 'y', 'width', 'height']) {
    const match = source.match(new RegExp(`\\b${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s>]+))`, 'i'));
    const value = String(match && (match[1] || match[2] || match[3]) || '');
    if (!/^-?\d+(?:\.\d+)?$/.test(value)) return null;
    values[name] = value;
  }
  return Number(values.width) > 0 && Number(values.height) > 0 ? values : null;
}

function escapeD2SvgRegex(value) {
  return String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function decorateD2MarkdownFrames(svg, importIr) {
  const nodes = importIr && importIr.elements && Array.isArray(importIr.elements.nodes) ? importIr.elements.nodes : [];
  let output = String(svg || '');
  let decorated = 0;
  for (const node of nodes) {
    const shape = String(node && node.styleHints && node.styleHints.shape || node && node.kind || '').toLowerCase();
    const frameAttributes = d2MarkdownFrameAttributes(node && node.styleHints && node.styleHints.style);
    if (shape !== 'text' || !frameAttributes || !node || !node.key) continue;
    const encodedKey = Buffer.from(String(node.key), 'utf8').toString('base64');
    const token = escapeD2SvgRegex(encodedKey);
    const pattern = new RegExp(
      `(<g\\b(?=[^>]*\\bclass\\s*=\\s*(?:"[^"]*${token}[^"]*"|'[^']*${token}[^']*'))[^>]*>\\s*<g\\b(?=[^>]*\\bclass\\s*=\\s*(?:"[^"]*\\bshape\\b[^"]*"|'[^']*\\bshape\\b[^']*'))[^>]*>)\\s*</g>(\\s*<g>\\s*<foreignObject\\b([^>]*)>[\\s\\S]*?</foreignObject>\\s*</g>\\s*</g>)`,
      'i'
    );
    output = output.replace(pattern, (match, shapeOpen, tail, foreignObjectAttributes) => {
      if (match.includes('data-cmdp-d2-markdown-frame=')) return match;
      const bounds = d2SvgNumericAttributes(foreignObjectAttributes);
      if (!bounds) return match;
      decorated += 1;
      return `${shapeOpen}<rect ${frameAttributes} x="${bounds.x}" y="${bounds.y}" width="${bounds.width}" height="${bounds.height}" /></g>${tail}`;
    });
  }
  return { content: output, decorated };
}

function decorateD2InteractiveElements(svg, importIr) {
  const elements = importIr && importIr.elements ? [].concat(importIr.elements.nodes || [], importIr.elements.groups || [], importIr.elements.edges || []) : [];
  let output = String(svg || '');
  for (const element of elements) {
    const key = String(element && element.key || '').trim();
    if (!key) continue;
    const token = escapeD2SvgRegex(Buffer.from(key, 'utf8').toString('base64'));
    const pattern = new RegExp(`(<g\\b(?=[^>]*\\bclass\\s*=\\s*(?:"[^"]*${token}[^"]*"|'[^']*${token}[^']*'))[^>]*)(>)`, 'i');
    output = output.replace(pattern, (match, opening, ending) => match.includes('data-cmdp-d2-key=') ? match : `${opening} data-cmdp-d2-key="${htmlEscape(key)}" tabindex="0" role="button"${ending}`);
  }
  return output;
}

function svgContainsD2ElementKey(svg, key) {
  const normalizedKey = String(key || '').trim();
  if (!normalizedKey) return false;
  const token = escapeD2SvgRegex(Buffer.from(normalizedKey, 'utf8').toString('base64'));
  const pattern = new RegExp(`\\bclass\\s*=\\s*(?:"[^"]*${token}[^"]*"|'[^']*${token}[^']*')`, 'i');
  return pattern.test(String(svg || ''));
}

function diagramSvgExecutionContract(diagram, svg) {
  const execution = diagram && diagram.execution && typeof diagram.execution === 'object' ? diagram.execution : {};
  const items = Array.isArray(execution.items) ? execution.items : [];
  const materialized = items.filter((item) => item && item.status === 'materialized' && String(item.d2Path || '').trim());
  if (!String(svg || '').trim()) {
    return {
      status: 'notRendered',
      expected: materialized.length,
      verified: 0,
      missing: []
    };
  }
  const missing = materialized.filter((item) => !svgContainsD2ElementKey(svg, item.d2Path)).map((item) => ({
    family: String(item.family || ''),
    role: cloneJsonValueServer(item.role, {}),
    label: String(item.label || ''),
    d2Path: String(item.d2Path || '')
  }));
  return {
    status: missing.length ? 'failed' : 'verified',
    expected: materialized.length,
    verified: materialized.length - missing.length,
    missing
  };
}

function d2SvgStyleIsSafe(value) {
  const css = String(value || '');
  if (!css || /<\/?(?:style|script|iframe|object|embed)\b|@import|expression\s*\(|behavior\s*:|javascript\s*:|vbscript\s*:/i.test(css)) {
    return false;
  }
  const urls = css.matchAll(/url\(\s*(['"]?)(.*?)\1\s*\)/gi);
  for (const match of urls) {
    const reference = String(match[2] || '').trim();
    if (!reference.startsWith('#') && !/^data:application\/font-woff(?:2)?;base64,[a-z0-9+/=]+$/i.test(reference)) {
      return false;
    }
  }
  return true;
}

function sanitizeD2SvgStyles(svg, allowD2Content) {
  return String(svg || '').replace(/<style\b[^>]*>([\s\S]*?)<\/style>/gi, (_match, content) => (
    allowD2Content && d2SvgStyleIsSafe(content) ? `<style type="text/css">${content}</style>` : ''
  ));
}

function d2MarkdownAttributes(tag, rawAttributes) {
  const attributes = String(rawAttributes || '');
  const result = [];
  const classMatch = attributes.match(/\bclass\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
  const className = String(classMatch?.[1] || classMatch?.[2] || classMatch?.[3] || '').trim();
  if (className && /^[A-Za-z0-9_ -]{1,512}$/.test(className)) result.push(`class="${className}"`);
  if (tag === 'div' && /\bxmlns\s*=\s*(?:"http:\/\/www\.w3\.org\/1999\/xhtml"|'http:\/\/www\.w3\.org\/1999\/xhtml')/i.test(attributes)) {
    result.push('xmlns="http://www.w3.org/1999/xhtml"');
  }
  return result.length ? ` ${result.join(' ')}` : '';
}

function sanitizeD2MarkdownHtml(value) {
  const allowedTags = new Set(['a', 'b', 'br', 'code', 'div', 'em', 'i', 'kbd', 'li', 'ol', 'p', 'pre', 's', 'span', 'strong', 'ul']);
  return String(value || '')
    .replace(/<(script|style|iframe|object|embed|svg|math)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, '')
    .replace(/<\/?([A-Za-z][A-Za-z0-9:-]*)\b([^>]*)>/g, (match, rawTag, rawAttributes) => {
      const tag = String(rawTag || '').toLowerCase();
      if (!allowedTags.has(tag)) return '';
      if (match.startsWith('</')) return `</${tag}>`;
      return `<${tag}${d2MarkdownAttributes(tag, rawAttributes)}>`;
    });
}

function sanitizeD2ForeignObjects(svg, allowD2Content) {
  return String(svg || '').replace(/<foreignObject\b([^>]*)>([\s\S]*?)<\/foreignObject>/gi, (_match, rawAttributes, content) => {
    if (!allowD2Content) return '';
    const attributes = String(rawAttributes || '');
    const values = [];
    for (const name of ['x', 'y', 'width', 'height']) {
      const attribute = attributes.match(new RegExp(`\\b${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s>]+))`, 'i'));
      const value = String(attribute?.[1] || attribute?.[2] || attribute?.[3] || '');
      if (value && /^-?\d+(?:\.\d+)?$/.test(value)) values.push(`${name}="${value}"`);
    }
    if (values.length !== 4) return '';
    return `<foreignObject ${values.join(' ')}>${sanitizeD2MarkdownHtml(content)}</foreignObject>`;
  });
}

function sanitizeD2Svg(svg) {
  const text = String(svg || '');
  const start = text.search(/<svg[\s>]/i);
  const end = text.toLowerCase().lastIndexOf('</svg>');
  if (start < 0 || end < start) return '';
  let sanitized = text.slice(start, end + '</svg>'.length);
  const allowD2Content = /^<svg\b[^>]*\bdata-d2-version\s*=\s*(?:"[^"]+"|'[^']+'|[^\s>]+)/i.test(sanitized);
  sanitized = sanitized.replace(/<\?xml[\s\S]*?\?>/gi, '');
  sanitized = sanitized.replace(/<!doctype[\s\S]*?>/gi, '');
  sanitized = sanitized.replace(/<script\b[\s\S]*?<\/script>/gi, '');
  sanitized = sanitized.replace(/<(iframe|object|embed|animate|animateMotion|animateTransform|set|image|use|feImage)\b[\s\S]*?<\/\1>/gi, '');
  sanitized = sanitized.replace(/<(iframe|object|embed|animate|animateMotion|animateTransform|set|image|use|feImage)\b[^>]*\/?>/gi, '');
  sanitized = sanitized.replace(/\s+on[a-z]+\s*=\s*"[^"]*"/gi, '');
  sanitized = sanitized.replace(/\s+on[a-z]+\s*=\s*'[^']*'/gi, '');
  sanitized = sanitized.replace(/\s+on[a-z]+\s*=\s*[^\s>]+/gi, '');
  sanitized = sanitized.replace(/\s+(href|xlink:href|src)\s*=\s*"([^"]*)"/gi, (match, _name, value) => safeD2SvgReferenceValue(value) ? match : '');
  sanitized = sanitized.replace(/\s+(href|xlink:href|src)\s*=\s*'([^']*)'/gi, (match, _name, value) => safeD2SvgReferenceValue(value) ? match : '');
  sanitized = sanitized.replace(/\s+(href|xlink:href|src)\s*=\s*([^\s>"']*)/gi, (match, _name, value) => safeD2SvgReferenceValue(value) ? match : '');
  sanitized = sanitized.replace(/\s+style\s*=\s*"[^"]*(?:url\s*\(|expression\s*\(|@import)[^"]*"/gi, '');
  sanitized = sanitized.replace(/\s+style\s*=\s*'[^']*(?:url\s*\(|expression\s*\(|@import)[^']*'/gi, '');
  sanitized = sanitized.replace(/\s+style\s*=\s*[^\s>]*(?:url\s*\(|expression\s*\(|@import)[^\s>]*/gi, '');
  sanitized = sanitizeD2SvgStyles(sanitized, allowD2Content);
  sanitized = sanitizeD2ForeignObjects(sanitized, allowD2Content);
  sanitized = sanitized.replace(/<(?:foreignObject|style)\b[^>]*\/\s*>/gi, '');
  if (!/data-cmdp-d2-rendered=/.test(sanitized)) {
    sanitized = sanitized.replace(/<svg\b/i, '<svg data-cmdp-d2-rendered="true"');
  }
  return sanitized;
}

function d2LayoutForDiagram(diagram) {
  const layout = diagram && diagram.layout && typeof diagram.layout === 'object' && !Array.isArray(diagram.layout) ? diagram.layout : {};
  return normalizeD2Layout(layout.engine || layout.d2Layout || layout.layout || D2_LAYOUT);
}

function d2CompilerNewlineOnly(line) {
  if (String(line).endsWith('\r\n')) return '\r\n';
  return String(line).endsWith('\n') ? '\n' : '';
}

function d2CompilerCodeLine(scanner, line) {
  let code = '';
  for (const character of String(line)) {
    if (scanner.quoted) {
      code += ' ';
      if (scanner.escaped) {
        scanner.escaped = false;
      } else if (character === '\\') {
        scanner.escaped = true;
      } else if (character === '"') {
        scanner.quoted = false;
      }
      continue;
    }
    if (character === '#') break;
    if (character === '"') {
      scanner.quoted = true;
      scanner.escaped = false;
      code += ' ';
      continue;
    }
    code += character;
  }
  return code;
}

function d2CompilerField(code) {
  const separator = String(code).indexOf(':');
  if (separator <= 0) return null;
  const name = String(code).slice(0, separator).trim();
  if (!name || /[{};]/.test(name)) return null;
  return { name, value: String(code).slice(separator + 1).trim() };
}

function d2CompilerBraceDelta(code) {
  let depth = 0;
  for (const character of String(code)) {
    if (character === '{') depth += 1;
    else if (character === '}') depth -= 1;
  }
  return depth;
}

// Notes are authoring metadata inside classes.<role>; D2 v0.7.1 does not
// accept them in the renderer input. Preserve every newline so renderer error
// locations still point at the user's original source. This mirrors the
// importer semantics for quoted literals, comments, and Markdown blocks.
function d2SourceForCompiler(source) {
  const lines = String(source || '').split(/(?<=\n)/);
  const output = [];
  const scanner = { escaped: false, markdown: false, quoted: false };
  let depth = 0;
  let classesDepth = -1;
  let classDepth = -1;
  let classKey = '';
  let strippingNotes = false;
  for (const line of lines) {
    if (strippingNotes) {
      output.push(d2CompilerNewlineOnly(line));
      if (String(line).trim() === '|') strippingNotes = false;
      continue;
    }
    if (scanner.markdown) {
      output.push(line);
      if (String(line).trim() === '|') scanner.markdown = false;
      continue;
    }

    const code = d2CompilerCodeLine(scanner, line);
    const field = d2CompilerField(code);
    if (classesDepth < 0 && field && field.name === 'classes' && field.value.startsWith('{')) {
      classesDepth = depth + 1;
    }
    if (classesDepth >= 0 && depth === classesDepth && field && field.value.startsWith('{')) {
      classKey = field.name;
      classDepth = depth + 1;
    }
    if (classKey && depth === classDepth && field && field.name.toLowerCase() === 'notes' && field.value.startsWith('|')) {
      strippingNotes = true;
      output.push(d2CompilerNewlineOnly(line));
      continue;
    }

    output.push(line);
    if (field && field.value.startsWith('|')) scanner.markdown = true;
    depth += d2CompilerBraceDelta(code);
    if (classKey && depth < classDepth) {
      classKey = '';
      classDepth = -1;
    }
    if (classesDepth >= 0 && depth < classesDepth) classesDepth = -1;
  }
  return output.join('');
}

async function renderD2SourceToSvg(source, diagram = {}) {
  const config = d2RendererConfig();
  if (!config.enabled) {
    return d2RenderError('disabled', 'D2 renderer is disabled by CMDP_D2_RENDER_ENABLED=false.');
  }
  const d2Source = String(source || '');
  const inputBytes = Buffer.byteLength(d2Source, 'utf8');
  if (!d2Source.trim()) {
    return d2RenderError('empty_source', 'D2 source is empty.');
  }
  if (inputBytes > config.maxInputBytes) {
    return d2RenderError('input_limit', `D2 source exceeded ${config.maxInputBytes} bytes.`, { inputBytes });
  }

  const layout = d2LayoutForDiagram(diagram);
  const result = await runD2Process([`--layout=${layout}`, '-', '-'], d2SourceForCompiler(d2Source), config);
  observeMetricSeconds('cmdp_d2_render_seconds', { layout }, result.elapsedMs / 1000);
  if (!result.ok) {
    incMetric('cmdp_d2_render_errors_total', { reason: result.reason || 'unknown' });
    logWarn('d2.render_failed', {
      requestId: currentRequestId(),
      reason: result.reason || 'unknown',
      binaryConfigured: Boolean(config.binary),
      layout,
      elapsedMs: result.elapsedMs,
      inputBytes,
      exitCode: result.exitCode == null ? undefined : result.exitCode,
      signal: result.signal || undefined
    });
    return d2RenderError(result.reason || 'render_failed', result.error || D2_RENDERER_UNAVAILABLE_TEXT, {
      layout,
      inputBytes
    });
  }

  let renderedSvg = result.stdout;
  if (/<foreignObject\b/i.test(renderedSvg)) {
    const imported = await d2ImportIrForRender(d2Source);
    if (!imported.ok) {
      incMetric('cmdp_d2_render_errors_total', { reason: 'markdown_frame_import' });
      logWarn('d2.markdown_frame_import_failed', {
        requestId: currentRequestId(),
        reason: imported.reason,
        elapsedMs: result.elapsedMs,
        inputBytes
      });
      return d2RenderError('markdown_frame_import', `D2 Markdown frame preparation failed: ${imported.error}`, {
        layout,
        inputBytes
      });
    }
    renderedSvg = decorateD2MarkdownFrames(renderedSvg, imported.ir).content;
  }

  const content = sanitizeD2Svg(renderedSvg);
  if (!content) {
    incMetric('cmdp_d2_render_errors_total', { reason: 'invalid_svg' });
    return d2RenderError('invalid_svg', 'D2 renderer did not return a valid SVG document.', {
      layout,
      inputBytes
    });
  }
  return {
    rendered: true,
    content,
    renderError: '',
    reason: 'ok',
    layout,
    inputBytes,
    outputBytes: Buffer.byteLength(content, 'utf8')
  };
}

async function renderD2ImportPreview(source) {
  const rendered = await renderD2SourceToSvg(source, {});
  const imported = rendered.rendered ? await d2ImportIrForRender(source) : null;
  return {
    rendered: Boolean(rendered.rendered),
    content: rendered.rendered ? decorateD2InteractiveElements(String(rendered.content || ''), imported && imported.ok ? imported.ir : null) : '',
    reason: rendered.reason || (rendered.rendered ? 'ok' : 'render_failed'),
    renderError: rendered.rendered ? '' : String(rendered.renderError || D2_RENDERER_UNAVAILABLE_TEXT),
    layout: rendered.layout || normalizeD2Layout(D2_LAYOUT)
  };
}

async function renderD2ArtifactsForDiagrams(diagrams) {
  if (!Array.isArray(diagrams) || !diagrams.length) return diagrams;
  const config = d2RendererConfig();
  const renderable = diagrams
    .map((diagram, index) => ({ diagram, index }))
    .filter(({ diagram }) => diagram && diagram.d2 && typeof diagram.d2.source === 'string' && diagram.d2.source.trim());
  const renderOptionsHash = hashJson(d2CacheContext());
  const overflow = renderable.slice(config.maxDiagrams);
  overflow.forEach(({ diagram }) => {
    const warnings = Array.isArray(diagram.warnings) ? diagram.warnings.slice() : [];
    warnings.push(`D2 render limit reached: rendered at most ${config.maxDiagrams} diagrams. This diagram was left as source-only.`);
    diagram.warnings = Array.from(new Set(warnings));
    diagram.svg = Object.assign({}, diagram.svg || {}, {
      content: '',
      rendered: false,
      renderError: '',
      renderReason: 'render_limit',
      renderer: 'd2',
      layout: d2LayoutForDiagram(diagram),
      metadataEmbedded: false
    });
    diagram.d2 = Object.assign({}, diagram.d2, {
      renderOptionsHash
    });
    if (diagram.execution && typeof diagram.execution === 'object') {
      diagram.execution.svgContract = diagramSvgExecutionContract(diagram, '');
    }
  });
  const queue = renderable.slice(0, config.maxDiagrams);
  let cursor = 0;
  async function next() {
    while (cursor < queue.length) {
      const current = queue[cursor];
      cursor += 1;
      const diagram = current.diagram;
      if (!diagram || !diagram.d2 || typeof diagram.d2.source !== 'string' || !diagram.d2.source.trim()) continue;
      const rendered = await renderD2SourceToSvg(diagram.d2.source, diagram);
      const embeddedSvg = rendered.rendered
        ? embedDiagramSvgMetadata(rendered.content || '', diagram.svg && diagram.svg.metadata)
        : { content: rendered.content || '', embedded: false };
      diagram.svg = Object.assign({}, diagram.svg || {}, {
        content: embeddedSvg.content,
        rendered: Boolean(rendered.rendered),
        renderError: rendered.rendered ? '' : rendered.renderError,
        renderReason: rendered.reason || '',
        renderer: 'd2',
        layout: rendered.layout || d2LayoutForDiagram(diagram),
        metadataEmbedded: embeddedSvg.embedded
      });
      diagram.d2 = Object.assign({}, diagram.d2, {
        renderOptionsHash
      });
      if (diagram.execution && typeof diagram.execution === 'object') {
        const contract = diagramSvgExecutionContract(diagram, embeddedSvg.content);
        diagram.execution.svgContract = contract;
        if (contract.status === 'failed') {
          const warnings = Array.isArray(diagram.warnings) ? diagram.warnings.slice() : [];
          warnings.push(`D2 SVG contract failed: ${contract.missing.length} materialized element(s) are absent from the rendered SVG.`);
          diagram.warnings = Array.from(new Set(warnings));
          logWarn('d2.svg_contract_violation', {
            diagram: String(diagram.name || ''),
            sourceHash: String(diagram.d2 && diagram.d2.sourceHash || ''),
            missing: contract.missing.length,
            roles: uniqueStrings(contract.missing.map((item) => String(item.role && item.role.key || '')).filter(Boolean))
          });
        }
      }
      if (!rendered.rendered) {
        const warnings = Array.isArray(diagram.warnings) ? diagram.warnings.slice() : [];
        warnings.push(D2_RENDERER_UNAVAILABLE_TEXT);
        if (rendered.renderError) warnings.push(`D2 render error: ${rendered.renderError}`);
        diagram.warnings = Array.from(new Set(warnings));
      }
    }
  }
  const workers = Array.from({ length: Math.min(config.concurrency, queue.length) }, () => next());
  await Promise.all(workers);
  return diagrams;
}

let d2HealthCache = { checkedAt: 0, payload: null };
let d2ImportHealthCache = { checkedAt: 0, payload: null };

async function d2RendererHealth({ force = false } = {}) {
  const config = d2RendererConfig();
  if (!config.enabled) {
    return {
      required: false,
      enabled: false,
      ok: true,
      status: 'disabled',
      binary: config.binary
    };
  }
  const now = Date.now();
  if (!force && d2HealthCache.payload && now - d2HealthCache.checkedAt < 15000) {
    return d2HealthCache.payload;
  }
  const result = await runD2Process(['--version'], '', {
    timeoutMs: Math.min(config.timeoutMs, 1500),
    maxOutputBytes: 4096
  });
  const payload = {
    required: true,
    enabled: true,
    ok: Boolean(result.ok),
    status: result.ok ? 'ok' : 'unavailable',
    binary: config.binary,
    version: result.ok ? truncateText((result.stdout || '').trim(), 120) : '',
    error: result.ok ? '' : truncateText(result.error || result.stderr || 'D2 renderer is unavailable.', 300),
    reason: result.reason || '',
    latencyMs: result.elapsedMs
  };
  d2HealthCache = { checkedAt: now, payload };
  return payload;
}

async function d2ImporterHealth({ force = false } = {}) {
  const now = Date.now();
  if (!force && d2ImportHealthCache.payload && now - d2ImportHealthCache.checkedAt < 15000) return d2ImportHealthCache.payload;
  const result = await runD2ImportProcess('health: Health\n', {
    timeoutMs: Math.min(D2_IMPORT_TIMEOUT_MS, 1500),
    maxOutputBytes: 64 * 1024
  });
  let parsed = null;
  try { parsed = result.ok ? JSON.parse(result.stdout) : null; } catch { parsed = null; }
  const errors = parsed && parsed.source && Array.isArray(parsed.source.errors) ? parsed.source.errors : [];
  const ok = Boolean(result.ok && parsed && parsed.version >= 4 && errors.length === 0);
  const payload = {
    required: true,
    ok,
    status: ok ? 'ok' : 'unavailable',
    binary: D2_IMPORT_BINARY,
    parser: parsed && parsed.source && (parsed.source.parser || parsed.source.parserVersion) || 'd2-v0.7.1',
    error: ok ? '' : truncateText(result.error || errors[0] && errors[0].message || 'D2 importer is unavailable.', 300),
    reason: result.reason || '',
    latencyMs: result.elapsedMs
  };
  d2ImportHealthCache = { checkedAt: now, payload };
  return payload;
}

function readSecretValue(value, filePath) {
  if (filePath) return fs.readFileSync(filePath, 'utf8').trim();
  return String(value || '');
}

function readOptionalSecretValue(value, filePath) {
  const directValue = String(value || '').trim();
  if (directValue) return { value: directValue, state: 'configured', errorCode: '' };
  const path = String(filePath || '').trim();
  if (!path) return { value: '', state: 'missing', errorCode: '' };
  try {
    const fileValue = fs.readFileSync(path, 'utf8').trim();
    return fileValue
      ? { value: fileValue, state: 'configured', errorCode: '' }
      : { value: '', state: 'missing', errorCode: '' };
  } catch (error) {
    const code = String(error && error.code || '').trim();
    if (code === 'ENOENT') return { value: '', state: 'missing', errorCode: '' };
    return {
      value: '',
      state: 'invalid_file',
      errorCode: code || 'read_failed'
    };
  }
}

function parseRedisUrl(value) {
  const parsed = new URL(value || 'redis://127.0.0.1:6379/0');
  if (!['redis:', 'rediss:'].includes(parsed.protocol)) {
    throw new Error('Redis URL must use redis:// or rediss://.');
  }
  const dbText = parsed.pathname && parsed.pathname !== '/' ? parsed.pathname.slice(1) : '0';
  return {
    host: parsed.hostname || '127.0.0.1',
    port: Number(parsed.port || 6379),
    password: REDIS_PASSWORD || (parsed.password ? decodeURIComponent(parsed.password) : ''),
    db: Number.isInteger(Number(dbText)) ? Number(dbText) : 0,
    tls: parsed.protocol === 'rediss:',
    tlsCaFile: REDIS_TLS_CA_FILE
  };
}

function redisTransportSecurity(value = REDIS_URL) {
  try {
    const config = parseRedisUrl(value);
    return {
      transport: config.tls ? 'tls' : 'plaintext',
      caConfigured: Boolean(config.tlsCaFile)
    };
  } catch {
    return {
      transport: 'invalid',
      caConfigured: false
    };
  }
}

function sanitizeRedisUrl(value) {
  try {
    const parsed = new URL(value || 'redis://127.0.0.1:6379/0');
    if (parsed.password || REDIS_PASSWORD) parsed.password = '***';
    return parsed.toString();
  } catch {
    return REDIS_PASSWORD ? 'redis://:***@invalid-url' : String(value || '');
  }
}

function encodeRedisCommand(parts) {
  const chunks = [`*${parts.length}\r\n`];
  for (const part of parts) {
    const value = Buffer.from(String(part === undefined || part === null ? '' : part));
    chunks.push(`$${value.length}\r\n`, value, '\r\n');
  }
  return Buffer.concat(chunks.map((chunk) => Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)));
}

function redisLineEnd(buffer, offset) {
  for (let index = offset; index < buffer.length - 1; index += 1) {
    if (buffer[index] === 13 && buffer[index + 1] === 10) return index;
  }
  return -1;
}

function parseRedisReply(buffer, offset = 0) {
  if (offset >= buffer.length) return null;
  const type = String.fromCharCode(buffer[offset]);
  const lineEnd = redisLineEnd(buffer, offset + 1);
  if (lineEnd === -1) return null;
  const line = buffer.toString('utf8', offset + 1, lineEnd);
  const nextOffset = lineEnd + 2;
  if (type === '+') return { value: line, offset: nextOffset };
  if (type === '-') {
    const error = new Error(`Redis error: ${line}`);
    error.redisError = true;
    throw error;
  }
  if (type === ':') return { value: Number(line), offset: nextOffset };
  if (type === '$') {
    const length = Number(line);
    if (length === -1) return { value: null, offset: nextOffset };
    const end = nextOffset + length;
    if (buffer.length < end + 2) return null;
    return { value: buffer.toString('utf8', nextOffset, end), offset: end + 2 };
  }
  if (type === '*') {
    const count = Number(line);
    if (count === -1) return { value: null, offset: nextOffset };
    const values = [];
    let currentOffset = nextOffset;
    for (let index = 0; index < count; index += 1) {
      const parsed = parseRedisReply(buffer, currentOffset);
      if (!parsed) return null;
      values.push(parsed.value);
      currentOffset = parsed.offset;
    }
    return { value: values, offset: currentOffset };
  }
  throw new Error(`Unsupported Redis reply type: ${type}`);
}

async function redisCommand(parts, options = {}) {
  if (!REDIS_ENABLED) {
    incMetric('cmdp_redis_errors_total', { reason: 'disabled' });
    throw new Error('Redis is disabled.');
  }
  const now = Date.now();
  if (!options.force && redisState.disabledUntil && redisState.disabledUntil > now) {
    incMetric('cmdp_redis_errors_total', { reason: 'temporarily_unavailable' });
    throw new Error(redisState.lastError || 'Redis is temporarily unavailable.');
  }
  const config = parseRedisUrl(REDIS_URL);
  let tlsOptions = null;
  if (config.tls) {
    try {
      tlsOptions = {
        host: config.host,
        port: config.port,
        ...(net.isIP(config.host) ? {} : { servername: config.host }),
        ...(config.tlsCaFile ? { ca: fs.readFileSync(config.tlsCaFile, 'utf8') } : {})
      };
    } catch (error) {
      throw new Error(`Redis TLS CA file is not readable: ${error && error.code ? error.code : 'read_failed'}.`);
    }
  }
  const commands = [];
  if (config.password) commands.push(['AUTH', config.password]);
  if (config.db) commands.push(['SELECT', config.db]);
  commands.push(parts);
  return await new Promise((resolve, reject) => {
    let settled = false;
    let buffer = Buffer.alloc(0);
    const socket = config.tls
      ? tls.connect(tlsOptions)
      : net.createConnection({ host: config.host, port: config.port });
    const timer = setTimeout(() => {
      socket.destroy();
      finish(new Error(`Redis command timed out after ${REDIS_TIMEOUT_MS}ms.`));
    }, REDIS_TIMEOUT_MS);
    function finish(error, value) {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      socket.destroy();
      if (error) {
        incMetric('cmdp_redis_errors_total', { reason: 'command_failed' });
        const previousAvailable = redisState.available;
        const previousError = redisState.lastError;
        redisState.available = false;
        redisState.lastError = error.message || String(error);
        redisState.lastCheckedAt = new Date().toISOString();
        redisState.disabledUntil = Date.now() + REDIS_RETRY_AFTER_MS;
        if (previousAvailable !== false || previousError !== redisState.lastError) {
          logWarn('redis.unavailable', {
            backend: 'memory',
            url: sanitizeRedisUrl(REDIS_URL),
            retryAfterMs: REDIS_RETRY_AFTER_MS,
            error: redisState.lastError
          });
        }
        reject(error);
      } else {
        const wasUnavailable = redisState.available === false;
        redisState.available = true;
        redisState.lastError = '';
        redisState.lastCheckedAt = new Date().toISOString();
        redisState.disabledUntil = 0;
        if (wasUnavailable) {
          logInfo('redis.available', {
            backend: 'redis',
            url: sanitizeRedisUrl(REDIS_URL)
          });
        }
        resolve(value);
      }
    }
    socket.on(config.tls ? 'secureConnect' : 'connect', () => {
      commands.forEach((command) => socket.write(encodeRedisCommand(command)));
    });
    socket.on('data', (chunk) => {
      try {
        buffer = Buffer.concat([buffer, chunk]);
        let offset = 0;
        const replies = [];
        while (replies.length < commands.length) {
          const parsed = parseRedisReply(buffer, offset);
          if (!parsed) return;
          replies.push(parsed.value);
          offset = parsed.offset;
        }
        finish(null, replies[replies.length - 1]);
      } catch (error) {
        finish(error);
      }
    });
    socket.on('error', finish);
  });
}

function cacheKey(namespace, key) {
  return `${REDIS_KEY_PREFIX}:${namespace}:${key}`;
}

function redisRequiredError(error, operation, namespace) {
  const message = error && error.message ? error.message : String(error || 'Redis is unavailable.');
  const next = new Error(`Redis is required for ${namespace} cache ${operation}, but Redis is unavailable: ${message}`);
  next.statusCode = 503;
  next.redisRequired = true;
  return next;
}

function memoryGet(map, key) {
  const entry = map.get(key);
  if (!entry) return null;
  if (entry.expiresAt && entry.expiresAt <= Date.now()) {
    map.delete(key);
    return null;
  }
  return cloneJsonValueServer(entry.value, null);
}

function memorySet(map, key, value, ttlMs) {
  map.set(key, {
    value: cloneJsonValueServer(value, null),
    expiresAt: ttlMs ? Date.now() + ttlMs : 0
  });
  while (map.size > RUNTIME_CACHE_MAX_ENTRIES) {
    const firstKey = map.keys().next().value;
    if (!firstKey) break;
    map.delete(firstKey);
  }
}

async function cacheGetJson(namespace, key, memoryMap) {
  if (REDIS_ENABLED) {
    try {
      const value = await redisCommand(['GET', cacheKey(namespace, key)]);
      if (value) {
        if (namespace === 'runtime') incMetric('cmdp_runtime_cache_hits_total', { backend: 'redis' });
        return { backend: 'redis', value: JSON.parse(value) };
      }
      if (namespace === 'runtime') incMetric('cmdp_runtime_cache_misses_total', { backend: 'redis' });
      return { backend: 'redis', value: null };
    } catch (error) {
      if (REDIS_REQUIRED) throw redisRequiredError(error, 'read', namespace);
      // Redis fallback is expected in local dev when Redis is not started.
    }
  } else if (REDIS_REQUIRED) {
    throw redisRequiredError(new Error('Redis is disabled.'), 'read', namespace);
  }
  const value = memoryGet(memoryMap, key);
  if (namespace === 'runtime') {
    incMetric(value ? 'cmdp_runtime_cache_hits_total' : 'cmdp_runtime_cache_misses_total', { backend: 'memory' });
  }
  return { backend: 'memory', value };
}

async function cacheSetJson(namespace, key, value, ttlMs, memoryMap) {
  if (REDIS_ENABLED) {
    try {
      const args = ['SET', cacheKey(namespace, key), JSON.stringify(value)];
      if (ttlMs) args.push('PX', Math.max(1, Math.floor(ttlMs)));
      await redisCommand(args);
      return 'redis';
    } catch (error) {
      if (REDIS_REQUIRED) throw redisRequiredError(error, 'write', namespace);
      // Fall through to in-memory fallback.
    }
  } else if (REDIS_REQUIRED) {
    throw redisRequiredError(new Error('Redis is disabled.'), 'write', namespace);
  }
  memorySet(memoryMap, key, value, ttlMs);
  return 'memory';
}

async function cacheDelete(namespace, key, memoryMap) {
  if (REDIS_ENABLED) {
    try {
      await redisCommand(['DEL', cacheKey(namespace, key)]);
    } catch (error) {
      if (REDIS_REQUIRED) throw redisRequiredError(error, 'delete', namespace);
      // Ignore Redis delete failures; memory fallback is still cleared.
    }
  } else if (REDIS_REQUIRED) {
    throw redisRequiredError(new Error('Redis is disabled.'), 'delete', namespace);
  }
  memoryMap.delete(key);
}

function runtimeTemplateIndexId(root, templateCode) {
  return hashJson({ root: String(root || ''), templateCode: String(templateCode || '') });
}

async function registerRuntimeTemplateCacheKey(root, templateCode, key, ttlMs) {
  const indexId = runtimeTemplateIndexId(root, templateCode);
  if (!runtimeCacheTemplateIndex.has(indexId)) runtimeCacheTemplateIndex.set(indexId, new Set());
  runtimeCacheTemplateIndex.get(indexId).add(key);
  if (!REDIS_ENABLED) return;
  const indexKey = cacheKey('runtime-index', indexId);
  try {
    await redisCommand(['SADD', indexKey, key]);
    await redisCommand(['EXPIRE', indexKey, Math.max(60, Math.ceil(Number(ttlMs || DEFAULT_TEMPLATE_CACHE_TTL_SEC * 1000) / 1000) + 60)]);
  } catch (error) {
    if (REDIS_REQUIRED) throw redisRequiredError(error, 'index', 'runtime');
  }
}

async function invalidateTemplateRuntimeCache(root, templateCode) {
  const indexId = runtimeTemplateIndexId(root, templateCode);
  const keys = new Set(runtimeCacheTemplateIndex.get(indexId) || []);
  const indexKey = cacheKey('runtime-index', indexId);
  let backend = 'memory';
  let redisError = '';
  if (REDIS_ENABLED) {
    try {
      const redisKeys = await redisCommand(['SMEMBERS', indexKey]);
      for (const key of Array.isArray(redisKeys) ? redisKeys : []) keys.add(String(key));
      for (const key of keys) await redisCommand(['DEL', cacheKey('runtime', key)]);
      await redisCommand(['DEL', indexKey]);
      backend = 'redis';
    } catch (error) {
      redisError = error && error.message ? error.message : String(error);
    }
  }
  for (const key of keys) {
    runtimeResultCache.delete(key);
    runtimeResultInFlight.delete(key);
  }
  if (redisError) runtimeCacheTemplateIndex.set(indexId, new Set(keys));
  else runtimeCacheTemplateIndex.delete(indexId);
  incMetric('cmdp_runtime_cache_invalidations_total', { backend, status: redisError ? 'partial' : 'ok' });
  if (redisError) {
    logError('runtime.cache_invalidation_failed', {
      root: truncateText(String(root || ''), 120),
      templateCode: truncateText(String(templateCode || ''), 120),
      required: REDIS_REQUIRED,
      errorName: 'redis_error'
    });
  }
  return {
    invalidated: keys.size,
    backend,
    required: REDIS_REQUIRED,
    complete: !redisError,
    error: redisError ? 'Redis cache invalidation failed.' : ''
  };
}

function staticSnapshotTemplateIndexId(root, templateCode) {
  return hashJson({ root: String(root || ''), templateCode: String(templateCode || '') });
}

async function registerStaticSnapshotCacheKey(root, templateCode, key) {
  const indexId = staticSnapshotTemplateIndexId(root, templateCode);
  if (!staticSnapshotTemplateIndex.has(indexId)) staticSnapshotTemplateIndex.set(indexId, new Set());
  staticSnapshotTemplateIndex.get(indexId).add(key);
  if (!REDIS_ENABLED) return;
  try {
    await redisCommand(['SADD', cacheKey('snapshot-index', indexId), key]);
  } catch (error) {
    if (REDIS_REQUIRED) throw redisRequiredError(error, 'index', 'snapshot');
  }
}

async function invalidateTemplateStaticSnapshots(root, templateCode) {
  const indexId = staticSnapshotTemplateIndexId(root, templateCode);
  const keys = new Set(staticSnapshotTemplateIndex.get(indexId) || []);
  const indexKey = cacheKey('snapshot-index', indexId);
  let backend = 'memory';
  let redisError = '';
  if (REDIS_ENABLED) {
    try {
      const redisKeys = await redisCommand(['SMEMBERS', indexKey]);
      for (const key of Array.isArray(redisKeys) ? redisKeys : []) keys.add(String(key));
      for (const key of keys) await redisCommand(['DEL', cacheKey('snapshot', key)]);
      await redisCommand(['DEL', indexKey]);
      backend = 'redis';
    } catch (error) {
      redisError = error && error.message ? error.message : String(error);
    }
  }
  for (const key of keys) staticSnapshotCache.delete(key);
  if (redisError) staticSnapshotTemplateIndex.set(indexId, new Set(keys));
  else staticSnapshotTemplateIndex.delete(indexId);
  incMetric('cmdp_static_snapshot_invalidations_total', { backend, status: redisError ? 'partial' : 'ok' });
  if (redisError) {
    logError('snapshot.cache_invalidation_failed', {
      root: truncateText(String(root || ''), 120),
      templateCode: truncateText(String(templateCode || ''), 120),
      required: REDIS_REQUIRED,
      errorName: 'redis_error'
    });
  }
  return {
    invalidated: keys.size,
    backend,
    required: REDIS_REQUIRED,
    complete: !redisError,
    error: redisError ? 'Redis snapshot invalidation failed.' : ''
  };
}

async function redisStatus(options = {}) {
  if (!REDIS_ENABLED) {
    return {
      enabled: false,
      required: REDIS_REQUIRED,
      backend: 'memory',
      available: false,
      url: sanitizeRedisUrl(REDIS_URL),
      transportSecurity: redisTransportSecurity(),
      keyPrefix: REDIS_KEY_PREFIX,
      message: 'Redis is disabled by CMDBDYNAMIC_REDIS_ENABLED=false.'
    };
  }
  try {
    const pong = await redisCommand(['PING'], options);
    return {
      enabled: true,
      required: REDIS_REQUIRED,
      backend: 'redis',
      available: pong === 'PONG',
      url: sanitizeRedisUrl(REDIS_URL),
      transportSecurity: redisTransportSecurity(),
      keyPrefix: REDIS_KEY_PREFIX,
      lastCheckedAt: redisState.lastCheckedAt
    };
  } catch (error) {
    return {
      enabled: true,
      required: REDIS_REQUIRED,
      backend: 'memory',
      available: false,
      url: sanitizeRedisUrl(REDIS_URL),
      transportSecurity: redisTransportSecurity(),
      keyPrefix: REDIS_KEY_PREFIX,
      lastCheckedAt: redisState.lastCheckedAt,
      error: error && error.message ? error.message : String(error)
    };
  }
}

function baseHealthPayload() {
  return {
    service: 'cmdbdynamicpages',
    timestamp: new Date().toISOString(),
    startedAt: STARTED_AT.toISOString(),
    uptimeSec: Math.floor(process.uptime()),
    pid: process.pid
  };
}

function isHealthPath(pathname) {
  return [
    '/health/live',
    '/health/ready',
    '/health/redis',
    `${BACKEND_PREFIX}/health/live`,
    `${BACKEND_PREFIX}/health/ready`,
    `${BACKEND_PREFIX}/health/redis`
  ].includes(pathname);
}

function isMetricsPath(pathname) {
  return pathname === '/metrics';
}

function healthKindFromPath(pathname) {
  if (pathname.endsWith('/live')) return 'live';
  if (pathname.endsWith('/redis')) return 'redis';
  return 'ready';
}

function checkCmdbuildUpstream() {
  const target = new URL('/cmdbuild/services/rest/v3/sessions/current', CMDBUILD_ORIGIN);
  const started = Date.now();
  return new Promise((resolve) => {
    let settled = false;
    const finish = (payload) => {
      if (settled) return;
      settled = true;
      resolve({
        url: `${target.origin}${target.pathname}`,
        latencyMs: Date.now() - started,
        ...payload
      });
    };
    const transport = httpTransportForTarget(target);
    const probeReq = transport.request({
      protocol: target.protocol,
      hostname: target.hostname,
      port: target.port,
      method: 'GET',
      path: `${target.pathname}${target.search}`,
      headers: { accept: 'application/json' },
      agent: cmdbuildAgentForTarget(target)
    }, (probeRes) => {
      probeRes.resume();
      probeRes.on('end', () => {
        const statusCode = probeRes.statusCode || 0;
        finish({
          ok: statusCode >= 200 && statusCode < 500,
          statusCode
        });
      });
    });
    probeReq.on('error', (error) => {
      finish({
        ok: false,
        statusCode: 0,
        error: error && error.message ? error.message : String(error)
      });
    });
    probeReq.setTimeout(HEALTH_TIMEOUT_MS, () => {
      probeReq.destroy(new Error(`CMDBuild health probe timed out after ${HEALTH_TIMEOUT_MS}ms.`));
    });
    probeReq.end();
  });
}

function redisHealthCheck(redis) {
  const ok = Boolean(REDIS_ENABLED && redis && redis.available);
  return {
    required: HEALTH_REDIS_REQUIRED,
    ok,
    status: ok ? 'ok' : REDIS_ENABLED ? 'unavailable' : 'disabled',
    ...redis
  };
}

async function readinessPayload() {
  const [redis, cmdbuild, d2, d2Import] = await Promise.all([
    redisStatus({ force: true }),
    checkCmdbuildUpstream(),
    d2RendererHealth(),
    d2ImporterHealth()
  ]);
  const checks = {
    process: {
      ok: true,
      status: 'ok'
    },
    redis: redisHealthCheck(redis),
    cmdbuild: {
      required: true,
      ok: Boolean(cmdbuild.ok),
      status: cmdbuild.ok ? 'ok' : 'unavailable',
      ...cmdbuild
    },
    d2: {
      ...d2
    },
    d2Import: {
      ...d2Import
    }
  };
  const ready = checks.cmdbuild.ok && (!HEALTH_REDIS_REQUIRED || checks.redis.ok) && (!checks.d2.required || checks.d2.ok) && (!checks.d2Import.required || checks.d2Import.ok);
  setMetricGauge('cmdp_health_ready', {}, ready ? 1 : 0);
  return {
    ...baseHealthPayload(),
    status: ready ? 'ready' : 'not_ready',
    ready,
    checks
  };
}

async function handleHealth(req, res, requestUrl) {
  if (!methodAllowed(req, res, 'GET')) return;
  const kind = healthKindFromPath(requestUrl.pathname);
  if (kind === 'live') {
    sendJson(res, 200, {
      ...baseHealthPayload(),
      status: 'live',
      live: true
    });
    return;
  }
  if (kind === 'redis') {
    const payload = {
      ...baseHealthPayload(),
      redis: redisHealthCheck(await redisStatus({ force: true }))
    };
    const ok = payload.redis.ok;
    payload.status = ok ? 'ok' : 'not_ready';
    sendJson(res, ok ? 200 : 503, payload);
    return;
  }
  const payload = await readinessPayload();
  sendJson(res, payload.ready ? 200 : 503, payload);
}

function cloneJsonValueServer(value, fallback = null) {
  try {
    return JSON.parse(JSON.stringify(value === undefined ? fallback : value));
  } catch {
    return fallback;
  }
}

function addUniqueString(list, value) {
  const text = String(value || '').trim();
  if (text && !list.includes(text)) list.push(text);
}

function shouldLogProxyRequest(pathname) {
  return pathname === '/cmdbuild/ui' ||
    pathname === '/cmdbuild/ui/' ||
    pathname === '/cmdbuild/ui/config.js' ||
    pathname === '/cmdbuild/ui/cmdbuild/app.js' ||
    pathname === '/cmdbuild/ui/hda/app.js' ||
    pathname.endsWith('/cmdbuild.json') ||
    pathname.endsWith('/hda.json') ||
    pathname.includes('/custompages/CmdbDynamicPages') ||
    pathname.includes('/view/custompages/CmdbDynamicPages/');
}

function isCmdbDynamicPagesScript(pathname) {
  return pathname.endsWith('/view/custompages/CmdbDynamicPages/CmdbDynamicPages.js');
}

function pathMatchesPrefix(pathname, prefix) {
  return pathname === prefix || pathname.startsWith(`${prefix}/`);
}

function isCmdbuildProxyPathAllowed(pathname, strict = PROXY_ALLOWLIST_STRICT) {
  if (!strict) return true;
  const pathText = String(pathname || '/');
  return pathText === '/cmdbuild' ||
    pathText === '/cmdbuild/' ||
    pathMatchesPrefix(pathText, '/cmdbuild/ui') ||
    pathMatchesPrefix(pathText, '/cmdbuild/services/rest');
}

function isCmdbuildUiEntry(pathname) {
  return pathname === '/cmdbuild/ui' || pathname === '/cmdbuild/ui/';
}

function isCmdbuildUiManifest(pathname) {
  return pathname === '/cmdbuild/ui/cmdbuild.json' || pathname === '/cmdbuild/ui/hda.json';
}

function isCmdbuildUiCacheSensitive(pathname) {
  return isCmdbuildUiEntry(pathname) ||
    isCmdbuildUiManifest(pathname) ||
    pathname === '/cmdbuild/ui/config.js' ||
    pathname === '/cmdbuild/ui/cmdbuild/app.js' ||
    pathname === '/cmdbuild/ui/hda/app.js' ||
    isCmdbDynamicPagesScript(pathname);
}

function logProxyRequest(req, requestUrl) {
  if (!shouldLogProxyRequest(requestUrl.pathname)) return;
  appendBoundedLog(proxyLogs, {
    time: new Date().toISOString(),
    method: req.method || '',
    path: sanitizeRequestPath(requestUrl),
    referer: sanitizeUrlForLog(req.headers.referer || '', 500),
    userAgent: truncateText(req.headers['user-agent'] || '', 200)
  });
}

function withNoStoreHeaders(headers) {
  const responseHeaders = { ...headers };
  responseHeaders['cache-control'] = 'no-store, no-cache, must-revalidate, proxy-revalidate';
  responseHeaders.pragma = 'no-cache';
  responseHeaders.expires = '0';
  delete responseHeaders.etag;
  delete responseHeaders['content-length'];
  delete responseHeaders['transfer-encoding'];
  return responseHeaders;
}

function normalizeSameSiteValue(value) {
  const text = String(value || '').trim().toLowerCase();
  if (text === 'lax') return 'Lax';
  if (text === 'strict') return 'Strict';
  if (text === 'none') return 'None';
  return '';
}

function shouldMarkProxyCookieSecure() {
  const value = String(PROXY_COOKIE_SECURE || '').trim().toLowerCase();
  return value !== 'false' && value !== '0' && value !== 'no';
}

function rewriteProxySetCookieHeader(header) {
  if (!header) return header;
  const sameSite = normalizeSameSiteValue(PROXY_COOKIE_SAMESITE);
  const secure = shouldMarkProxyCookieSecure();
  function rewriteOne(cookie) {
    const parts = String(cookie || '').split(';').map((part) => part.trim()).filter(Boolean);
    if (!parts.length) return cookie;
    const rewritten = [parts[0]];
    let hasSecure = false;
    for (const part of parts.slice(1)) {
      if (/^samesite=/i.test(part)) continue;
      if (/^secure$/i.test(part)) {
        hasSecure = true;
        rewritten.push('Secure');
        continue;
      }
      rewritten.push(part);
    }
    if (sameSite) rewritten.push(`SameSite=${sameSite}`);
    if (secure && !hasSecure) rewritten.push('Secure');
    return rewritten.join('; ');
  }
  return Array.isArray(header) ? header.map(rewriteOne) : rewriteOne(header);
}

function rewriteProxyResponseHeaders(headers) {
  const responseHeaders = { ...headers };
  if (responseHeaders['set-cookie']) {
    responseHeaders['set-cookie'] = rewriteProxySetCookieHeader(responseHeaders['set-cookie']);
  }
  return responseHeaders;
}

