    var maximum = Number(executionLimits.maxRowsMax);
    var fallback = Number(defaultRuntimeConfig().executionLimits.maxRowsDataPreviewDefault);
    var limit = Number.isInteger(configured) && configured > 0 ? configured : fallback;
